INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95358, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "由国家投资经营的。", "primary_collocate": null, "pronunciation": "guó yíng", "ipa": "kwo˧˥ jiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "国家投钱办了这家国营企业。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国营企业的工人工资比较稳定。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家国营银行在全国有很多分行。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他毕业后想进国营公司工作。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国营电视台每天播放新闻。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条铁路是国营的，由国家管理。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国营工厂生产的产品，质量都不错。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府给国营医院很多钱。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国营农场种了很多苹果。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国营企业也要学会赚钱。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "国营企业", "label": "复合"}], "register": "中性", "sense_fingerprint": "国家投资并经营的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5590457-323a-4f29-a55c-1e85319d3532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95358, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "甜", "is_correct": false, "explanation": "语义：“甜”描述味道，不能用来修饰企业。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容人或动物的身形，不能用来修饰企业。"}, {"text": "国营", "is_correct": true, "explanation": "国营指由国家投资经营，与“国家投钱办”的语境相符。"}, {"text": "私营", "is_correct": false, "explanation": "语义：“私营”指私人经营，与“国家投钱办”正相矛盾。"}], "explanations": {"甜": "语义：“甜”描述味道，不能用来修饰企业。", "瘦": "体貌：“瘦”形容人或动物的身形，不能用来修饰企业。", "国营": "国营指由国家投资经营，与“国家投钱办”的语境相符。", "私营": "语义：“私营”指私人经营，与“国家投钱办”正相矛盾。"}, "sentence_index": 0, "correct_answer": "国营"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我姐姐是国营的，她很喜欢画画。", "explanation": "这里把“国营”误用来形容人，误成了〈职业身份〉的意思。国营说的是单位由国家投资经营，不能修饰人。"}, {"text": "天上的太阳是国营的，每天都很亮。", "explanation": "这里把“国营”误用成了〈公共〉的意思。国营说的是由国家投资经营的单位，太阳不是单位。"}, {"text": "他的梦想是国营的，一直没有改变。", "explanation": "这里把“国营”误用成了〈共有〉的意思。国营只修饰由国家投资经营的单位，梦想不是单位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f92986f4-e2ef-4f74-b8c7-f309337bf38e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95358, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "悲伤", "is_correct": false, "explanation": "语义：“悲伤”形容情绪，不能用来修饰工厂，句子不通。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”形容高度，不能用来修饰工厂。"}, {"text": "国营", "is_correct": true, "explanation": "国营工厂指由国家投资经营的工厂，与句中“产品质量不错”的语境相符。"}, {"text": "辣", "is_correct": false, "explanation": "语义：“辣”形容味道，不能用来修饰工厂。"}], "explanations": {"悲伤": "语义：“悲伤”形容情绪，不能用来修饰工厂，句子不通。", "矮": "体貌：“矮”形容高度，不能用来修饰工厂。", "国营": "国营工厂指由国家投资经营的工厂，与句中“产品质量不错”的语境相符。", "辣": "语义：“辣”形容味道，不能用来修饰工厂。"}, "sentence_index": 6, "correct_answer": "国营"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的小猫是国营的，每天都陪我玩。", "explanation": "这里把“国营”误用来指动物，误成了〈私养〉的意思。国营说的是单位由国家投资经营，小猫不是单位。"}, {"text": "明天的天气是国营的，大家都很期待。", "explanation": "这里把“国营”误用成了〈全民所有〉的意思。国营说的是由国家投资经营的单位，天气不是单位。"}, {"text": "这个笑话是国营的，大家都笑了。", "explanation": "这里把“国营”误用成了〈公开〉的意思。国营说的是由国家投资经营的单位，笑话不是单位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f92986f4-e2ef-4f74-b8c7-f309337bf38e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95358, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座公园很国营的，门票比较便宜。", "corrected_sentence": "这座公园是国营的，门票比较便宜。", "error_description": "“国营”表示所有制，不能受程度副词“很”修饰；作谓语时要说“是国营的”，不能把“是”换成“很”，说成“很国营的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f92986f4-e2ef-4f74-b8c7-f309337bf38e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95358, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家电台不国营的，是私人的。", "corrected_sentence": "这家电台不是国营的，是私人的。", "error_description": "“国营”作谓语时要说“是国营的”，否定要说“不是国营的”，不能漏掉“是”，说成“不国营的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f92986f4-e2ef-4f74-b8c7-f309337bf38e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
