INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95368, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "儿子的妻子，也口语中指妻子。", "primary_collocate": null, "pronunciation": "xí fu", "ipa": "ɕi˧˥ fu", "syllable_count": 2, "sentences": [{"text": "我媳妇今天不上班。", "target_word": "媳妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他带着媳妇回老家过年。", "target_word": "媳妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我媳妇做的菜特别好吃。", "target_word": "媳妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王的媳妇在医院工作。", "target_word": "媳妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想给媳妇买一件礼物。", "target_word": "媳妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我跟媳妇都喜欢看电影。", "target_word": "媳妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "张大哥娶了媳妇，大家都很高兴。", "target_word": "媳妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "媳妇生气了，他赶快说对不起。", "target_word": "媳妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天要早点儿回家陪媳妇。", "target_word": "媳妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说她的大媳妇最会做饭。", "target_word": "媳妇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "新媳妇", "label": "复合"}, {"form": "儿媳妇", "label": "复合"}, {"form": "媳婦", "label": "繁体"}], "register": "口语", "sense_fingerprint": "儿子的妻子；口语中也指自己或他人的妻子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c44c436-e2e9-48e7-8596-898e18732794') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95368, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "媳妇", "is_correct": true, "explanation": "正确答案：媳妇（xí fu），口语中可指自己的妻子。"}, {"text": "西服", "is_correct": false, "explanation": "xī（第一声）与 xí（第二声）声调不同，西服是西装，与媳妇意思无关。"}, {"text": "戏服", "is_correct": false, "explanation": "xì（第四声）与 xí（第二声）声调不同，戏服指戏剧表演时穿的服装。"}, {"text": "姨夫", "is_correct": false, "explanation": "yí 与 xí 声母不同（y 与 x），姨夫指母亲姐妹的丈夫。"}, {"text": "喜服", "is_correct": false, "explanation": "xǐ（第三声）与 xí（第二声）声调不同，喜服指结婚时穿的衣服。"}], "explanations": {"媳妇": "正确答案：媳妇（xí fu），口语中可指自己的妻子。", "西服": "xī（第一声）与 xí（第二声）声调不同，西服是西装，与媳妇意思无关。", "戏服": "xì（第四声）与 xí（第二声）声调不同，戏服指戏剧表演时穿的服装。", "姨夫": "yí 与 xí 声母不同（y 与 x），姨夫指母亲姐妹的丈夫。", "喜服": "xǐ（第三声）与 xí（第二声）声调不同，喜服指结婚时穿的衣服。"}, "sentence_index": null, "correct_answer": "媳妇"}, "level_3": {"options": [{"text": "媳妇", "is_correct": true, "explanation": "媳妇指妻子，“我媳妇今天不上班”符合语境。"}, {"text": "学生", "is_correct": false, "explanation": "搭配：学生上学，不说“上班”，“我学生今天不上班”说不通。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不会上班，“我电脑今天不上班”说不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会上班，“我桌子今天不上班”说不通。"}], "explanations": {"媳妇": "媳妇指妻子，“我媳妇今天不上班”符合语境。", "学生": "搭配：学生上学，不说“上班”，“我学生今天不上班”说不通。", "电脑": "语义：电脑不会上班，“我电脑今天不上班”说不通。", "桌子": "语义：桌子不会上班，“我桌子今天不上班”说不通。"}, "sentence_index": 0, "correct_answer": "媳妇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和他是媳妇，两家一起过年。", "explanation": "这里应该用〈亲家〉。媳妇指儿子的妻子或口语中的妻子，两家因子女结婚而结成的关系不能说“是媳妇”。"}, {"text": "我的媳妇还没结婚。", "explanation": "这里应该用〈女朋友〉。媳妇指已经结婚的妻子，与“还没结婚”矛盾。"}, {"text": "我们家请了一个媳妇，她做饭很好吃。", "explanation": "这里应该用〈保姆〉。媳妇是家里人，不能请来做家务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c90960a-6c3b-4a06-9171-bce75b911b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95368, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "媳妇", "is_correct": true, "explanation": "媳妇指妻子，“娶了媳妇”符合语境。"}, {"text": "女朋友", "is_correct": false, "explanation": "搭配：“娶”用于结婚的对象，不说“娶了女朋友”，搭配不当。"}, {"text": "嫂子", "is_correct": false, "explanation": "语义：嫂子是哥哥或弟弟的妻子，张大哥不能娶嫂子。"}, {"text": "女婿", "is_correct": false, "explanation": "语义：女婿是女儿的丈夫，不能说“娶”。"}], "explanations": {"媳妇": "媳妇指妻子，“娶了媳妇”符合语境。", "女朋友": "搭配：“娶”用于结婚的对象，不说“娶了女朋友”，搭配不当。", "嫂子": "语义：嫂子是哥哥或弟弟的妻子，张大哥不能娶嫂子。", "女婿": "语义：女婿是女儿的丈夫，不能说“娶”。"}, "sentence_index": 6, "correct_answer": "媳妇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我媳妇今年八岁。", "explanation": "这里应该用〈女儿〉。媳妇指已经结婚的妻子或儿子的妻子，八岁的孩子不可能是媳妇。"}, {"text": "我媳妇刚出生。", "explanation": "这里应该用〈孙女〉。媳妇指已经结婚的女性，不能指刚出生的孩子。"}, {"text": "那个媳妇今年十二岁。", "explanation": "这里应该用〈男孩〉。媳妇指已经结婚的妻子，十二岁的孩子不能是媳妇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c90960a-6c3b-4a06-9171-bce75b911b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95368, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们家刚娶了一条新媳妇。", "corrected_sentence": "我们家刚娶了一个新媳妇。", "error_description": "量词错误：“条”用于细长的东西，不能用来数人。正确：“一个新媳妇”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c90960a-6c3b-4a06-9171-bce75b911b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95368, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年娶了一头媳妇。", "corrected_sentence": "他去年娶了一个媳妇。", "error_description": "错误：“一头媳妇”。正确：“一个媳妇”。“头”多用于大牲畜，人用量词“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c90960a-6c3b-4a06-9171-bce75b911b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95370, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "娶", "is_correct": true, "explanation": "娶：男子迎娶妻子，与“嫁”相对，两者可以合称“嫁娶”。"}, {"text": "送", "is_correct": false, "explanation": "送：把东西交给别人，与“嫁”不是反义关系。"}, {"text": "买", "is_correct": false, "explanation": "买：用钱换取东西，与“嫁”没有反义关系。"}, {"text": "吃", "is_correct": false, "explanation": "吃：把食物咽下去，与“嫁”没有反义关系。"}], "correct_answer": "娶", "explanations": {"娶": "娶：男子迎娶妻子，与“嫁”相对，两者可以合称“嫁娶”。", "送": "送：把东西交给别人，与“嫁”不是反义关系。", "买": "买：用钱换取东西，与“嫁”没有反义关系。", "吃": "吃：把食物咽下去，与“嫁”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b1ace79-53a1-4242-a2e2-e2b35734789e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95370, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "娶", "is_correct": true, "explanation": "娶：男子迎娶妻子，与“嫁”相对，两者可以合称“嫁娶”。"}, {"text": "读", "is_correct": false, "explanation": "读：看着文字发出声音或理解内容，与“嫁”没有反义关系。"}, {"text": "站", "is_correct": false, "explanation": "站：立起身体，不是“嫁”的反义词。"}, {"text": "洗", "is_correct": false, "explanation": "洗：用水去除污物，与“嫁”没有反义关系。"}], "correct_answer": "娶", "explanations": {"娶": "娶：男子迎娶妻子，与“嫁”相对，两者可以合称“嫁娶”。", "读": "读：看着文字发出声音或理解内容，与“嫁”没有反义关系。", "站": "站：立起身体，不是“嫁”的反义词。", "洗": "洗：用水去除污物，与“嫁”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b1ace79-53a1-4242-a2e2-e2b35734789e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95370, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "女子出嫁，与人结为夫妻。", "primary_collocate": null, "pronunciation": "jià", "ipa": "tɕja˥˩", "syllable_count": 1, "sentences": [{"text": "她二十五岁嫁给了一位医生。", "target_word": "嫁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "姐姐明年要嫁到北京去。", "target_word": "嫁", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她不想嫁给不爱的人。", "target_word": "嫁", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小红嫁了以后，住在外地。", "target_word": "嫁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我女儿还小，不想嫁人。", "target_word": "嫁", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她嫁给他已经十年了。", "target_word": "嫁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古时候，女孩十几岁就要嫁人。", "target_word": "嫁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妹妹去年嫁到了国外。", "target_word": "嫁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她说，自己只嫁爱她的人。", "target_word": "嫁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "王老师的女儿嫁给了他的同学。", "target_word": "嫁", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "嫁了", "label": "体标"}, {"form": "嫁过", "label": "体标"}, {"form": "嫁人", "label": "复合"}, {"form": "嫁给", "label": "复合"}], "register": "通用", "sense_fingerprint": "女子出嫁，与人结为夫妻", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36dfc1c3-bfed-4839-928d-9a6989dfa483') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95370, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "嫁", "is_correct": true, "explanation": "嫁：女子出嫁，与人结为夫妻，是本词的基本意思。"}, {"text": "家", "is_correct": false, "explanation": "jiā（第一声）与 jià（第四声）声调不同，意思是“家”，指家庭或住所。"}, {"text": "假", "is_correct": false, "explanation": "jiǎ（第三声）与 jià（第四声）声调不同，意思是“假”，即不真实。"}, {"text": "加", "is_correct": false, "explanation": "jiā（第一声）与 jià（第四声）声调不同，意思是“加”，即增添。"}, {"text": "夹", "is_correct": false, "explanation": "jiā（第一声）与 jià（第四声）声调不同，意思是“夹”，即用两物挤压。"}, {"text": "下", "is_correct": false, "explanation": "xià（第四声）与 jià 声母不同（x 与 j），意思是“下面”。"}], "explanations": {"嫁": "嫁：女子出嫁，与人结为夫妻，是本词的基本意思。", "家": "jiā（第一声）与 jià（第四声）声调不同，意思是“家”，指家庭或住所。", "假": "jiǎ（第三声）与 jià（第四声）声调不同，意思是“假”，即不真实。", "加": "jiā（第一声）与 jià（第四声）声调不同，意思是“加”，即增添。", "夹": "jiā（第一声）与 jià（第四声）声调不同，意思是“夹”，即用两物挤压。", "下": "xià（第四声）与 jià 声母不同（x 与 j），意思是“下面”。"}, "sentence_index": null, "correct_answer": "嫁"}, "level_3": {"options": [{"text": "嫁", "is_correct": true, "explanation": "嫁：女子出嫁，与人结为夫妻。“嫁给了”指嫁给某人，符合句意。"}, {"text": "娶", "is_correct": false, "explanation": "语义：“娶”指男子迎娶妻子，句子的主语“她”是女子，不能用“娶”。"}, {"text": "送", "is_correct": false, "explanation": "搭配：“送给”的宾语应是可以转交的物品，不能用来指“她”这个人。"}, {"text": "卖", "is_correct": false, "explanation": "语义：“卖给”指把东西换钱给人，与婚嫁无关，读起来像在说卖人。"}], "explanations": {"嫁": "嫁：女子出嫁，与人结为夫妻。“嫁给了”指嫁给某人，符合句意。", "娶": "语义：“娶”指男子迎娶妻子，句子的主语“她”是女子，不能用“娶”。", "送": "搭配：“送给”的宾语应是可以转交的物品，不能用来指“她”这个人。", "卖": "语义：“卖给”指把东西换钱给人，与婚嫁无关，读起来像在说卖人。"}, "sentence_index": 0, "correct_answer": "嫁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "张先生去年嫁给了一位同学。", "explanation": "这里应该用〈娶〉。嫁只指女子出嫁，男子成家要用娶，主语是男性时不能用嫁。"}, {"text": "两家嫁以后，关系更好了。", "explanation": "这里应该用〈结亲〉。嫁指女子出嫁，两家联姻要说结亲，“两家”不能作嫁的主语。"}, {"text": "他把书嫁给了朋友。", "explanation": "这里应该用〈借〉。“嫁”只用于女子出嫁，不能用于书籍，把书借给朋友要说借。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b1ace79-53a1-4242-a2e2-e2b35734789e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95370, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "嫁", "is_correct": true, "explanation": "嫁：女子出嫁，与人结为夫妻，是本词的基本意思。"}, {"text": "甲", "is_correct": false, "explanation": "jiǎ（第三声）与 jià（第四声）声调不同，意思是“甲”，如甲乙。"}, {"text": "佳", "is_correct": false, "explanation": "jiā（第一声）与 jià 声调不同，意思是“佳”，即美好。"}, {"text": "夏", "is_correct": false, "explanation": "xià 与 jià 声母不同（x 与 j），意思是“夏天”。"}, {"text": "教", "is_correct": false, "explanation": "jiào（第四声）与 jià 的韵母不同（ao 与 a），意思是“教导”。"}], "explanations": {"嫁": "嫁：女子出嫁，与人结为夫妻，是本词的基本意思。", "甲": "jiǎ（第三声）与 jià（第四声）声调不同，意思是“甲”，如甲乙。", "佳": "jiā（第一声）与 jià 声调不同，意思是“佳”，即美好。", "夏": "xià 与 jià 声母不同（x 与 j），意思是“夏天”。", "教": "jiào（第四声）与 jià 的韵母不同（ao 与 a），意思是“教导”。"}, "sentence_index": null, "correct_answer": "嫁"}, "level_3": {"options": [{"text": "嫁", "is_correct": true, "explanation": "嫁：女子出嫁，与人结为夫妻。“嫁人”指女子出嫁，符合句意。"}, {"text": "骗", "is_correct": false, "explanation": "语义：“骗人”是欺骗别人，与“女孩十几岁就要”的语境不符，读起来不通。"}, {"text": "雇", "is_correct": false, "explanation": "语义：“雇人”需要经济能力，十几岁的女孩不会去雇人，句意读不通。"}, {"text": "娶", "is_correct": false, "explanation": "搭配：“娶”通常接“妻子”，且说的是男子，不能用来指女孩去“娶人”。"}], "explanations": {"嫁": "嫁：女子出嫁，与人结为夫妻。“嫁人”指女子出嫁，符合句意。", "骗": "语义：“骗人”是欺骗别人，与“女孩十几岁就要”的语境不符，读起来不通。", "雇": "语义：“雇人”需要经济能力，十几岁的女孩不会去雇人，句意读不通。", "娶": "搭配：“娶”通常接“妻子”，且说的是男子，不能用来指女孩去“娶人”。"}, "sentence_index": 6, "correct_answer": "嫁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "王老师把房子嫁给了他的同学。", "explanation": "这里应该用〈卖〉。嫁的对象只能是人，不能用于物品；把房子卖给别人，要用卖。"}, {"text": "王老师的女儿和他的同学嫁了。", "explanation": "这里应该用〈结婚〉。嫁只说女方出嫁、到男方家，两人并列一起结婚要说结婚。"}, {"text": "他去年嫁到了女方家。", "explanation": "这里应该用〈入赘〉。嫁只指女子出嫁，男子到女方家成家要说入赘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b1ace79-53a1-4242-a2e2-e2b35734789e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95370, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她去年嫁到了一位律师。", "corrected_sentence": "她去年嫁给了一位律师。", "error_description": "“嫁到”后面接地方，“嫁给”后面接人。这里嫁的是一个人，应把“到”改为“给”，说“嫁给了一位律师”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b1ace79-53a1-4242-a2e2-e2b35734789e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95370, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他女儿今年把嫁给了一位工程师。", "corrected_sentence": "他女儿今年嫁给了一位工程师。", "error_description": "错误：“把”之后缺少宾语（应是被嫁的人）。“嫁”可以用于“把”字句（如“他把女儿嫁给了……”），但此句的“把”后直接接“嫁”，应删去“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b1ace79-53a1-4242-a2e2-e2b35734789e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
