INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95371, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很多人一起睡觉、住下来的房子。", "primary_collocate": null, "pronunciation": "sù shè", "ipa": "su⁵¹ ʂɤ⁵¹", "syllable_count": 2, "sentences": [{"text": "工人们晚上都睡在工地旁边的宿舍。", "target_word": "宿舍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间宿舍有八张床，住着八个人。", "target_word": "宿舍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军训期间，我们全班住在同一个宿舍里。", "target_word": "宿舍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂给外地来的工人安排了宿舍。", "target_word": "宿舍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宿舍里很热闹，大家晚上聊到很晚。", "target_word": "宿舍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏令营的孩子们回宿舍休息了。", "target_word": "宿舍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他下班以后就回宿舍睡觉。", "target_word": "宿舍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宿舍里的床都是上下两层的。", "target_word": "宿舍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个宿舍住着十几个打工的年轻人。", "target_word": "宿舍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宿舍的门口放着很多鞋子。", "target_word": "宿舍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "间", "label": "量词"}, {"form": "宿舍楼", "label": "复合词"}, {"form": "工人宿舍", "label": "复合词"}], "register": "中性", "sense_fingerprint": "许多人合住、一起睡觉的房子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e67f8dfb-e267-437b-9944-79bb6626f076') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95371, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宿舍", "is_correct": true, "explanation": "宿舍是许多人一起住的集体房屋，“工地旁边的宿舍”能让工人晚上睡觉，是正确答案。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是景观场所，不是供人睡觉居住的地方，“睡在花园”说不通。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是自然水体，不能用来睡觉，“工地旁边的河流”无法与“睡”搭配。"}, {"text": "书架", "is_correct": false, "explanation": "搭配：“睡”要求可以躺卧的处所，“书架”是家具，不能用来睡。"}], "explanations": {"宿舍": "宿舍是许多人一起住的集体房屋，“工地旁边的宿舍”能让工人晚上睡觉，是正确答案。", "花园": "语义：花园是景观场所，不是供人睡觉居住的地方，“睡在花园”说不通。", "河流": "语义：河流是自然水体，不能用来睡觉，“工地旁边的河流”无法与“睡”搭配。", "书架": "搭配：“睡”要求可以躺卧的处所，“书架”是家具，不能用来睡。"}, "sentence_index": 0, "correct_answer": "宿舍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在医院的宿舍里住了一个星期，每天有护士照顾。", "explanation": "这里应该用〈病房〉。宿舍是许多人合住的集体房屋，住院的病人要说病房。"}, {"text": "我们家有三间宿舍，每人一间。", "explanation": "这里应该用〈卧室〉。宿舍是集体住房，家里的房间要说卧室。"}, {"text": "他在市中心租了一套宿舍。", "explanation": "这里应该用〈公寓〉。宿舍由单位或学校提供，不是个人租用的房子，租房要说公寓。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bd675e3-c938-486a-bec4-7c7114a7efcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95371, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宿舍", "is_correct": true, "explanation": "他下班后回宿舍睡觉，“回”后接的是可以住宿的处所，是正确答案。"}, {"text": "大衣", "is_correct": false, "explanation": "语义：大衣是衣物，不是可以回去睡觉的地方，“回大衣睡觉”说不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能作为“回去”的处所，“回桌子睡觉”不成立。"}, {"text": "星期", "is_correct": false, "explanation": "搭配：“回”要求处所，“星期”是时间，二者不能搭配。"}], "explanations": {"宿舍": "他下班后回宿舍睡觉，“回”后接的是可以住宿的处所，是正确答案。", "大衣": "语义：大衣是衣物，不是可以回去睡觉的地方，“回大衣睡觉”说不通。", "桌子": "语义：桌子是家具，不能作为“回去”的处所，“回桌子睡觉”不成立。", "星期": "搭配：“回”要求处所，“星期”是时间，二者不能搭配。"}, "sentence_index": 6, "correct_answer": "宿舍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工地上搭着一只宿舍，工人晚上都睡在里面。", "explanation": "这里应该用〈间〉。宿舍作为房间用“间”，“只”用于动物，不能用于宿舍。"}, {"text": "工厂为外地工人准备了一把宿舍。", "explanation": "这里应该用〈间〉或〈栋〉。“把”用于有柄的器具，不能用于宿舍。"}, {"text": "夏令营的孩子们住进了一支宿舍。", "explanation": "这里应该用〈间〉。“支”用于笔、队伍等，不能用于宿舍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bd675e3-c938-486a-bec4-7c7114a7efcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95371, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几个工人都住在这张宿舍里。", "corrected_sentence": "这几个工人都住在这间宿舍里。", "error_description": "错误：量词“张”用错。宿舍是房间，应用量词“间”，写作“这间宿舍里”。“张”用于床、桌等物体，不能用于房间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bd675e3-c938-486a-bec4-7c7114a7efcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95371, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在这台宿舍住过三年。", "corrected_sentence": "我在这间宿舍住过三年。", "error_description": "错误：量词“台”用错。宿舍是房间，应用量词“间”；“台”用于机器、设备，不能用于宿舍，应写作“这间宿舍”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bd675e3-c938-486a-bec4-7c7114a7efcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
