INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95372, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供学生或员工集体居住的房屋。", "primary_collocate": null, "pronunciation": "sù shè", "ipa": "su⁵¹ ʂɤ⁵¹", "syllable_count": 2, "sentences": [{"text": "我们学校的宿舍在图书馆后面。", "target_word": "宿舍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她和三个同学住在一间宿舍里。", "target_word": "宿舍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宿舍晚上十一点关门，我得早点回去。", "target_word": "宿舍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的员工可以申请公司的宿舍。", "target_word": "宿舍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天从宿舍走到教室只要五分钟。", "target_word": "宿舍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把行李搬进了宿舍。", "target_word": "宿舍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宿舍管理员正在检查每个房间的电器。", "target_word": "宿舍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们宿舍的四个人都喜欢打篮球。", "target_word": "宿舍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我在宿舍里洗衣服、打扫卫生。", "target_word": "宿舍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宿舍里不能做饭，也不能养宠物。", "target_word": "宿舍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "间", "label": "量词"}, {"form": "宿舍楼", "label": "复合词"}, {"form": "学生宿舍", "label": "复合词"}], "register": "中性", "sense_fingerprint": "学校或单位提供给学生、员工住的集体住房", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e67f8dfb-e267-437b-9944-79bb6626f076') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95372, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宿舍", "is_correct": true, "explanation": "宿舍是学校或单位提供的集体住房，“我们学校的宿舍在图书馆后面”语义通顺，是正确答案。"}, {"text": "学期", "is_correct": false, "explanation": "语义：学期是一段时间，不能位于某个地点，“在图书馆后面”说不通。"}, {"text": "学费", "is_correct": false, "explanation": "语义：学费是金钱，不是有位置的实体，不能说在图书馆后面。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“在……后面”要求具体场所或物体，“天气”不能用来指方位。"}], "explanations": {"宿舍": "宿舍是学校或单位提供的集体住房，“我们学校的宿舍在图书馆后面”语义通顺，是正确答案。", "学期": "语义：学期是一段时间，不能位于某个地点，“在图书馆后面”说不通。", "学费": "语义：学费是金钱，不是有位置的实体，不能说在图书馆后面。", "天气": "搭配：“在……后面”要求具体场所或物体，“天气”不能用来指方位。"}, "sentence_index": 0, "correct_answer": "宿舍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在海边订了一间宿舍，住了三天。", "explanation": "这里应该用〈旅馆〉。宿舍是学校或单位为学生、员工提供的集体住房，外出旅游的临时住宿要说旅馆。"}, {"text": "我们在郊区买了一套宿舍。", "explanation": "这里应该用〈住宅〉。宿舍由学校或单位提供，个人不能买下，买房子要说住宅。"}, {"text": "他在市中心租了一套宿舍。", "explanation": "这里应该用〈公寓〉。宿舍由学校或单位提供，不是私人房东出租的房子，租房要说公寓。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bd675e3-c938-486a-bec4-7c7114a7efcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95372, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宿舍", "is_correct": true, "explanation": "宿舍管理员是管理学生宿舍的人员，与“检查每个房间的电器”语境相符，是正确答案。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“管理员”指人，前面的名词要表示场所或组织，“冰箱”不能与“管理员”组成这种关系。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车管理员管理的是停车场所，不负责检查房间的电器。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是可以管理的场所或机构，“石头管理员”不成立。"}], "explanations": {"宿舍": "宿舍管理员是管理学生宿舍的人员，与“检查每个房间的电器”语境相符，是正确答案。", "冰箱": "搭配：“管理员”指人，前面的名词要表示场所或组织，“冰箱”不能与“管理员”组成这种关系。", "汽车": "语义：汽车管理员管理的是停车场所，不负责检查房间的电器。", "石头": "语义：石头不是可以管理的场所或机构，“石头管理员”不成立。"}, "sentence_index": 6, "correct_answer": "宿舍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工地上有一只宿舍，工人都住在里面。", "explanation": "这里应该用〈间〉。宿舍作为房间用“间”，“只”用于动物，不能用于宿舍。"}, {"text": "学校新盖了一把宿舍。", "explanation": "这里应该用〈栋〉。宿舍作为楼用“栋”，“把”用于有柄的器具，不能用于宿舍。"}, {"text": "我们班有一支宿舍。", "explanation": "这里应该用〈间〉。宿舍作为房间用“间”，“支”用于笔、队伍等，不能用于宿舍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bd675e3-c938-486a-bec4-7c7114a7efcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95372, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末我们都宿舍里学习。", "corrected_sentence": "周末我们都在宿舍里学习。", "error_description": "错误：“宿舍里”前缺少介词“在”。应写作“在宿舍里学习”，表示动作发生的场所要用“在”引出。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bd675e3-c938-486a-bec4-7c7114a7efcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95372, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把这辆宿舍收拾得很干净。", "corrected_sentence": "我把这间宿舍收拾得很干净。", "error_description": "错误：量词“辆”用错。“辆”用于车，宿舍是房间，应用量词“间”，写作“这间宿舍”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bd675e3-c938-486a-bec4-7c7114a7efcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
