INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95376, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "学生将所学知识应用于实际工作中进行锻炼。", "primary_collocate": null, "pronunciation": "shí xí", "ipa": "ʂɻ̩˧˥ ɕi˧˥", "syllable_count": 2, "sentences": [{"text": "老师让我们去公司实习，用上学到的知识。", "target_word": "实习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想去学校当老师，先实习一年。", "target_word": "实习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学法律的学生要去法院实习。", "target_word": "实习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在实习的时候学到了很多。", "target_word": "实习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学电脑的人可以去公司实习。", "target_word": "实习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在设计公司实习，用课上学的知识画图。", "target_word": "实习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生必须实习半年才能毕业。", "target_word": "实习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想找一个地方实习，把课上学的知识用到工作里。", "target_word": "实习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在医院实习，慢慢学会了看病。", "target_word": "实习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们都在找地方实习。", "target_word": "实习", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "实习过", "label": "体标"}, {"form": "实习期", "label": "复合"}, {"form": "實習", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把所学知识用于实际工作来锻炼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5590457-323a-4f29-a55c-1e85319d3532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95376, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "实习", "is_correct": true, "explanation": "正确：实习指把所学知识用于工作，与“老师让我们去公司”相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：去公司游泳与“用上学到的知识”的意思冲突。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：去公司睡觉与“用上学到的知识”冲突。"}, {"text": "写作业", "is_correct": false, "explanation": "搭配：“写作业”与学校搭配，不能用于公司。"}], "explanations": {"实习": "正确：实习指把所学知识用于工作，与“老师让我们去公司”相符。", "游泳": "语义：去公司游泳与“用上学到的知识”的意思冲突。", "睡觉": "语义：去公司睡觉与“用上学到的知识”冲突。", "写作业": "搭配：“写作业”与学校搭配，不能用于公司。"}, "sentence_index": 0, "correct_answer": "实习"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天晚上在沙发上实习，很放松。", "explanation": "这里应该用〈休息〉。实习是到单位学习做事，在沙发上放松不是实习。"}, {"text": "我们在海边实习，玩得很开心。", "explanation": "这里应该用〈度假〉。实习是为了在单位学习做事，与“玩得很开心”的休闲意思不符。"}, {"text": "爸爸已经实习了，每天在公园散步。", "explanation": "这里应该用〈退休〉。实习是学习锻炼，已经退休的爸爸应说退休。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f92986f4-e2ef-4f74-b8c7-f309337bf38e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95376, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "实习", "is_correct": true, "explanation": "正确：实习指学生把所学用于工作，与“必须……才能毕业”相符。"}, {"text": "旅游", "is_correct": false, "explanation": "语义：旅游不是毕业前必须的学习，与“才能毕业”冲突。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步半年不是毕业要求，与句意冲突。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉半年不能代替毕业要求，与句意冲突。"}], "explanations": {"实习": "正确：实习指学生把所学用于工作，与“必须……才能毕业”相符。", "旅游": "语义：旅游不是毕业前必须的学习，与“才能毕业”冲突。", "散步": "语义：散步半年不是毕业要求，与句意冲突。", "睡觉": "语义：睡觉半年不能代替毕业要求，与句意冲突。"}, "sentence_index": 6, "correct_answer": "实习"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同学们晚上都去操场实习，打篮球。", "explanation": "这里应该用〈锻炼〉。实习指到单位学习做事，去操场打篮球是体育锻炼，不是实习。"}, {"text": "爷爷每天下午实习。", "explanation": "这里应该用〈睡觉〉。实习是到单位学习做事，爷爷每天下午要说睡觉或休息。"}, {"text": "我每天早上去超市实习，买了很多东西。", "explanation": "这里应该用〈购物〉。实习是到单位学习做事，去超市买东西不是实习。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f92986f4-e2ef-4f74-b8c7-f309337bf38e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95376, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在工厂实习着一年。", "corrected_sentence": "她在工厂实习了一年。", "error_description": "错误：“实习着一年”。正确：“实习了一年”。“着”表示动作或状态正在进行，不用来叙述已经结束的一段实习经历；叙述已完成的时段，应用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f92986f4-e2ef-4f74-b8c7-f309337bf38e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95376, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他工厂实习过两个月。", "corrected_sentence": "他在工厂实习过两个月。", "error_description": "错误：缺少“在”，写成“工厂实习过”。正确：“在工厂实习过”。表示地点的介词“在”不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f92986f4-e2ef-4f74-b8c7-f309337bf38e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
