INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95380, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "影像和声音的合称。", "primary_collocate": null, "pronunciation": "yǐng yīn", "ipa": "iŋ²¹⁴ in⁵⁵", "syllable_count": 2, "sentences": [{"text": "这个视频的影音不同步。", "target_word": "影音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆用影音记录了老人的生活。", "target_word": "影音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "影音和文字都是保存历史的方法。", "target_word": "影音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司专门制作影音，客户很多。", "target_word": "影音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的影音作品在比赛中得了奖。", "target_word": "影音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "影音数据很大，需要很多存储空间。", "target_word": "影音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把现场的影音保存下来。", "target_word": "影音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家图书馆收藏了很多老电影的影音。", "target_word": "影音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在的影音行业发展得很快。", "target_word": "影音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场演出的影音已经上传到网站。", "target_word": "影音", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "影音资料", "label": "复合词"}, {"form": "影音作品", "label": "复合词"}], "register": "中性", "sense_fingerprint": "影像与声音两种记录形式的合称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e67f8dfb-e267-437b-9944-79bb6626f076') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95380, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "影音", "is_correct": true, "explanation": "影音是影像和声音的合称，是正确答案。"}, {"text": "影印", "is_correct": false, "explanation": "影印（yǐng yìn）与影音（yǐng yīn）第二个音节声调不同，影印指复印，意思不同。"}, {"text": "英音", "is_correct": false, "explanation": "英音（yīng yīn）与影音（yǐng yīn）第一个音节声调不同，意思是英式发音。"}, {"text": "硬音", "is_correct": false, "explanation": "硬音（yìng yīn）与影音（yǐng yīn）第一个音节声调不同，意思是用力较强的发音。"}], "explanations": {"影音": "影音是影像和声音的合称，是正确答案。", "影印": "影印（yǐng yìn）与影音（yǐng yīn）第二个音节声调不同，影印指复印，意思不同。", "英音": "英音（yīng yīn）与影音（yǐng yīn）第一个音节声调不同，意思是英式发音。", "硬音": "硬音（yìng yīn）与影音（yǐng yīn）第一个音节声调不同，意思是用力较强的发音。"}, "sentence_index": null, "correct_answer": "影音"}, "level_3": {"options": [{"text": "影音", "is_correct": true, "explanation": "“这个视频的影音不同步”指画面与声音不同步，是正确答案。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是金钱数额，不能与视频同步。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道属于味觉，不能与视频同步。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“不同步”用于时间或进度，“温度”不能与视频搭配。"}], "explanations": {"影音": "“这个视频的影音不同步”指画面与声音不同步，是正确答案。", "价格": "语义：价格是金钱数额，不能与视频同步。", "味道": "语义：味道属于味觉，不能与视频同步。", "温度": "搭配：“不同步”用于时间或进度，“温度”不能与视频搭配。"}, "sentence_index": 0, "correct_answer": "影音"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的影音很好听。", "explanation": "这里应该用〈声音〉。影音包含画面，歌曲只有声音，要说声音。"}, {"text": "这部小说的影音很生动。", "explanation": "这里应该用〈文字〉。小说是文字作品，没有影音，要说文字。"}, {"text": "这本画册里有很多影音。", "explanation": "这里应该用〈图片〉。画册是静态的图片，没有声音，影音要有影像和声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bd675e3-c938-486a-bec4-7c7114a7efcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95380, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "影音", "is_correct": true, "explanation": "“请把现场的影音保存下来”指保存现场的画面和声音，是正确答案。"}, {"text": "重力", "is_correct": false, "explanation": "语义：重力是物理作用力，不是可以录制或保存的对象，“保存重力”说不通。"}, {"text": "温泉", "is_correct": false, "explanation": "语义：温泉是地热水体，不能像录制内容一样保存下来。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“保存”一般搭配可录制的内容，“脚步”通常不能保存下来。"}], "explanations": {"影音": "“请把现场的影音保存下来”指保存现场的画面和声音，是正确答案。", "重力": "语义：重力是物理作用力，不是可以录制或保存的对象，“保存重力”说不通。", "温泉": "语义：温泉是地热水体，不能像录制内容一样保存下来。", "脚步": "搭配：“保存”一般搭配可录制的内容，“脚步”通常不能保存下来。"}, "sentence_index": 6, "correct_answer": "影音"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师发了一只影音给同学们。", "explanation": "这里应该用〈段〉。“只”用于动物，影音应说“一段影音”。"}, {"text": "他借了一把影音，回家看了一晚上。", "explanation": "这里应该用〈段〉。“把”用于有柄的器具，影音应说“一段影音”。"}, {"text": "这家商店卖一支影音。", "explanation": "这里应该用〈段〉。“支”用于笔、队伍等，影音应说“一段影音”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bd675e3-c938-486a-bec4-7c7114a7efcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95380, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只影音很精彩。", "corrected_sentence": "这段影音很精彩。", "error_description": "错误：“影音”的量词用错。“只”用于动物，影音应用“段”，写作“这段影音”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bd675e3-c938-486a-bec4-7c7114a7efcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95380, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工作人员录过这只影音。", "corrected_sentence": "工作人员录过这段影音。", "error_description": "错误：量词“只”用错。“只”用于动物，影音应用“段”，写作“这段影音”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bd675e3-c938-486a-bec4-7c7114a7efcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
