INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95382, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把伤员或物资送往后方。", "primary_collocate": null, "pronunciation": "hòu sòng", "ipa": "xoʊ˥˩ sʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "医生要把伤员后送到后方的医院。", "target_word": "后送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前线打得很激烈，伤员必须马上后送。", "target_word": "后送", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "部队把受伤的战士后送到后方医院。", "target_word": "后送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天亮以前，他们后送了二十个伤员。", "target_word": "后送", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战士们用车把伤员后送，路上走了一夜。", "target_word": "后送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战斗快开始了，要把多余的物资后送。", "target_word": "后送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士们一边包扎，一边后送重伤员。", "target_word": "后送", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "部队撤退前，把弹药和粮食都后送了。", "target_word": "后送", "complexity_tier": "T3", "furigana": "hòu sòng", "sentence_source": "generated"}, {"text": "这些药品要后送，不能留在前线。", "target_word": "后送", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院在后方，所以重伤员要从前线后送到那里。", "target_word": "后送", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "后送了", "label": "完成体"}, {"form": "后送过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "战时把伤员或物资从前线送往后方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c26939-6725-4f6a-bb31-b15d2945697c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95382, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "后送", "is_correct": true, "explanation": "正确：后送指把伤员送往后方，与“把伤员……到后方的医院”相符。"}, {"text": "丢弃", "is_correct": false, "explanation": "语义：“丢弃”是抛开不要，与救治转送伤员的意思相反。"}, {"text": "收藏", "is_correct": false, "explanation": "搭配：“收藏”的对象是物品，不能说收藏伤员。"}, {"text": "押", "is_correct": false, "explanation": "搭配：“押”多用于看管犯人，不用于转送伤员。"}], "explanations": {"后送": "正确：后送指把伤员送往后方，与“把伤员……到后方的医院”相符。", "丢弃": "语义：“丢弃”是抛开不要，与救治转送伤员的意思相反。", "收藏": "搭配：“收藏”的对象是物品，不能说收藏伤员。", "押": "搭配：“押”多用于看管犯人，不用于转送伤员。"}, "sentence_index": 0, "correct_answer": "后送"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "前线吃紧，部队把弹药从后方后送到前线。", "explanation": "这里应该用〈前送〉。后送是把伤员或物资送往后方，把弹药从后方运到前线是前送，方向正好相反。"}, {"text": "他们后送了这个阵地。", "explanation": "这里应该用〈放弃〉。后送的对象只能是伤员或物资，阵地是地点，不能被后送，这里要说放弃阵地。"}, {"text": "撤退时，部队把自己后送到了后方。", "explanation": "这里应该用〈转移〉。后送的对象是伤员或物资，由别人送走；部队自己转移不用后送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aeff772-539d-4f47-b284-c068f2a7122c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95382, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "后送", "is_correct": true, "explanation": "正确：后送指把伤员送往后方，与“一边包扎，一边……重伤员”的语境相符。"}, {"text": "洗涤", "is_correct": false, "explanation": "搭配：“洗涤”用于衣物等物品，不能说洗涤人。"}, {"text": "咒骂", "is_correct": false, "explanation": "语域：“咒骂”含强烈贬义，与认真救护伤员的语境不协调。"}, {"text": "冲击", "is_correct": false, "explanation": "语义：“冲击”指猛烈撞击，与包扎救治的动作不合。"}], "explanations": {"后送": "正确：后送指把伤员送往后方，与“一边包扎，一边……重伤员”的语境相符。", "洗涤": "搭配：“洗涤”用于衣物等物品，不能说洗涤人。", "咒骂": "语域：“咒骂”含强烈贬义，与认真救护伤员的语境不协调。", "冲击": "语义：“冲击”指猛烈撞击，与包扎救治的动作不合。"}, "sentence_index": 6, "correct_answer": "后送"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "快递员把包裹后送到我家门口。", "explanation": "这里应该用〈投递〉。后送指把伤员或物资送往后方，把包裹送到住处属于日常投递，要用投递。"}, {"text": "班长把身体很好的战士后送到后方医院。", "explanation": "这里应该用〈调派〉。后送只用于伤员或物资，把身体很好的战士送往后方要用调派。"}, {"text": "战士们把战友的家书后送到后方的营地。", "explanation": "这里应该用〈寄〉。后送针对的是伤员或战时物资，家书既不是伤员，也不是需要转运的物资，不能用后送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aeff772-539d-4f47-b284-c068f2a7122c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95382, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "班长把伤员后送在后方的救护站。", "corrected_sentence": "班长把伤员后送到后方的救护站。", "error_description": "“后送”后面表示送达地点要用“到”，不能用“在”，说成“后送在后方的救护站”是错的。正确形式是“后送到后方的救护站”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aeff772-539d-4f47-b284-c068f2a7122c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95382, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "连长把弹药后送在后方仓库。", "corrected_sentence": "连长把弹药后送到后方仓库。", "error_description": "“后送”后面表示送达的地点要用“到”，不能用“在”，说成“后送在后方仓库”是错的。正确形式是“后送到后方仓库”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aeff772-539d-4f47-b284-c068f2a7122c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
