INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95383, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让电影或歌曲很快地往后走。", "primary_collocate": null, "pronunciation": "kuài jìn", "ipa": "kʰuai˥˩ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "这段广告太长了，我们快进吧。", "target_word": "快进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌前面很无聊，你可以快进。", "target_word": "快进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影的开头没意思，我把它快进了。", "target_word": "快进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按这个键，电影会快进。", "target_word": "快进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看电视剧的时候，常常快进。", "target_word": "快进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把歌快进到最后一段。", "target_word": "快进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影太慢了，我快进着看了一遍。", "target_word": "快进", "complexity_tier": "T3", "furigana": "kuài jìn", "sentence_source": "generated"}, {"text": "妈妈正在看电影，你不要快进。", "target_word": "快进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影的前半个小时，我都快进了。", "target_word": "快进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听课的录音太长，我快进着听。", "target_word": "快进", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "快进了", "label": "体标（了）"}, {"form": "快进着", "label": "体标（着）"}, {"form": "快进键", "label": "复合词"}], "register": "口语", "sense_fingerprint": "让电影、歌曲等快速往后播放，跳过不想看的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9854624b-8070-4f99-8ae6-f7429f171087') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95383, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "快进", "is_correct": true, "explanation": "正确：快进指让广告快速播过去，正好对应“广告太长”的语境。"}, {"text": "放大", "is_correct": false, "explanation": "语义：放大指扩大图像或声音，与要跳过太长广告的意思无关。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：修理的对象是坏掉的东西，不能说修理广告让它变短。"}, {"text": "出发", "is_correct": false, "explanation": "语义：出发指动身前往，与“广告太长了”这一句的理由不相干。"}], "explanations": {"快进": "正确：快进指让广告快速播过去，正好对应“广告太长”的语境。", "放大": "语义：放大指扩大图像或声音，与要跳过太长广告的意思无关。", "修理": "搭配：修理的对象是坏掉的东西，不能说修理广告让它变短。", "出发": "语义：出发指动身前往，与“广告太长了”这一句的理由不相干。"}, "sentence_index": 0, "correct_answer": "快进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "按这个键，电影会快进到开头。", "explanation": "这里应该用“快退”。快进是让内容往后播放，要回到开头需要用快退。"}, {"text": "我们快进工作进度，争取早点完成。", "explanation": "这里应该用“加快”。快进只用于正在播放的影音，工作进度要用加快。"}, {"text": "汽车在高速上快进，很快就到了城里。", "explanation": "这里应该用“行驶”。快进是让影音内容往后播放，汽车前进要用行驶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe1ffd8-a3dc-44be-8085-b68b09c3db6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95383, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "快进", "is_correct": true, "explanation": "正确：快进指快速跳过内容往后播，与“电影太慢了”的抱怨相合。"}, {"text": "慢放", "is_correct": false, "explanation": "语义：慢放会让电影更慢，与“电影太慢了”的抱怨直接矛盾。"}, {"text": "放慢", "is_correct": false, "explanation": "语义：放慢是降低速度，与前文“太慢”要加快的意思相反。"}, {"text": "关掉", "is_correct": false, "explanation": "语义：关掉就结束了观看，不能说“关掉着看”，与“看了一遍”矛盾。"}], "explanations": {"快进": "正确：快进指快速跳过内容往后播，与“电影太慢了”的抱怨相合。", "慢放": "语义：慢放会让电影更慢，与“电影太慢了”的抱怨直接矛盾。", "放慢": "语义：放慢是降低速度，与前文“太慢”要加快的意思相反。", "关掉": "语义：关掉就结束了观看，不能说“关掉着看”，与“看了一遍”矛盾。"}, "sentence_index": 6, "correct_answer": "快进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电影院正在快进这部电影。", "explanation": "这里应该用“放映”。快进是在播放器上跳过内容，电影院里的影片不能快进。"}, {"text": "他快进完了全程马拉松。", "explanation": "这里应该用“跑完”。快进只用于播放内容，人跑马拉松不能说快进。"}, {"text": "妈妈快进着炒菜，一会儿就炒好了。", "explanation": "这里应该用“翻炒”。快进只用于影音播放，炒菜要用翻炒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe1ffd8-a3dc-44be-8085-b68b09c3db6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95383, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把这首歌快进在了副歌。", "corrected_sentence": "他把这首歌快进到了副歌。", "error_description": "错误：快进的目标须用“到”引出，应说“快进到了副歌”；“在”不能引出快进的目标，“快进在了副歌”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe1ffd8-a3dc-44be-8085-b68b09c3db6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95383, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这段录音太慢了，我们快进了听吧。", "corrected_sentence": "这段录音太慢了，我们快进着听吧。", "error_description": "错误：“快进”后用了“了”，表示完成，不能用于劝人一起做的句子。应改为“着”，说“快进着听”，表示一边快进一边听。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe1ffd8-a3dc-44be-8085-b68b09c3db6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
