INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95384, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe1ffd8-a3dc-44be-8085-b68b09c3db6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95384, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使播放内容快速向前推进。", "primary_collocate": null, "pronunciation": "kuài jìn", "ipa": "kʰuai˥˩ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "老师说这一段不重要，让我们快进。", "target_word": "快进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "视频里的广告太长，请快进到三分钟。", "target_word": "快进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想看结尾，所以把录像快进了。", "target_word": "快进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "播放器上有一个快进的按钮。", "target_word": "快进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边吃饭，一边把节目快进。", "target_word": "快进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节目太慢了，我们先快进一会儿。", "target_word": "快进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议录像有两个小时，我只好快进着看。", "target_word": "快进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别快进，这里有很重要的内容。", "target_word": "快进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不喜欢看片头，每次都快进。", "target_word": "快进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你向右拖一下，视频就会快进。", "target_word": "快进", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "快进了", "label": "体标（了）"}, {"form": "快进着", "label": "体标（着）"}, {"form": "快进键", "label": "复合词"}], "register": "口语", "sense_fingerprint": "操作播放器，使视频、录音等内容加速向前推进", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9854624b-8070-4f99-8ae6-f7429f171087') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95384, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "快进", "is_correct": true, "explanation": "正确：快进指快速跳过播放内容，正好对应“这一段不重要”的语境。"}, {"text": "放慢", "is_correct": false, "explanation": "语义：放慢是降低速度，与“不重要、可以跳过”的意思相反。"}, {"text": "重读", "is_correct": false, "explanation": "语义：重读是再读一遍，与跳过不重要内容的意思矛盾。"}, {"text": "背诵", "is_correct": false, "explanation": "搭配：背诵常用于需要记住的内容，与“这一段不重要”搭配不当。"}], "explanations": {"快进": "正确：快进指快速跳过播放内容，正好对应“这一段不重要”的语境。", "放慢": "语义：放慢是降低速度，与“不重要、可以跳过”的意思相反。", "重读": "语义：重读是再读一遍，与跳过不重要内容的意思矛盾。", "背诵": "搭配：背诵常用于需要记住的内容，与“这一段不重要”搭配不当。"}, "sentence_index": 0, "correct_answer": "快进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想把节目倒回开头，就按了快进。", "explanation": "这里应该用“快退”。快进是让内容往后播放，倒回开头要用快退。"}, {"text": "我们快进工作进度，争取早点完成。", "explanation": "这里应该用“加快”。快进只用于播放中的影音，工作进度要用加快。"}, {"text": "他快进了那幅画，很快就欣赏完了。", "explanation": "这里应该用“浏览”。快进是让影音内容快速往后播放，看画要用浏览或观看。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe1ffd8-a3dc-44be-8085-b68b09c3db6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95384, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "快进", "is_correct": true, "explanation": "正确：快进指快速跳过内容，与“只好”跳着看一个很长的录像相合。"}, {"text": "录制", "is_correct": false, "explanation": "语义：录制是拍摄或录音，不能用来指观看已有的录像。"}, {"text": "讲解", "is_correct": false, "explanation": "配价：讲解需要所讲的内容作宾语，“讲解着看”说不通。"}, {"text": "转播", "is_correct": false, "explanation": "语义：转播指实时传送节目，与看已经录好的录像不符。"}], "explanations": {"快进": "正确：快进指快速跳过内容，与“只好”跳着看一个很长的录像相合。", "录制": "语义：录制是拍摄或录音，不能用来指观看已有的录像。", "讲解": "配价：讲解需要所讲的内容作宾语，“讲解着看”说不通。", "转播": "语义：转播指实时传送节目，与看已经录好的录像不符。"}, "sentence_index": 6, "correct_answer": "快进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电视台正在快进新闻节目。", "explanation": "这里应该用“播放”。快进是跳过内容加速往后走，电视台应正常播放节目。"}, {"text": "工人正在快进货物。", "explanation": "这里应该用“装载”。快进只用于影音播放，搬运货物要用装载。"}, {"text": "妈妈仔细洗了菜，然后快进了菜。", "explanation": "这里应该用“切”。快进只用于播放影音，处理蔬菜要用切。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe1ffd8-a3dc-44be-8085-b68b09c3db6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95384, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这段广告太长了，我们快进在结尾吧。", "corrected_sentence": "这段广告太长了，我们快进到结尾吧。", "error_description": "错误：快进的目标须用“到”引出，应说“快进到结尾吧”；“快进在结尾吧”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe1ffd8-a3dc-44be-8085-b68b09c3db6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95384, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "视频太慢了，你快进过看吧。", "corrected_sentence": "视频太慢了，你快进着看吧。", "error_description": "错误：“快进”后用了“过”，表示曾经有过的经历，不能用于劝人的句子。应改为“着”，说“快进着看”，表示一边快进一边看。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe1ffd8-a3dc-44be-8085-b68b09c3db6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
