INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95388, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "方言，打听；询问。", "primary_collocate": null, "pronunciation": "dǎ wèn", "ipa": "ta˨˩ wən˥˩", "syllable_count": 2, "sentences": [{"text": "他到处打问你的下落。", "target_word": "打问", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想跟人打问一下去车站的路。", "target_word": "打问", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你去村口打问打问，看有没有人见过。", "target_word": "打问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向邻居打问了那家人的情况。", "target_word": "打问", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我打问过好几个人，都不知道。", "target_word": "打问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人拉着路人打问孩子的消息。", "target_word": "打问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她四处打问哪里有房子出租。", "target_word": "打问", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先打问清楚价钱，再决定买不买。", "target_word": "打问", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我进城打问找工作的门路。", "target_word": "打问", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在门口打问了半天，才找到那家店。", "target_word": "打问", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "打问了", "label": "完成体"}, {"form": "打问过", "label": "经历体"}, {"form": "打问打问", "label": "重叠"}, {"form": "打問", "label": "繁体"}], "register": "方言", "sense_fingerprint": "方言动词，向人打听、询问某人某事的消息或情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abbedf5-65ef-4d8e-91b6-0fff13c7738f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95388, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "打问", "is_correct": true, "explanation": "正确。打问（dǎ wèn）指向人打听消息或情况，是方言词。"}, {"text": "大吻", "is_correct": false, "explanation": "dà（第四声）与 dǎ（第三声）、wěn（第三声）与 wèn（第四声），声母韵母相同、仅声调不同；大吻指屋脊两端的装饰构件，与“打问”意思无关。"}, {"text": "答问", "is_correct": false, "explanation": "dá（第二声）与 dǎ（第三声）声调不同；答问意思是回答问题。"}, {"text": "打吻", "is_correct": false, "explanation": "wěn（第三声）与 wèn（第四声）声调不同；打吻意思是亲吻。"}], "explanations": {"打问": "正确。打问（dǎ wèn）指向人打听消息或情况，是方言词。", "大吻": "dà（第四声）与 dǎ（第三声）、wěn（第三声）与 wèn（第四声），声母韵母相同、仅声调不同；大吻指屋脊两端的装饰构件，与“打问”意思无关。", "答问": "dá（第二声）与 dǎ（第三声）声调不同；答问意思是回答问题。", "打吻": "wěn（第三声）与 wèn（第四声）声调不同；打吻意思是亲吻。"}, "sentence_index": null, "correct_answer": "打问"}, "level_3": {"options": [{"text": "打问", "is_correct": true, "explanation": "正确。打问表示向人打听消息，可以和“到处”“下落”搭配。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”与“到处”“找下落”的意思相反，句子无法成立。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是器物，不能接“下落”。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”只能接可以食用的东西，不能接“下落”。"}], "explanations": {"打问": "正确。打问表示向人打听消息，可以和“到处”“下落”搭配。", "忘记": "语义：“忘记”与“到处”“找下落”的意思相反，句子无法成立。", "修理": "搭配：“修理”的对象是器物，不能接“下落”。", "吃": "搭配：“吃”只能接可以食用的东西，不能接“下落”。"}, "sentence_index": 0, "correct_answer": "打问"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在字典里打问这个字的读音。", "explanation": "这里应该用〈查〉。打问的对象是人，不能用来在字典里查字音。"}, {"text": "他一拳打问了那个小偷。", "explanation": "这里应该用〈打倒〉。“打”在此是击打义，打问表示打听，不能表示击打。"}, {"text": "妈妈打问我去买菜。", "explanation": "这里应该用〈吩咐〉。打问只表示打听，不表示下命令让对方去做事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3804a8c4-77d5-473c-a855-186802e79ed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95388, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打问", "is_correct": true, "explanation": "正确。打问表示向人打听情况，与“四处”“哪里有房子出租”搭配。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”是把东西分开，与“打听哪里有房子出租”的意思不符。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮料，不能接“哪里有房子出租”。"}, {"text": "摘", "is_correct": false, "explanation": "语义：“摘”是采下植物等，与“四处”“打听房源”不相关。"}], "explanations": {"打问": "正确。打问表示向人打听情况，与“四处”“哪里有房子出租”搭配。", "切": "语义：“切”是把东西分开，与“打听哪里有房子出租”的意思不符。", "喝": "搭配：“喝”的对象是饮料，不能接“哪里有房子出租”。", "摘": "语义：“摘”是采下植物等，与“四处”“打听房源”不相关。"}, "sentence_index": 6, "correct_answer": "打问"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "姐姐打问我路上小心。", "explanation": "这里应该用〈嘱咐〉。打问表示打听，不表示叮嘱对方注意什么。"}, {"text": "他把门打问开了。", "explanation": "这里应该用〈打开〉。“打”在此是打开的义，打问表示打听，不能表示把门打开。"}, {"text": "他打问朋友帮忙。", "explanation": "这里应该用〈拜托〉。打问表示打听情况，不表示请人帮忙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3804a8c4-77d5-473c-a855-186802e79ed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95388, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我托朋友打问的那个小区的房价。", "corrected_sentence": "我托朋友打问了那个小区的房价。", "error_description": "错误形式“打问的”，正确形式“打问了”。“了”是完成体标记，不能换成“的”；“打问的……房价”没有谓语，句子不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3804a8c4-77d5-473c-a855-186802e79ed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95388, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他先打问清晰那家店的营业时间，再出门。", "corrected_sentence": "他先打问清楚那家店的营业时间，再出门。", "error_description": "错误在“清晰”：问明白的结果补语应为“清楚”。“清晰”多指影像、声音、思路等分明，不能表示打问的结果，所以“打问清晰”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3804a8c4-77d5-473c-a855-186802e79ed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
