INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95389, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa67c596-f682-4c12-8a7a-11802c00d547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95389, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用照相机把人或东西的样子留下来。", "primary_collocate": null, "pronunciation": "pāi zhào", "ipa": "pʰaɪ̯˥ ʈʂaʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "我想给小狗拍照，留个纪念。", "target_word": "拍照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业那天，同学们一起拍照留念。", "target_word": "拍照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢给花拍照。", "target_word": "拍照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说，拍照能把美好的样子留下来。", "target_word": "拍照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在海边拍照，笑得很开心。", "target_word": "拍照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她常常给孩子拍照，放进相册里。", "target_word": "拍照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "结婚那天，他们请朋友拍照。", "target_word": "拍照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客们排着队在塔前拍照。", "target_word": "拍照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，下课后大家去门口拍照。", "target_word": "拍照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拍照的技术越来越好了。", "target_word": "拍照", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拍了照", "label": "体标（了）"}, {"form": "拍过照", "label": "体标（过）"}, {"form": "拍张照", "label": "离合"}], "register": "中性", "sense_fingerprint": "给人或物拍下样子留作纪念", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10b2f6b-6e2b-4fc3-8a1e-105a8b61b983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95389, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拍照", "is_correct": true, "explanation": "“拍照”指用相机留下影像，与“留个纪念”相符。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”是给食物，与“留个纪念”说不通。"}, {"text": "讲解", "is_correct": false, "explanation": "配价：“讲解”需要讲解的内容作宾语，句中缺少这一成分。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”多用于物品，不用来形容给小狗做的事。"}], "explanations": {"拍照": "“拍照”指用相机留下影像，与“留个纪念”相符。", "喂": "语义：“喂”是给食物，与“留个纪念”说不通。", "讲解": "配价：“讲解”需要讲解的内容作宾语，句中缺少这一成分。", "修理": "搭配：“修理”多用于物品，不用来形容给小狗做的事。"}, "sentence_index": 0, "correct_answer": "拍照"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我请画家给奶奶拍照，挂在客厅里。", "explanation": "这里应该用〈画像〉。拍照是用相机留下影像，请画家用画笔画出样子要说画像。"}, {"text": "这首歌被拍照下来了，一直放给孩子听。", "explanation": "这里应该用〈录下来〉。拍照留下的是影像，把声音留下要说录下来。"}, {"text": "这部纪录片的外景在山里拍照，拍了一年。", "explanation": "这里应该用〈拍摄〉。拍照留下的是静态影像，拍纪录片、电影要说拍摄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa67c596-f682-4c12-8a7a-11802c00d547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95389, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拍照", "is_correct": true, "explanation": "“拍照”指用相机留下影像，符合“请朋友拍照”的语境。"}, {"text": "上课", "is_correct": false, "explanation": "语义：“上课”与结婚的场合无关，说不通。"}, {"text": "放假", "is_correct": false, "explanation": "配价：“放假”是离合词，不能直接带“朋友”作宾语。"}, {"text": "辞职", "is_correct": false, "explanation": "语义：“辞职”与结婚那天的场景不符，不能用来请朋友做事。"}], "explanations": {"拍照": "“拍照”指用相机留下影像，符合“请朋友拍照”的语境。", "上课": "语义：“上课”与结婚的场合无关，说不通。", "放假": "配价：“放假”是离合词，不能直接带“朋友”作宾语。", "辞职": "语义：“辞职”与结婚那天的场景不符，不能用来请朋友做事。"}, "sentence_index": 6, "correct_answer": "拍照"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件古董被拍照了，最后卖出了很高的价钱。", "explanation": "这里应该用〈拍卖〉。拍照是用相机留下影像，把古董竞价卖出要说拍卖。"}, {"text": "这部小说被拍照了，拍了整整三个月。", "explanation": "这里应该用〈拍摄〉。拍照留下的是静态影像，把小说改成影视作品要说拍摄。"}, {"text": "他听了表扬，拍照了。", "explanation": "这里应该用〈脸红〉。拍照是用相机留下影像，害羞时的反应要说脸红。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa67c596-f682-4c12-8a7a-11802c00d547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95389, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈给刚出生的宝宝拍照得很可爱。", "corrected_sentence": "妈妈给刚出生的宝宝拍照拍得很可爱。", "error_description": "错误形式：拍照得；正确形式：拍照拍得。离合词“拍照”带补语时要重复动词“拍”，再用“得”连接补语，直接说“拍照得”是常见错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa67c596-f682-4c12-8a7a-11802c00d547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95389, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶年轻时在这里拍照过，留作纪念。", "corrected_sentence": "奶奶年轻时在这里拍过照，留作纪念。", "error_description": "错误形式：拍照过；正确形式：拍过照。动态助词“过”应紧跟动词“拍”，放在离合词“拍照”中间，不能放在句尾。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa67c596-f682-4c12-8a7a-11802c00d547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
