INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95399, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "打人、打仗时用的力气和武器。", "primary_collocate": null, "pronunciation": "wǔ lì", "ipa": "u˨˩˦ li˥˩", "syllable_count": 2, "sentences": [{"text": "打仗需要很多人，也需要武力。", "target_word": "武力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们没有武力，只好离开。", "target_word": "武力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人的武力比我们强，我们很难打赢。", "target_word": "武力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小偷用武力抢走了老人的包。", "target_word": "武力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小国的武力很弱，不敢打仗。", "target_word": "武力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人说不通，就用起了武力。", "target_word": "武力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队有强大的武力，能保护国家。", "target_word": "武力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察不能随便对人使用武力。", "target_word": "武力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民用武力赶走了进村的坏人。", "target_word": "武力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争前，两边都在增强武力。", "target_word": "武力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "打架、打仗时所用的力气和武器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebf1bab-7caf-4398-b821-cabf8dd12500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95399, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "武力", "is_correct": true, "explanation": "正确答案。武力（wǔlì）指打斗、打仗时用的力气和武器。"}, {"text": "无力", "is_correct": false, "explanation": "wú（第二声）与 wǔ（第三声）声调不同，意思是没有力气。"}, {"text": "物力", "is_correct": false, "explanation": "wù（第四声）与 wǔ（第三声）声调不同，意思是物质资源。"}, {"text": "物理", "is_correct": false, "explanation": "wù 与 wǔ 声调不同，lǐ（第三声）与 lì（第四声）声调也不同，意思是物理学。"}, {"text": "无礼", "is_correct": false, "explanation": "wú 与 wǔ 声调不同，lǐ 与 lì 声调也不同，意思是不礼貌。"}], "explanations": {"武力": "正确答案。武力（wǔlì）指打斗、打仗时用的力气和武器。", "无力": "wú（第二声）与 wǔ（第三声）声调不同，意思是没有力气。", "物力": "wù（第四声）与 wǔ（第三声）声调不同，意思是物质资源。", "物理": "wù 与 wǔ 声调不同，lǐ（第三声）与 lì（第四声）声调也不同，意思是物理学。", "无礼": "wú 与 wǔ 声调不同，lǐ 与 lì 声调也不同，意思是不礼貌。"}, "sentence_index": null, "correct_answer": "武力"}, "level_3": {"options": [{"text": "武力", "is_correct": true, "explanation": "正确。“武力”指打仗时用的力气和武器，与“打仗需要……”相合。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：打仗需要的是人员和武器，歌曲不能充当。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：打仗不需要花朵，句子意思不通。"}, {"text": "玻璃", "is_correct": false, "explanation": "搭配：“需要”后接的应是打仗所用的东西，“玻璃”不与打仗搭配。"}], "explanations": {"武力": "正确。“武力”指打仗时用的力气和武器，与“打仗需要……”相合。", "歌曲": "语义：打仗需要的是人员和武器，歌曲不能充当。", "花朵": "语义：打仗不需要花朵，句子意思不通。", "玻璃": "搭配：“需要”后接的应是打仗所用的东西，“玻璃”不与打仗搭配。"}, "sentence_index": 0, "correct_answer": "武力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的武力很好，跑了十公里也不累。", "explanation": "这里应该用〈体力〉。武力指打斗、打仗时的力气和武器，跑步时的力气要用体力。"}, {"text": "她的武力很好，每次辩论都能获胜。", "explanation": "这里应该用〈口才〉。武力指打斗、打仗时的力气和武器，辩论中的言语能力要用口才。"}, {"text": "老张的武力很好，一眼就看出这幅画是假的。", "explanation": "这里应该用〈眼力〉。武力指打斗、打仗时的力气和武器，辨别事物的眼光要用眼力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95399, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "武力", "is_correct": true, "explanation": "正确答案。武力（wǔlì）指打斗、打仗时用的力气和武器。"}, {"text": "无理", "is_correct": false, "explanation": "wú 与 wǔ、lǐ 与 lì 声调都不同，意思是不合道理。"}, {"text": "努力", "is_correct": false, "explanation": "声母 n 与 w 不同（nǔ 与 wǔ），其余相同，意思是尽力。"}, {"text": "无利", "is_correct": false, "explanation": "wú（第二声）与 wǔ（第三声）声调不同，意思是没有利益。"}], "explanations": {"武力": "正确答案。武力（wǔlì）指打斗、打仗时用的力气和武器。", "无理": "wú 与 wǔ、lǐ 与 lì 声调都不同，意思是不合道理。", "努力": "声母 n 与 w 不同（nǔ 与 wǔ），其余相同，意思是尽力。", "无利": "wú（第二声）与 wǔ（第三声）声调不同，意思是没有利益。"}, "sentence_index": null, "correct_answer": "武力"}, "level_3": {"options": [{"text": "武力", "is_correct": true, "explanation": "正确。“武力”指军队的力量，与“军队有强大的……”相合。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：军队的力量不能用蔬菜来形容，句子意思不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是军队的力量，“强大的天气”说不通。"}, {"text": "态度", "is_correct": false, "explanation": "搭配：“强大的”不修饰“态度”，这里应说“坚定的态度”之类的搭配。"}], "explanations": {"武力": "正确。“武力”指军队的力量，与“军队有强大的……”相合。", "蔬菜": "语义：军队的力量不能用蔬菜来形容，句子意思不通。", "天气": "语义：天气不是军队的力量，“强大的天气”说不通。", "态度": "搭配：“强大的”不修饰“态度”，这里应说“坚定的态度”之类的搭配。"}, "sentence_index": 6, "correct_answer": "武力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他跑马拉松靠的是武力，不是速度。", "explanation": "这里应该用〈耐力〉。武力指打斗、打仗时的力气和武器，长时间坚持的能力要用耐力。"}, {"text": "这个城市的武力很雄厚，能建很多学校。", "explanation": "这里应该用〈财力〉。武力指打斗、打仗时的力气和武器，经济实力要用财力。"}, {"text": "他的武力很高，数学成绩总是第一。", "explanation": "这里应该用〈智力〉。武力指打斗、打仗时的力气和武器，头脑的能力要用智力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCL