INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95399, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小国拥有一只武力，不敢轻易开战。", "corrected_sentence": "这个小国拥有一支武力，不敢轻易开战。", "error_description": "量词错误：“武力”作为一支力量应用量词“支”，“只”多用于动物。应改为“一支武力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95399, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们组建了一个武力，负责保护码头。", "corrected_sentence": "他们组建了一支武力，负责保护码头。", "error_description": "量词错误：“武力”作为一支力量应用量词“支”，不能用通用量词“个”。应改为“一支武力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
