INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95400, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "军事力量或暴力。", "primary_collocate": null, "pronunciation": "wǔ lì", "ipa": "u˨˩˦ li˥˩", "syllable_count": 2, "sentences": [{"text": "国家之间的问题不能只靠武力解决。", "target_word": "武力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想用武力让邻国听话。", "target_word": "武力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的武力越来越强大。", "target_word": "武力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "武力不是解决问题的好办法。", "target_word": "武力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个国家决定不用武力，坐下来谈。", "target_word": "武力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用武力占领了那座城市。", "target_word": "武力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些人遇到问题就想用武力。", "target_word": "武力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠武力欺负同学，大家都怕他。", "target_word": "武力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王用武力保护自己的国家。", "target_word": "武力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界上很多人反对使用武力。", "target_word": "武力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "国家或个人用来强迫别人的军事力量或暴力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebf1bab-7caf-4398-b821-cabf8dd12500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95400, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "武力", "is_correct": true, "explanation": "正确答案。武力（wǔlì）指军事力量或暴力。"}, {"text": "无力", "is_correct": false, "explanation": "wú（第二声）与 wǔ（第三声）声调不同，意思是没有力气。"}, {"text": "物力", "is_correct": false, "explanation": "wù（第四声）与 wǔ（第三声）声调不同，意思是物质资源。"}, {"text": "物理", "is_correct": false, "explanation": "wù 与 wǔ 声调不同，lǐ（第三声）与 lì（第四声）声调也不同，意思是物理学。"}, {"text": "无礼", "is_correct": false, "explanation": "wú 与 wǔ 声调不同，lǐ 与 lì 声调也不同，意思是不礼貌。"}], "explanations": {"武力": "正确答案。武力（wǔlì）指军事力量或暴力。", "无力": "wú（第二声）与 wǔ（第三声）声调不同，意思是没有力气。", "物力": "wù（第四声）与 wǔ（第三声）声调不同，意思是物质资源。", "物理": "wù 与 wǔ 声调不同，lǐ（第三声）与 lì（第四声）声调也不同，意思是物理学。", "无礼": "wú 与 wǔ 声调不同，lǐ 与 lì 声调也不同，意思是不礼貌。"}, "sentence_index": null, "correct_answer": "武力"}, "level_3": {"options": [{"text": "武力", "is_correct": true, "explanation": "正确。“武力”指军事力量或暴力，与“不能只靠……解决”相合。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不能用来解决国家之间的问题，句子意思不通。"}, {"text": "晚餐", "is_correct": false, "explanation": "搭配：“靠”后接的应是可借助的手段，“晚餐”不能用来解决国家之间的问题。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具与国家之间的问题毫不相干，句子不通。"}], "explanations": {"武力": "正确。“武力”指军事力量或暴力，与“不能只靠……解决”相合。", "歌曲": "语义：歌曲不能用来解决国家之间的问题，句子意思不通。", "晚餐": "搭配：“靠”后接的应是可借助的手段，“晚餐”不能用来解决国家之间的问题。", "玩具": "语义：玩具与国家之间的问题毫不相干，句子不通。"}, "sentence_index": 0, "correct_answer": "武力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家球队的武力很强，本赛季一定能夺冠。", "explanation": "这里应该用〈实力〉。武力指军事力量或暴力，球队的综合水平要用实力。"}, {"text": "她有很强的武力，很快就完成了这个任务。", "explanation": "这里应该用〈能力〉。武力只指军事力量或暴力，不能泛指一般的能力。"}, {"text": "这家工厂的武力不够，产量一直上不去。", "explanation": "这里应该用〈人力〉。武力指军事力量或暴力，生产中的劳动力要用人力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95400, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "武力", "is_correct": true, "explanation": "正确答案。武力（wǔlì）指军事力量或暴力。"}, {"text": "无理", "is_correct": false, "explanation": "wú 与 wǔ、lǐ 与 lì 声调都不同，意思是不合道理。"}, {"text": "努力", "is_correct": false, "explanation": "声母 n 与 w 不同（nǔ 与 wǔ），其余相同，意思是尽力。"}, {"text": "无利", "is_correct": false, "explanation": "wú（第二声）与 wǔ（第三声）声调不同，意思是没有利益。"}], "explanations": {"武力": "正确答案。武力（wǔlì）指军事力量或暴力。", "无理": "wú 与 wǔ、lǐ 与 lì 声调都不同，意思是不合道理。", "努力": "声母 n 与 w 不同（nǔ 与 wǔ），其余相同，意思是尽力。", "无利": "wú（第二声）与 wǔ（第三声）声调不同，意思是没有利益。"}, "sentence_index": null, "correct_answer": "武力"}, "level_3": {"options": [{"text": "武力", "is_correct": true, "explanation": "正确。“武力”指用暴力手段，与“想用……”和“遇到问题”相合。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜不能用来解决问题，“想用蔬菜”说不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以借助的手段，句子意思不通。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“用”后接的应是可以使用的手段，不能说“用空气解决问题”。"}], "explanations": {"武力": "正确。“武力”指用暴力手段，与“想用……”和“遇到问题”相合。", "蔬菜": "语义：蔬菜不能用来解决问题，“想用蔬菜”说不通。", "天气": "语义：天气不是可以借助的手段，句子意思不通。", "空气": "搭配：“用”后接的应是可以使用的手段，不能说“用空气解决问题”。"}, "sentence_index": 6, "correct_answer": "武力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在公司里有很大的武力，可以决定员工的去留。", "explanation": "这里应该用〈权力〉。武力指军事力量或暴力，支配他人的职权要用权力。"}, {"text": "这部电影的武力很强，很多观众都哭了。", "explanation": "这里应该用〈感染力〉。武力指军事力量或暴力，作品打动人心的力量要用感染力。"}, {"text": "他很有武力，爬山从来不累。", "explanation": "这里应该用〈体力〉。武力指军事力量或暴力，身体的力气要用体力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95400, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "边境上驻扎着一只武力，随时准备应对意外。", "corrected_sentence": "边境上驻扎着一支武力，随时准备应对意外。", "error_description": "量词错误：“武力”指军队的力量，量词应用“支”，不能用“只”（“只”多用于动物）。应改为“一支武力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95400, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他手下有一个武力，专门负责保护商店。", "corrected_sentence": "他手下有一支武力，专门负责保护商店。", "error_description": "量词错误：“武力”作为一支力量应用量词“支”，不能用通用量词“个”。应改为“一支武力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
