INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95401, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bd675e3-c938-486a-bec4-7c7114a7efcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95401, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "信号或东西到不了的那一块地方。", "primary_collocate": null, "pronunciation": "sǐ qū", "ipa": "sɿ˨˩˦ tɕʰy˥", "syllable_count": 2, "sentences": [{"text": "山里有很多手机信号死区。", "target_word": "死区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电梯里是信号死区，打电话总是断。", "target_word": "死区", "complexity_tier": "T3", "furigana": "diàn tī lǐ shì xìnhào sǐ qū, dǎ diànhuà zǒng shì duàn.", "sentence_source": "generated"}, {"text": "地下停车场是信号的死区。", "target_word": "死区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个房间是网络死区，总是断线。", "target_word": "死区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "摄像头照不到的地方，就是死区。", "target_word": "死区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他站在死区里，怎么也打不通电话。", "target_word": "死区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的车开进了山里的信号死区。", "target_word": "死区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院里这个角落是无线网的死区。", "target_word": "死区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请不要把车停在信号死区里，导航会失灵。", "target_word": "死区", "complexity_tier": "T3", "furigana": "qǐng bú yào bǎ chē tíng zài xìnhào sǐ qū lǐ, dǎoháng huì shīlíng.", "sentence_source": "generated"}, {"text": "这座桥下面有一片信号死区，手机用不了。", "target_word": "死区", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "信号死区", "label": "复合"}, {"form": "片", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "手机信号、网络或摄像头等覆盖不到的具体地点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e67f8dfb-e267-437b-9944-79bb6626f076') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95401, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "死区", "is_correct": true, "explanation": "死区：手机信号或网络覆盖不到的地方，正确答案。"}, {"text": "死去", "is_correct": false, "explanation": "qù（第四声）与 qū（第一声）声调不同，意思是死亡，与信号覆盖无关。"}, {"text": "市区", "is_correct": false, "explanation": "shì（第四声）与 sǐ（第三声）声母与声调都不同，意思是城市里的区域。"}, {"text": "时区", "is_correct": false, "explanation": "shí（第二声）与 sǐ（第三声）声母与声调都不同，意思是地球上按时间划分的区域。"}, {"text": "四区", "is_correct": false, "explanation": "sì（第四声）与 sǐ（第三声）声调不同，意思是第四个区域，与信号无关。"}], "explanations": {"死区": "死区：手机信号或网络覆盖不到的地方，正确答案。", "死去": "qù（第四声）与 qū（第一声）声调不同，意思是死亡，与信号覆盖无关。", "市区": "shì（第四声）与 sǐ（第三声）声母与声调都不同，意思是城市里的区域。", "时区": "shí（第二声）与 sǐ（第三声）声母与声调都不同，意思是地球上按时间划分的区域。", "四区": "sì（第四声）与 sǐ（第三声）声调不同，意思是第四个区域，与信号无关。"}, "sentence_index": null, "correct_answer": "死区"}, "level_3": {"options": [{"text": "死区", "is_correct": true, "explanation": "死区指手机信号覆盖不到的地方，符合“山里有很多手机信号……”的语境。"}, {"text": "写字楼", "is_correct": false, "explanation": "语义：山里不会有很多写字楼，与句中的“山里”冲突。"}, {"text": "地铁站", "is_correct": false, "explanation": "语义：山里没有地铁，“地铁站”与“山里”矛盾。"}, {"text": "海滩", "is_correct": false, "explanation": "搭配：“海滩”需要海边，与“山里”搭配不当。"}], "explanations": {"死区": "死区指手机信号覆盖不到的地方，符合“山里有很多手机信号……”的语境。", "写字楼": "语义：山里不会有很多写字楼，与句中的“山里”冲突。", "地铁站": "语义：山里没有地铁，“地铁站”与“山里”矛盾。", "海滩": "搭配：“海滩”需要海边，与“山里”搭配不当。"}, "sentence_index": 0, "correct_answer": "死区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在地铁站找到一座死区，手机完全没有信号。", "explanation": "这里应该用〈片〉。死区是一片区域，量词“座”用于山、楼等大型建筑，不能用于“死区”。"}, {"text": "这个房间有一条网络死区，电话常常断。", "explanation": "这里应该用〈片〉。死区是一片区域，量词“条”用于河流、道路等长条形事物。"}, {"text": "这一根死区里收不到信号，导航失灵。", "explanation": "这里应该用〈片〉。死区是一片区域，量词“根”用于细长的条状物，不能用于“死区”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bd675e3-c938-486a-bec4-7c7114a7efcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95401, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "死区", "is_correct": true, "explanation": "死区指信号覆盖不到的地方，车开进去后正符合句意。"}, {"text": "教室", "is_correct": false, "explanation": "语义：车开进了山里，不可能开进教室，与句中的“车”和“山里”冲突。"}, {"text": "冰箱", "is_correct": false, "explanation": "配价：“开进”的终点应是车能进入的处所，“冰箱”不能作为车开进去的地方。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：车不能开进钢琴，两者的所指不合。"}], "explanations": {"死区": "死区指信号覆盖不到的地方，车开进去后正符合句意。", "教室": "语义：车开进了山里，不可能开进教室，与句中的“车”和“山里”冲突。", "冰箱": "配价：“开进”的终点应是车能进入的处所，“冰箱”不能作为车开进去的地方。", "钢琴": "语义：车不能开进钢琴，两者的所指不合。"}, "sentence_index": 6, "correct_answer": "死区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座死区在地下，手机没有信号。", "explanation": "这里应该用〈片〉。死区是一片区域，量词“座”用于山、楼等大型建筑，不能用于“死区”。"}, {"text": "这张死区很大，手机收不到信号。", "explanation": "这里应该用〈片〉。死区是一片区域，量词“张”用于平面的东西，不能用于“死区”。"}, {"text": "这根死区在山里，手机没有信号。", "explanation": "这里应该用〈片〉。死区是一片区域，量词“根”用于细长的条状物，不能用于“死区”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bd675e3-c938-486a-bec4-7c7114a7efcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95401, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这一条信号死区，至今还没有人解决。", "corrected_sentence": "这一片信号死区，至今还没有人解决。", "error_description": "量词错误：“死区”应配量词“片”，写作“这一条信号死区”错，应为“这一片信号死区”。“条”用于长条形事物，不用于这类区域。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bd675e3-c938-486a-bec4-7c7114a7efcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95401, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这段路有两条信号死区，导航经常失灵。", "corrected_sentence": "这段路有两处信号死区，导航经常失灵。", "error_description": "错误：“两条信号死区”。正确：“两处信号死区”。“条”用于长条形事物，“死区”是一块地方，应用“处”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bd675e3-c938-486a-bec4-7c7114a7efcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
