INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95404, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "某个环境中给人的特定气氛和情调。", "primary_collocate": null, "pronunciation": "fēn wéi", "ipa": "fən˥ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "这家咖啡馆的氛围很安静，适合看书。", "target_word": "氛围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司里的工作氛围很轻松。", "target_word": "氛围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新年到了，街上有很浓的节日氛围。", "target_word": "氛围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师想让课堂氛围活跃一点。", "target_word": "氛围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯光和音乐让餐厅有了浪漫的氛围。", "target_word": "氛围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都在笑，会议室的氛围一下子好了。", "target_word": "氛围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试前，班里的氛围有点紧张。", "target_word": "氛围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家有一种很温暖的氛围。", "target_word": "氛围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的学习氛围很好，大家都爱看书。", "target_word": "氛围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一首歌让聚会的氛围热闹起来了。", "target_word": "氛围", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种氛围", "label": "量词"}], "register": "中性", "sense_fingerprint": "某个环境中形成的特定气氛和情调，如工作氛围、节日氛围", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abbedf5-65ef-4d8e-91b6-0fff13c7738f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95404, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "味道", "is_correct": false, "explanation": "语义：味道不能用“安静”来形容，句子说不通。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“安静”形容环境或声音，不能说“价格很安静”。"}, {"text": "氛围", "is_correct": true, "explanation": "氛围：环境中给人的气氛，可以说“很安静”，与后句“适合看书”照应。"}, {"text": "菜单", "is_correct": false, "explanation": "语义：菜单是印有菜名的纸，不能用“安静”形容。"}], "explanations": {"味道": "语义：味道不能用“安静”来形容，句子说不通。", "价格": "搭配：“安静”形容环境或声音，不能说“价格很安静”。", "氛围": "氛围：环境中给人的气氛，可以说“很安静”，与后句“适合看书”照应。", "菜单": "语义：菜单是印有菜名的纸，不能用“安静”形容。"}, "sentence_index": 0, "correct_answer": "氛围"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她把氛围切成了三块。", "explanation": "氛围是抽象的气氛，不是可以切开的具体东西，这里把它当成了物品，不这么用。"}, {"text": "他把氛围放进了冰箱。", "explanation": "氛围是环境中的气氛，不是可以放进冰箱的东西，这里把它当成了具体物品，不这么用。"}, {"text": "他把氛围装进了箱子。", "explanation": "氛围是抽象的气氛，不是可以装进箱子的具体东西，这里不这么用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3804a8c4-77d5-473c-a855-186802e79ed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95404, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书本", "is_correct": false, "explanation": "语义：书本不是可以紧张的对象，句子说不通。"}, {"text": "座位", "is_correct": false, "explanation": "语义：座位是物件，不能用“紧张”形容。"}, {"text": "灯光", "is_correct": false, "explanation": "搭配：“紧张”形容人或气氛，不说“灯光有点紧张”。"}, {"text": "氛围", "is_correct": true, "explanation": "氛围：某个环境中的气氛，可以说“有点紧张”，与“考试前”的情境相符。"}], "explanations": {"书本": "语义：书本不是可以紧张的对象，句子说不通。", "座位": "语义：座位是物件，不能用“紧张”形容。", "灯光": "搭配：“紧张”形容人或气氛，不说“灯光有点紧张”。", "氛围": "氛围：某个环境中的气氛，可以说“有点紧张”，与“考试前”的情境相符。"}, "sentence_index": 6, "correct_answer": "氛围"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班新来了一台氛围。", "explanation": "量词用错：〈台〉用于机器，氛围是抽象的气氛，不能用〈台〉计量。"}, {"text": "公园里有一只氛围。", "explanation": "量词用错：〈只〉用于动物或成对的东西，氛围不能用〈只〉计量。"}, {"text": "桌上摆着一把氛围。", "explanation": "量词用错：〈把〉用于有柄的器具，氛围不能用〈把〉计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3804a8c4-77d5-473c-a855-186802e79ed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95404, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家书店地氛围很温馨。", "corrected_sentence": "这家书店的氛围很温馨。", "error_description": "错误在助词：“这家书店”修饰“氛围”时要用“的”，不能用“地”；“地”用于修饰动词或形容词，应说“这家书店的氛围”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3804a8c4-77d5-473c-a855-186802e79ed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95404, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜市的氛围热闹出来了。", "corrected_sentence": "夜市的氛围热闹起来了。", "error_description": "错误在补语：表示气氛从无到有、变得热闹，应用“起来”，不能用“出来”，应说“热闹起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3804a8c4-77d5-473c-a855-186802e79ed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
