INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95405, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把菜放进热锅里，用铲子翻着做熟。", "primary_collocate": null, "pronunciation": "chǎo", "ipa": "ʈʂʰɑʊ˨˩˦", "syllable_count": 1, "sentences": [{"text": "先把锅烧热，再放菜炒。", "target_word": "炒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着铲子在锅里炒肉。", "target_word": "炒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "炒的时候要不停地翻。", "target_word": "炒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把白菜放进热锅里炒了几下。", "target_word": "炒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子看爸爸炒菜，觉得很有意思。", "target_word": "炒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不会炒，只会煮面条。", "target_word": "炒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这盘牛肉炒得刚好。", "target_word": "炒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶用铲子慢慢炒着青菜。", "target_word": "炒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先炒一下洋葱，味道会更香。", "target_word": "炒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜炒好以后，马上放在盘子里。", "target_word": "炒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "炒了", "label": "体标"}, {"form": "炒过", "label": "体标"}, {"form": "炒着", "label": "体标"}, {"form": "炒炒", "label": "重叠"}, {"form": "炒菜", "label": "复合"}], "register": "口语", "sense_fingerprint": "把菜放进热锅里，用铲子翻着做熟", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9854624b-8070-4f99-8ae6-f7429f171087') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95405, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "炒", "is_correct": true, "explanation": "炒（第三声）：把菜放进热锅里翻着做熟，即本义。"}, {"text": "草", "is_correct": false, "explanation": "草 cǎo 与 chǎo 声母不同（c/ch），声调相同，意思是草。"}, {"text": "超", "is_correct": false, "explanation": "超 chāo 与 chǎo 声调不同（第一声），意思是超过。"}, {"text": "潮", "is_correct": false, "explanation": "潮 cháo 与 chǎo 声调不同（第二声），意思是潮水或潮湿。"}], "explanations": {"炒": "炒（第三声）：把菜放进热锅里翻着做熟，即本义。", "草": "草 cǎo 与 chǎo 声母不同（c/ch），声调相同，意思是草。", "超": "超 chāo 与 chǎo 声调不同（第一声），意思是超过。", "潮": "潮 cháo 与 chǎo 声调不同（第二声），意思是潮水或潮湿。"}, "sentence_index": null, "correct_answer": "炒"}, "level_3": {"options": [{"text": "炒", "is_correct": true, "explanation": "正确：“再放菜炒”，炒是用锅翻动做熟菜。"}, {"text": "哭", "is_correct": false, "explanation": "语义：哭是流泪发声，不是烹饪动作。"}, {"text": "写", "is_correct": false, "explanation": "语义：写用于文字，不能用于菜。"}, {"text": "跳", "is_correct": false, "explanation": "配价：跳是不及物动词，不能带“菜”作宾语。"}], "explanations": {"炒": "正确：“再放菜炒”，炒是用锅翻动做熟菜。", "哭": "语义：哭是流泪发声，不是烹饪动作。", "写": "语义：写用于文字，不能用于菜。", "跳": "配价：跳是不及物动词，不能带“菜”作宾语。"}, "sentence_index": 0, "correct_answer": "炒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这碗面要在热水里炒三分钟。", "explanation": "这里应该用〈煮〉。炒是在热锅里翻动食物，面要在水里煮。"}, {"text": "面包要放进烤箱里炒。", "explanation": "这里应该用〈烘〉。炒要在锅里翻动，放进烤箱要用“烘”。"}, {"text": "他把牛奶炒进杯子里。", "explanation": "这里应该用〈倒〉。炒是把菜放进热锅里翻着做熟，牛奶要倒进杯子里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe1ffd8-a3dc-44be-8085-b68b09c3db6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95405, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "炒", "is_correct": true, "explanation": "炒（第三声）：把菜放进热锅里翻着做熟，即本义。"}, {"text": "朝", "is_correct": false, "explanation": "朝 cháo 与 chǎo 声调不同（第二声），意思是朝向或朝代。"}, {"text": "抄", "is_correct": false, "explanation": "抄 chāo 与 chǎo 声调不同（第一声），意思是抄写。"}, {"text": "操", "is_correct": false, "explanation": "操 cāo 与 chǎo 声母不同（c/ch），声调也不同，意思是操作或操练。"}], "explanations": {"炒": "炒（第三声）：把菜放进热锅里翻着做熟，即本义。", "朝": "朝 cháo 与 chǎo 声调不同（第二声），意思是朝向或朝代。", "抄": "抄 chāo 与 chǎo 声调不同（第一声），意思是抄写。", "操": "操 cāo 与 chǎo 声母不同（c/ch），声调也不同，意思是操作或操练。"}, "sentence_index": null, "correct_answer": "炒"}, "level_3": {"options": [{"text": "炒", "is_correct": true, "explanation": "正确：“这盘牛肉炒得刚好”，炒是用锅翻动做熟，火候刚好。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱的对象是歌，不能说“唱得刚好”指牛肉。"}, {"text": "睡", "is_correct": false, "explanation": "配价：睡是不及物动词，主语须是人或动物，牛肉不能睡。"}, {"text": "逛", "is_correct": false, "explanation": "语义：逛是人在街上走，牛肉不能逛，不能说“逛得刚好”。"}], "explanations": {"炒": "正确：“这盘牛肉炒得刚好”，炒是用锅翻动做熟，火候刚好。", "唱": "语义：唱的对象是歌，不能说“唱得刚好”指牛肉。", "睡": "配价：睡是不及物动词，主语须是人或动物，牛肉不能睡。", "逛": "语义：逛是人在街上走，牛肉不能逛，不能说“逛得刚好”。"}, "sentence_index": 6, "correct_answer": "炒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "茶叶要用开水炒。", "explanation": "这里应该用〈泡〉。炒要在热锅里翻动，茶叶要用开水泡。"}, {"text": "饺子要用手炒。", "explanation": "这里应该用〈包〉。炒是把食物放在锅里翻动，饺子要用手包。"}, {"text": "这锅鸡汤要用小火慢慢炒。", "explanation": "这里应该用〈熬〉。炒靠翻动，不能用于汤，汤要用小火慢慢熬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe1ffd8-a3dc-44be-8085-b68b09c3db6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
