INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95406, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把食物放在锅里加热翻动使熟。", "primary_collocate": null, "pronunciation": "chǎo", "ipa": "ʈʂʰɑʊ˨˩˦", "syllable_count": 1, "sentences": [{"text": "妈妈在厨房炒菜。", "target_word": "炒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先炒鸡蛋，再炒青菜。", "target_word": "炒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把肉放进锅里炒了五分钟。", "target_word": "炒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个菜要用大火炒。", "target_word": "炒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸炒的饭很好吃。", "target_word": "炒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你炒过土豆丝吗？", "target_word": "炒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她正炒着菜，电话响了。", "target_word": "炒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "炒米饭的时候要放一点盐。", "target_word": "炒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我常常在家炒几个菜。", "target_word": "炒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青菜炒得太久就不绿了。", "target_word": "炒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "炒了", "label": "体标"}, {"form": "炒过", "label": "体标"}, {"form": "炒着", "label": "体标"}, {"form": "炒炒", "label": "重叠"}, {"form": "炒菜", "label": "复合"}], "register": "口语", "sense_fingerprint": "把食物放在锅里加热翻动使熟", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9854624b-8070-4f99-8ae6-f7429f171087') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95406, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "炒", "is_correct": true, "explanation": "炒（第三声）：把食物放在锅里加热翻动使熟，即本义。"}, {"text": "草", "is_correct": false, "explanation": "草 cǎo 与 chǎo 声母不同（c/ch），声调相同，意思是草。"}, {"text": "超", "is_correct": false, "explanation": "超 chāo 与 chǎo 声调不同（第一声），意思是超过。"}, {"text": "潮", "is_correct": false, "explanation": "潮 cháo 与 chǎo 声调不同（第二声），意思是潮水或潮湿。"}], "explanations": {"炒": "炒（第三声）：把食物放在锅里加热翻动使熟，即本义。", "草": "草 cǎo 与 chǎo 声母不同（c/ch），声调相同，意思是草。", "超": "超 chāo 与 chǎo 声调不同（第一声），意思是超过。", "潮": "潮 cháo 与 chǎo 声调不同（第二声），意思是潮水或潮湿。"}, "sentence_index": null, "correct_answer": "炒"}, "level_3": {"options": [{"text": "炒", "is_correct": true, "explanation": "正确：炒是在锅里加热翻动，与厨房做菜相合。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱的对象是歌，不能说“唱菜”。"}, {"text": "睡", "is_correct": false, "explanation": "配价：睡是不及物动词，不能带“菜”作宾语。"}, {"text": "弹", "is_correct": false, "explanation": "语义：弹用于琴弦和乐器，不能用于菜。"}], "explanations": {"炒": "正确：炒是在锅里加热翻动，与厨房做菜相合。", "唱": "语义：唱的对象是歌，不能说“唱菜”。", "睡": "配价：睡是不及物动词，不能带“菜”作宾语。", "弹": "语义：弹用于琴弦和乐器，不能用于菜。"}, "sentence_index": 0, "correct_answer": "炒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这锅粥要用小火炒。", "explanation": "这里应该用〈煮〉。炒是在锅里翻动食物使熟，粥要加水煮。"}, {"text": "这只鸡要放在烤箱里炒。", "explanation": "这里应该用〈烤〉。炒要在锅里翻动，放进烤箱要用“烤”。"}, {"text": "他把草莓放在水里炒了一遍。", "explanation": "这里应该用〈洗〉。炒是把食物放在热锅里翻动使熟，草莓要放在水里洗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe1ffd8-a3dc-44be-8085-b68b09c3db6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95406, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "炒", "is_correct": true, "explanation": "炒（第三声）：把食物放在锅里加热翻动使熟，即本义。"}, {"text": "朝", "is_correct": false, "explanation": "朝 cháo 与 chǎo 声调不同（第二声），意思是朝向或朝代。"}, {"text": "抄", "is_correct": false, "explanation": "抄 chāo 与 chǎo 声调不同（第一声），意思是抄写。"}, {"text": "操", "is_correct": false, "explanation": "操 cāo 与 chǎo 声母不同（c/ch），声调也不同，意思是操作或操练。"}], "explanations": {"炒": "炒（第三声）：把食物放在锅里加热翻动使熟，即本义。", "朝": "朝 cháo 与 chǎo 声调不同（第二声），意思是朝向或朝代。", "抄": "抄 chāo 与 chǎo 声调不同（第一声），意思是抄写。", "操": "操 cāo 与 chǎo 声母不同（c/ch），声调也不同，意思是操作或操练。"}, "sentence_index": null, "correct_answer": "炒"}, "level_3": {"options": [{"text": "炒", "is_correct": true, "explanation": "正确：“她正炒着菜”，炒是在锅里翻动做菜。"}, {"text": "听", "is_correct": false, "explanation": "语义：听的对象是声音，不能说“听着菜”。"}, {"text": "笑", "is_correct": false, "explanation": "配价：笑是不及物动词，不能带“菜”作宾语。"}, {"text": "踢", "is_correct": false, "explanation": "语义：踢用于球或脚，不能用于菜。"}], "explanations": {"炒": "正确：“她正炒着菜”，炒是在锅里翻动做菜。", "听": "语义：听的对象是声音，不能说“听着菜”。", "笑": "配价：笑是不及物动词，不能带“菜”作宾语。", "踢": "语义：踢用于球或脚，不能用于菜。"}, "sentence_index": 6, "correct_answer": "炒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "面团要用手炒。", "explanation": "这里应该用〈揉〉。炒是在热锅里翻动食物，面团要用手揉。"}, {"text": "这条鱼要放在蒸锅里炒十分钟。", "explanation": "这里应该用〈蒸〉。炒要在锅里翻动，放进蒸锅要用“蒸”。"}, {"text": "这盘凉菜要加醋炒匀。", "explanation": "这里应该用〈拌〉。炒需要加热，凉菜要用“拌”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe1ffd8-a3dc-44be-8085-b68b09c3db6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95406, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我已经把鸡蛋好炒了。", "corrected_sentence": "我已经把鸡蛋炒好了。", "error_description": "结果补语位置错误：“炒”在前，结果补语“好”在后，应说“炒好了”，不能说“好炒了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe1ffd8-a3dc-44be-8085-b68b09c3db6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95406, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶正炒菜着，等会儿一起吃饭。", "corrected_sentence": "奶奶正炒着菜，等会儿一起吃饭。", "error_description": "体标位置错误：进行态“着”应紧跟动词“炒”，说“炒着菜”，不能把“着”放在宾语后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe1ffd8-a3dc-44be-8085-b68b09c3db6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
