INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95409, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "从母牛身上挤出来的白色液体，可以喝。", "primary_collocate": null, "pronunciation": "niú nǎi", "ipa": "niou˧˥ nai˨˩˦", "syllable_count": 2, "sentences": [{"text": "农民每天早上从母牛身上挤牛奶。", "target_word": "牛奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚挤出来的牛奶还是热的。", "target_word": "牛奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小牛喝的是母牛的牛奶。", "target_word": "牛奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这桶牛奶是今天早上挤的。", "target_word": "牛奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛奶是白色的，味道有点甜。", "target_word": "牛奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农场的牛奶要先放进冰箱。", "target_word": "牛奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在牧场喝了一杯新鲜牛奶。", "target_word": "牛奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这头母牛一天能产二十公斤牛奶。", "target_word": "牛奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛奶放久了会变酸。", "target_word": "牛奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子第一次看见人挤牛奶，觉得很有意思。", "target_word": "牛奶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一杯牛奶", "label": "量词"}, {"form": "一桶牛奶", "label": "量词"}], "register": "中性", "sense_fingerprint": "刚从母牛身上挤出的白色液体，可以喝", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55addd89-518c-40da-814b-2ea91ff12618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95409, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "牛奶", "is_correct": true, "explanation": "正确。“挤”用于从母牛身上取出的液体，母牛身上挤出的正是牛奶。"}, {"text": "羊奶", "is_correct": false, "explanation": "语义：母牛身上挤出的是牛奶，羊奶来自山羊或绵羊，与“母牛身上”矛盾。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "搭配：“挤”搭配“奶”这类液体，不能说挤鸡蛋。"}, {"text": "黄油", "is_correct": false, "explanation": "语义：黄油是由牛奶加工而成的，不能从母牛身上直接挤出。"}], "explanations": {"牛奶": "正确。“挤”用于从母牛身上取出的液体，母牛身上挤出的正是牛奶。", "羊奶": "语义：母牛身上挤出的是牛奶，羊奶来自山羊或绵羊，与“母牛身上”矛盾。", "鸡蛋": "搭配：“挤”搭配“奶”这类液体，不能说挤鸡蛋。", "黄油": "语义：黄油是由牛奶加工而成的，不能从母牛身上直接挤出。"}, "sentence_index": 0, "correct_answer": "牛奶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只牛奶。", "explanation": "这里应该用〈瓶〉或〈盒〉。〈只〉用于动物或成对的东西，装牛奶的要用〈瓶〉〈盒〉〈杯〉等容器量词。"}, {"text": "我把牛奶切成了三片。", "explanation": "这里不能用〈切〉。〈切〉用于有固定形状的固体，牛奶是液体，不能切成片。"}, {"text": "牛奶在草地上吃草。", "explanation": "这里应该用〈牛〉。〈牛奶〉是饮品，不是动物，不能吃草。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ac0ca0-d16b-45be-ac1e-5dbb03f8730c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95409, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "牛奶", "is_correct": true, "explanation": "正确。“喝”的对象是可饮用的液体，“新鲜牛奶”与“喝一杯”搭配自然。"}, {"text": "泥土", "is_correct": false, "explanation": "语义：泥土不能喝，“喝一杯新鲜泥土”与常识相悖。"}, {"text": "柴油", "is_correct": false, "explanation": "语义：柴油是燃料，有毒，不能喝。"}, {"text": "果酱", "is_correct": false, "explanation": "搭配：“喝”不搭配果酱这类半固体，应说“吃”。"}], "explanations": {"牛奶": "正确。“喝”的对象是可饮用的液体，“新鲜牛奶”与“喝一杯”搭配自然。", "泥土": "语义：泥土不能喝，“喝一杯新鲜泥土”与常识相悖。", "柴油": "语义：柴油是燃料，有毒，不能喝。", "果酱": "搭配：“喝”不搭配果酱这类半固体，应说“吃”。"}, "sentence_index": 6, "correct_answer": "牛奶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在两片饼干中间夹了一层牛奶。", "explanation": "这里应该用〈奶油〉。〈夹〉用于可以作夹层的固体或半固体，牛奶是液体，不能夹成一层。"}, {"text": "他早上吃了一碗牛奶，很快就饱了。", "explanation": "这里应该用〈喝〉。牛奶是液体，习惯说“喝”，不说“吃一碗”。"}, {"text": "妈妈在厨房里揉牛奶，准备做馒头。", "explanation": "这里应该用〈面粉〉。〈揉〉用于面团，牛奶是液体，不能揉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ac0ca0-d16b-45be-ac1e-5dbb03f8730c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95409, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈昨天买了两只牛奶。", "corrected_sentence": "妈妈昨天买了两盒牛奶。", "error_description": "量词错误：“牛奶”应用“盒”“瓶”等容器量词。“两只牛奶”错在“只”，“只”用于动物或成对的东西。应改为“两盒牛奶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ac0ca0-d16b-45be-ac1e-5dbb03f8730c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95409, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "桌上放着一块刚热好的牛奶。", "corrected_sentence": "桌上放着一杯刚热好的牛奶。", "error_description": "量词错误：“牛奶”是液体，应用“杯”量。“一块”用于有固定形状的块状物，不能用于牛奶。应改为“一杯刚热好的牛奶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ac0ca0-d16b-45be-ac1e-5dbb03f8730c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
