INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95413, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人们做出东西的本事有多大。", "primary_collocate": null, "pronunciation": "shēng chǎn lì", "ipa": "ʂɤŋ˥ tʂʰan˨˩ li˥˩", "syllable_count": 3, "sentences": [{"text": "新机器提高了工厂的生产力。", "target_word": "生产力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的生产力很高。", "target_word": "生产力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人累了，生产力就会下降。", "target_word": "生产力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的管理能提高生产力。", "target_word": "生产力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个人一天能做多少东西，看他的生产力。", "target_word": "生产力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用上新方法后，我们的生产力比去年高多了。", "target_word": "生产力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "休息不好会影响工作的生产力。", "target_word": "生产力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个车间的生产力是全厂最低的。", "target_word": "生产力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板想用电脑来提高生产力。", "target_word": "生产力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的生产力不高，所以东西做得慢。", "target_word": "生产力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生產力", "label": "繁体"}, {"form": "劳动生产力", "label": "复合"}], "register": "中性", "sense_fingerprint": "工厂、公司、工人做出东西的效率和本事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c44c436-e2e9-48e7-8596-898e18732794') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95413, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生产力", "is_correct": true, "explanation": "生产力指人们做出东西的本事，与“提高了工厂的”相符。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“提高”不能搭配“年龄”，工厂也没有年龄可以提高。"}, {"text": "身高", "is_correct": false, "explanation": "语义：工厂没有身高，“提高了工厂的身高”说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能被“提高”，“提高了工厂的颜色”说不通。"}], "explanations": {"生产力": "生产力指人们做出东西的本事，与“提高了工厂的”相符。", "年龄": "搭配：“提高”不能搭配“年龄”，工厂也没有年龄可以提高。", "身高": "语义：工厂没有身高，“提高了工厂的身高”说不通。", "颜色": "语义：颜色不能被“提高”，“提高了工厂的颜色”说不通。"}, "sentence_index": 0, "correct_answer": "生产力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜的生产力很好，大家都吃光了。", "explanation": "这里应该用〈味道〉。生产力指做出东西的本事，不能用来评价菜的口味好坏。"}, {"text": "他工作很努力，因为有强烈的生产力。", "explanation": "这里应该用〈动力〉。生产力指做出东西的本事，不能用来指推动人努力的内在力量。"}, {"text": "这辆车的生产力很快，一小时能跑一百公里。", "explanation": "这里应该用〈速度〉。生产力指做出东西的本事，描述车跑得快慢要用“速度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c90960a-6c3b-4a06-9171-bce75b911b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95413, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生产力", "is_correct": true, "explanation": "生产力指做出东西的效率，“影响工作的”后面可以接它。"}, {"text": "味道", "is_correct": false, "explanation": "语义：工作没有味道，“影响工作的味道”说不通。"}, {"text": "形状", "is_correct": false, "explanation": "语义：工作没有形状，这个搭配说不通。"}, {"text": "发型", "is_correct": false, "explanation": "搭配：“影响”一般搭配效率、质量、进度，不搭配发型。"}], "explanations": {"生产力": "生产力指做出东西的效率，“影响工作的”后面可以接它。", "味道": "语义：工作没有味道，“影响工作的味道”说不通。", "形状": "语义：工作没有形状，这个搭配说不通。", "发型": "搭配：“影响”一般搭配效率、质量、进度，不搭配发型。"}, "sentence_index": 6, "correct_answer": "生产力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一个很好的生产力。", "explanation": "这里应该用〈工人〉。生产力是能力，不能用来指人。"}, {"text": "这件衣服的生产力很好，穿了三年都没坏。", "explanation": "这里应该用〈质量〉。生产力指做出东西的本事，不能用来说衣服耐不耐穿，说东西好坏要用“质量”。"}, {"text": "他的生产力很好，能扛起重物。", "explanation": "这里应该用〈体力〉。生产力指做出东西的能力，形容一个人的力气要用“体力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c90960a-6c3b-4a06-9171-bce75b911b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95413, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个车间的生产力高很。", "corrected_sentence": "这个车间的生产力很高。", "error_description": "错误：“生产力高很”，副词“很”放在了形容词之后。正确：“生产力很高”，“很”应放在形容词前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c90960a-6c3b-4a06-9171-bce75b911b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95413, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个车间的生产力下降得很高。", "corrected_sentence": "这个车间的生产力下降得很低。", "error_description": "错误：“下降得很高”，“下降”表示变低，后面不能接“很高”，前后语义矛盾。正确：“下降得很低”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c90960a-6c3b-4a06-9171-bce75b911b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
