INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95414, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c90960a-6c3b-4a06-9171-bce75b911b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95414, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人们创造物质财富的能力。", "primary_collocate": null, "pronunciation": "shēng chǎn lì", "ipa": "ʂɤŋ˥ tʂʰan˨˩ li˥˩", "syllable_count": 3, "sentences": [{"text": "科学技术的发展提高了社会生产力。", "target_word": "生产力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生产力发展了，人们的生活才会变好。", "target_word": "生产力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个国家的生产力决定它有多少财富。", "target_word": "生产力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业让生产力有了很大的发展。", "target_word": "生产力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的生产力很低，人们常常吃不饱。", "target_word": "生产力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器出现后，社会生产力大大提高。", "target_word": "生产力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家想发展生产力，让人民更富。", "target_word": "生产力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生产力越高，社会创造的财富越多。", "target_word": "生产力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农业的生产力不高，农民很穷。", "target_word": "生产力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新技术带来了新的生产力。", "target_word": "生产力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生產力", "label": "繁体"}, {"form": "社会生产力", "label": "复合"}], "register": "中性", "sense_fingerprint": "社会、国家、时代创造物质财富的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c44c436-e2e9-48e7-8596-898e18732794') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95414, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生产力", "is_correct": true, "explanation": "生产力指创造物质财富的能力，与“提高了社会”相符。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：“提高”不搭配“人口”，人口一般说增长或减少。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：社会没有颜色可以提高，这个说法说不通。"}, {"text": "身高", "is_correct": false, "explanation": "语义：社会不能用“身高”来衡量，“提高了社会身高”说不通。"}], "explanations": {"生产力": "生产力指创造物质财富的能力，与“提高了社会”相符。", "人口": "搭配：“提高”不搭配“人口”，人口一般说增长或减少。", "颜色": "语义：社会没有颜色可以提高，这个说法说不通。", "身高": "语义：社会不能用“身高”来衡量，“提高了社会身高”说不通。"}, "sentence_index": 0, "correct_answer": "生产力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一个国家的生产力很多。", "explanation": "这里应该用〈财富〉。生产力是创造财富的能力，不是财富本身，不能说“很多”。"}, {"text": "人的生产力延长了不少。", "explanation": "这里应该用〈寿命〉。生产力不是可以延长的东西，“延长”只用于寿命等。"}, {"text": "这家店的生产力很好，顾客都很满意。", "explanation": "这里应该用〈服务态度〉。生产力指创造财富的能力，不能用来形容店员对顾客的态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c90960a-6c3b-4a06-9171-bce75b911b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95414, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生产力", "is_correct": true, "explanation": "生产力指创造财富的能力，“发展”的对象是它，符合语境。"}, {"text": "疾病", "is_correct": false, "explanation": "语义：疾病不能被“发展”来让人民更富，说不通。"}, {"text": "口味", "is_correct": false, "explanation": "语义：口味不能用来让人民更富，这个搭配说不通。"}, {"text": "发型", "is_correct": false, "explanation": "搭配：“发展”一般搭配经济、技术、事业等，不搭配发型。"}], "explanations": {"生产力": "生产力指创造财富的能力，“发展”的对象是它，符合语境。", "疾病": "语义：疾病不能被“发展”来让人民更富，说不通。", "口味": "语义：口味不能用来让人民更富，这个搭配说不通。", "发型": "搭配：“发展”一般搭配经济、技术、事业等，不搭配发型。"}, "sentence_index": 6, "correct_answer": "生产力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的生产力增加了三公斤。", "explanation": "这里应该用〈体重〉。生产力不能用“公斤”来计量，“增加了三公斤”只用于体重等可称的东西。"}, {"text": "这朵花的生产力很浓。", "explanation": "这里应该用〈香味〉。生产力指创造财富的能力，不能用来形容气味的浓淡。"}, {"text": "他们之间的生产力很深。", "explanation": "这里应该用〈感情〉。生产力是能力，不能用来形容关系的深浅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c90960a-6c3b-4a06-9171-bce75b911b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95414, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "蒸汽机的发明让社会的生产力高很。", "corrected_sentence": "蒸汽机的发明让社会的生产力很高。", "error_description": "错误：“生产力高很”，副词“很”放在了形容词之后。正确：“生产力很高”，“很”应放在形容词前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c90960a-6c3b-4a06-9171-bce75b911b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95414, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "随着技术的进步，国家的生产力越高越来。", "corrected_sentence": "随着技术的进步，国家的生产力越来越高。", "error_description": "错误：“越高越来”，“越来越”是固定搭配，前两个字不能颠倒。正确：“越来越高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c90960a-6c3b-4a06-9171-bce75b911b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
