INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95415, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "现在这一小会儿。", "primary_collocate": null, "pronunciation": "dāng xià", "ipa": "tɑŋ˥ ɕja˥˩", "syllable_count": 2, "sentences": [{"text": "不要总想以后，要珍惜当下。", "target_word": "当下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当下我只想好好休息，别的事都先放一放。", "target_word": "当下", "complexity_tier": "T3", "furigana": "dāngxià wǒ zhǐ xiǎng hǎohāo xiūxi, bié de shì dōu xiān fàng yi fàng.", "sentence_source": "generated"}, {"text": "他学会了活在当下，不再担心明天。", "target_word": "当下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子专心玩着，完全沉浸在当下。", "target_word": "当下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去已经过去了，当下才是真的。", "target_word": "当下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "深呼吸，把注意力放在当下。", "target_word": "当下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说，只有当下是我们真正拥有的。", "target_word": "当下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别想昨天的错，先做好当下的事。", "target_word": "当下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旅行时，我喜欢享受当下的每一刻。", "target_word": "当下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他闭上眼睛，感受当下的安静。", "target_word": "当下", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "眼前这短短的一刻，常与珍惜、专注、活在当下连用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3b264aa-b95b-40a2-9864-e252a279c2f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95415, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当下", "is_correct": true, "explanation": "当下：眼前这一刻，与“不要总想以后”的意思相呼应。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”指未来，与同句的“不要总想以后”相矛盾，不能用于此句。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“珍惜”多接时间、机会、感情等，不说“珍惜手机”。"}, {"text": "空调", "is_correct": false, "explanation": "语义：空调是家用电器，“要珍惜空调”不表达时间的意义，与句子的主旨不符。"}], "explanations": {"当下": "当下：眼前这一刻，与“不要总想以后”的意思相呼应。", "明天": "语义：“明天”指未来，与同句的“不要总想以后”相矛盾，不能用于此句。", "手机": "搭配：“珍惜”多接时间、机会、感情等，不说“珍惜手机”。", "空调": "语义：空调是家用电器，“要珍惜空调”不表达时间的意义，与句子的主旨不符。"}, "sentence_index": 0, "correct_answer": "当下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我的当下朋友。", "explanation": "这里应该用〈目前〉之类的说法，但“当下”只指“这一小会儿”，不能用来修饰“朋友”这样的人。"}, {"text": "明天的当下一定会下雨。", "explanation": "这里应该用〈将来〉。“当下”指眼前这一小会儿，不能指明天这样的将来，“明天的当下”自相矛盾。"}, {"text": "他抬头看了看当下。", "explanation": "当下是抽象的时间概念，不能被看见，这里应该说〈时间〉，即看了看时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9d3a1d-3f50-474f-99e2-3628cc50ae16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95415, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当下", "is_correct": true, "explanation": "当下：眼前这一刻，只有此刻才说得上真正拥有。"}, {"text": "未来", "is_correct": false, "explanation": "语义：未来还没有到来，说不上“真正拥有”，与句中的意思矛盾。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是具体的建筑部件，与这句关于时间的哲理意思不符。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“脚步”是迈步的动作，不能说“真正拥有”，这里不搭配。"}], "explanations": {"当下": "当下：眼前这一刻，只有此刻才说得上真正拥有。", "未来": "语义：未来还没有到来，说不上“真正拥有”，与句中的意思矛盾。", "窗户": "语义：窗户是具体的建筑部件，与这句关于时间的哲理意思不符。", "脚步": "搭配：“脚步”是迈步的动作，不能说“真正拥有”，这里不搭配。"}, "sentence_index": 6, "correct_answer": "当下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨晚做了一个很长的当下。", "explanation": "这里应该用〈梦〉。当下指眼前这一刻，不能用来指做过的梦。"}, {"text": "我们把当下的昨天全都忘了。", "explanation": "这里是把“当下”当成“一段时期”来用，但它只指“这一小会儿”，不能修饰“昨天”这样的过去时间。"}, {"text": "我当下的一生都很精彩。", "explanation": "这里是把“当下”当成“目前”来用，但它只指“这一小会儿”，不能用来概括“一生”这样漫长的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9d3a1d-3f50-474f-99e2-3628cc50ae16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95415, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他只活在当下的，不想过去和未来。", "corrected_sentence": "他只活在当下，不想过去和未来。", "error_description": "多余的“的”：“活在当下”中“当下”直接作地点宾语，后面不能加“的”，应说“他只活在当下”，不能说“他只活在当下的，……”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9d3a1d-3f50-474f-99e2-3628cc50ae16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95415, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他闭上眼睛，专心感受在当下。", "corrected_sentence": "他闭上眼睛，专心感受当下。", "error_description": "多余的介词“在”：“感受”后直接接“当下”作宾语，不需要“在”，应说“专心感受当下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9d3a1d-3f50-474f-99e2-3628cc50ae16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
