INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95417, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "真的发生过的事，不是编的。", "primary_collocate": null, "pronunciation": "zhēn shì", "ipa": "ʈʂən˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这个故事不是编的，是一件真事。", "target_word": "真事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你别笑，我说的都是真事。", "target_word": "真事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电影是根据一件真事拍的。", "target_word": "真事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我以为他在编故事，原来是真事。", "target_word": "真事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶讲的那个故事是真事，不是书里的。", "target_word": "真事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说这不是小说，是真事。", "target_word": "真事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是真事，我朋友亲眼看到的。", "target_word": "真事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他写的书里都是真事，没有一句是编的。", "target_word": "真事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听完这个故事，我才知道它是真事。", "target_word": "真事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个新闻是真事，不是笑话。", "target_word": "真事", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一件真事", "label": "量词"}, {"form": "真事儿", "label": "儿化"}], "register": "口语", "sense_fingerprint": "与编出来的故事相对，指确实发生过的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6595b4a5-d1da-4ecc-9c20-7ed1df0b6017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95417, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "真事", "is_correct": true, "explanation": "正确：指真的发生过的事，不是编的。"}, {"text": "阵式", "is_correct": false, "explanation": "zhèn（第四声）与 zhēn（第一声）声调不同，意思是阵形的样式。"}, {"text": "诊室", "is_correct": false, "explanation": "zhěn（第三声）与 zhēn（第一声）声调不同，意思是诊室。"}, {"text": "阵势", "is_correct": false, "explanation": "zhèn（第四声）与 zhēn（第一声）声调不同，意思是阵势。"}], "explanations": {"真事": "正确：指真的发生过的事，不是编的。", "阵式": "zhèn（第四声）与 zhēn（第一声）声调不同，意思是阵形的样式。", "诊室": "zhěn（第三声）与 zhēn（第一声）声调不同，意思是诊室。", "阵势": "zhèn（第四声）与 zhēn（第一声）声调不同，意思是阵势。"}, "sentence_index": null, "correct_answer": "真事"}, "level_3": {"options": [{"text": "真事", "is_correct": true, "explanation": "正确：“真事”指确实发生过的事，与“不是编的”相符。"}, {"text": "谎言", "is_correct": false, "explanation": "搭配：“件”不搭配“谎言”，应说“一句谎言”。"}, {"text": "假货", "is_correct": false, "explanation": "语义：“假货”是假的东西，与“不是编的”的前提相矛盾。"}, {"text": "童话", "is_correct": false, "explanation": "语义：童话是虚构的故事，与“不是编的”相矛盾。"}], "explanations": {"真事": "正确：“真事”指确实发生过的事，与“不是编的”相符。", "谎言": "搭配：“件”不搭配“谎言”，应说“一句谎言”。", "假货": "语义：“假货”是假的东西，与“不是编的”的前提相矛盾。", "童话": "语义：童话是虚构的故事，与“不是编的”相矛盾。"}, "sentence_index": 0, "correct_answer": "真事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是一个完全虚构的真事。", "explanation": "这里应该用〈故事〉。“虚构”的是故事，“真事”指真实发生过的事，二者相矛盾。"}, {"text": "他把这件真事标上了价格。", "explanation": "这里应该用〈商品〉。“标价”的是商品，“真事”指发生过的事，不能标价。"}, {"text": "他的眼神流露出了真事。", "explanation": "这里应该用〈真情〉。“流露”的是感情，“真事”指发生过的事，不能流露。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b74e1261-5f5f-425d-9d1e-d585592b8400') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95417, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "真事", "is_correct": true, "explanation": "正确：“真事”指亲眼看到的、确实发生过的事。"}, {"text": "传说", "is_correct": false, "explanation": "语义：传说多是口耳相传、未经证实的，与“亲眼看到”矛盾。"}, {"text": "玩笑", "is_correct": false, "explanation": "搭配：“亲眼看到”的对象是事情或场面，不能是玩笑。"}, {"text": "童话", "is_correct": false, "explanation": "语义：童话是虚构的故事，与“亲眼看到”矛盾。"}], "explanations": {"真事": "正确：“真事”指亲眼看到的、确实发生过的事。", "传说": "语义：传说多是口耳相传、未经证实的，与“亲眼看到”矛盾。", "玩笑": "搭配：“亲眼看到”的对象是事情或场面，不能是玩笑。", "童话": "语义：童话是虚构的故事，与“亲眼看到”矛盾。"}, "sentence_index": 6, "correct_answer": "真事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一生都在信奉这个真事。", "explanation": "这里应该用〈真理〉。“信奉”的是道理、主张，“真事”指真实发生过的事，不能信奉。"}, {"text": "这些真事已被辟谣。", "explanation": "这里应该用〈传闻〉。“辟谣”针对的是传闻、谣言，“真事”指真实发生过的事，不能辟谣。"}, {"text": "这个真事是我编的。", "explanation": "这里应该用〈故事〉。“编”的是故事，“真事”指真实发生过的事，不能说“编”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b74e1261-5f5f-425d-9d1e-d585592b8400') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95417, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶给我讲过一本真事。", "corrected_sentence": "奶奶给我讲过一件真事。", "error_description": "量词错误：“真事”的量词是“件”，“本”用于书册，应说“讲过一件真事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b74e1261-5f5f-425d-9d1e-d585592b8400') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95417, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他讲地那件真事让大家都很感动。", "corrected_sentence": "他讲的那件真事让大家都很感动。", "error_description": "助词错误：修饰名词“真事”的定语标记应为“的”，“地”用于修饰动词，应说“他讲的那件真事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b74e1261-5f5f-425d-9d1e-d585592b8400') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
