INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95421, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把分数上下的数字，用同一个数去变小。", "primary_collocate": null, "pronunciation": "yuē fēn", "ipa": "ɥœ˥ fən˥", "syllable_count": 2, "sentences": [{"text": "二分之一不用约分，它已经最简单了。", "target_word": "约分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把八分之四约分，就是二分之一。", "target_word": "约分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题的答案还要约分才对。", "target_word": "约分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们把每个分数都约分。", "target_word": "约分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "九分之三约分后是三分之一。", "target_word": "约分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分数的上下都除以三，这叫约分。", "target_word": "约分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我约分了两次，才得到最简分数。", "target_word": "约分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先约分再加，算起来更快。", "target_word": "约分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个分数太复杂，我们来约分吧。", "target_word": "约分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他约分时出错了，答案不对。", "target_word": "约分", "complexity_tier": "T3", "furigana": "tā yuēfēn shí chūcuò le, dá''àn bú duì。", "sentence_source": "generated"}], "morphological_forms": [{"form": "约分了", "label": "体标"}, {"form": "约分过", "label": "体标"}, {"form": "約分", "label": "繁体"}], "register": "中性", "sense_fingerprint": "分数上下同除一个数来化简", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebf1bab-7caf-4398-b821-cabf8dd12500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95421, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "约分", "is_correct": true, "explanation": "正确。“二分之一”已是最简分数，“不用约分”合理。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”与分数化简无关，句子意思不通。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”与分数无关，不能用在这里。"}, {"text": "相乘", "is_correct": false, "explanation": "搭配：“相乘”要用“与……相乘”的结构，不能直接放在“不用……”后面。"}], "explanations": {"约分": "正确。“二分之一”已是最简分数，“不用约分”合理。", "翻译": "语义：“翻译”与分数化简无关，句子意思不通。", "游泳": "语义：“游泳”与分数无关，不能用在这里。", "相乘": "搭配：“相乘”要用“与……相乘”的结构，不能直接放在“不用……”后面。"}, "sentence_index": 0, "correct_answer": "约分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "把这张图片约分一半，就能放进信封里。", "explanation": "这里应该用〈缩小〉。约分特指分数上下同除以一个数，一般的变小要用缩小。"}, {"text": "要把60分解成质因数的乘积，要用约分。", "explanation": "这里应该用〈分解〉。约分只用于分数的化简，把整数拆成质因数要用分解。"}, {"text": "把2.6四舍五入到个位，这叫约分。", "explanation": "这里应该用〈取整〉。约分只用于化简分数，把小数取近似整数要用取整。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95421, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "约分", "is_correct": true, "explanation": "正确。“约分了两次”后“才得到最简分数”，前后相合。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与得到最简分数无关，句子不通。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”不能用来得到最简分数。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“得到最简分数”要搭配计算类动作，“散步”不能与之搭配。"}], "explanations": {"约分": "正确。“约分了两次”后“才得到最简分数”，前后相合。", "唱歌": "语义：“唱歌”与得到最简分数无关，句子不通。", "修理": "语义：“修理”不能用来得到最简分数。", "散步": "搭配：“得到最简分数”要搭配计算类动作，“散步”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "约分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "1小时等于60分钟，这叫约分。", "explanation": "这里应该用〈换算〉。约分是化简分数，单位之间的变换要用换算。"}, {"text": "出门前先约分一下路费。", "explanation": "这里应该用〈估算〉。约分只用于分数，粗略算一下路费要用估算。"}, {"text": "这道题要约分出长方形的面积。", "explanation": "这里应该用〈计算〉。约分只是化简分数，不能用来泛指求得面积。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95421, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这道题我约分了两个才得到答案。", "corrected_sentence": "这道题我约分了两次才得到答案。", "error_description": "量词错误：计量“约分”这个动作要用动量词“次”，不能用名量词“个”，应说“约分了两次”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95421, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这个分数把约分后，才算出答案。", "corrected_sentence": "他把这个分数约分后，才算出答案。", "error_description": "重复介词：“把”只用一次，“把这个分数约分后”已有“把”，不应再在“约分”前加“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
