INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95422, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把分数的分子与分母同时除以公因数，使其变简。", "primary_collocate": null, "pronunciation": "yuē fēn", "ipa": "ɥœ˥ fən˥", "syllable_count": 2, "sentences": [{"text": "六分之四可以约分成三分之二。", "target_word": "约分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分子和分母有公因数，就可以约分。", "target_word": "约分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎样给分数约分。", "target_word": "约分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做完这道题，别忘了约分。", "target_word": "约分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十二分之八约分以后是三分之二。", "target_word": "约分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个分数已经不能再约分了。", "target_word": "约分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先找公因数，再把分数约分。", "target_word": "约分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "约分后的分数比原来简单。", "target_word": "约分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明算对了，可是没有约分。", "target_word": "约分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要约分，分子分母要同时除以公因数。", "target_word": "约分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "约分了", "label": "体标"}, {"form": "约分过", "label": "体标"}, {"form": "約分", "label": "繁体"}], "register": "中性", "sense_fingerprint": "数学上用公因数化简分数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebf1bab-7caf-4398-b821-cabf8dd12500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95422, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "约分", "is_correct": true, "explanation": "正确。“约分”指用公因数化简分数，与“可以……成三分之二”相合。"}, {"text": "通分", "is_correct": false, "explanation": "语义：通分是把分母化为相同，不能得到三分之二。"}, {"text": "相乘", "is_correct": false, "explanation": "搭配：“相乘”要用“与……相乘”的结构，不能直接接“成三分之二”。"}, {"text": "相加", "is_correct": false, "explanation": "语义：相加是求和，六分之四与别的数相加不会得到化简的结果。"}], "explanations": {"约分": "正确。“约分”指用公因数化简分数，与“可以……成三分之二”相合。", "通分": "语义：通分是把分母化为相同，不能得到三分之二。", "相乘": "搭配：“相乘”要用“与……相乘”的结构，不能直接接“成三分之二”。", "相加": "语义：相加是求和，六分之四与别的数相加不会得到化简的结果。"}, "sentence_index": 0, "correct_answer": "约分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "12的约分有1、2、3、4、6和12。", "explanation": "这里应该用〈约数〉。约分是化简分数的动作，一个数的因数要用约数。"}, {"text": "要把30约分成2、3、5的乘积。", "explanation": "这里应该用〈分解〉。约分只用于分数的化简，把整数拆成质因数要用分解。"}, {"text": "把小数四舍五入，就是约分。", "explanation": "这里应该用〈取整〉。约分只用于化简分数，把小数取近似整数要用取整。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95422, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "约分", "is_correct": true, "explanation": "正确。“再把分数约分”是化简分数的下一步，与前面的“找公因数”相合。"}, {"text": "修理", "is_correct": false, "explanation": "语义：分数不能修理，这里需要的是化简。"}, {"text": "游泳", "is_correct": false, "explanation": "配价：“游泳”是不及物动词，不能用“把”引出的“分数”作宾语。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能用“把”引出“分数”作宾语。"}], "explanations": {"约分": "正确。“再把分数约分”是化简分数的下一步，与前面的“找公因数”相合。", "修理": "语义：分数不能修理，这里需要的是化简。", "游泳": "配价：“游泳”是不及物动词，不能用“把”引出的“分数”作宾语。", "散步": "配价：“散步”是不及物动词，不能用“把”引出“分数”作宾语。"}, "sentence_index": 6, "correct_answer": "约分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "1米等于100厘米，这叫约分。", "explanation": "这里应该用〈换算〉。约分是化简分数，单位之间的变换要用换算。"}, {"text": "买东西前先约分一下总价。", "explanation": "这里应该用〈估算〉。约分只用于分数，粗略算一下总价要用估算。"}, {"text": "他用尺子约分了桌子的长度。", "explanation": "这里应该用〈测量〉。约分只用于化简分数，量取长短要用测量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95422, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他约分得这个分数。", "corrected_sentence": "他约分了这个分数。", "error_description": "错误形式：“约分得这个分数”；“得”是补语标记，后面要接补语，不能直接带宾语“这个分数”。表示完成的动作应用“了”，应说“他约分了这个分数”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95422, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我先把这个分数把约分。", "corrected_sentence": "我先把这个分数约分。", "error_description": "重复介词：“把”只用一次，“把这个分数约分”已有“把”，不应再在“约分”前加“把”。应改为“我先把这个分数约分”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
