INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95429, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人和动物身体前面，装着吃的东西的地方。", "primary_collocate": null, "pronunciation": "dù zi", "ipa": "tu˥˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "我的肚子饿了，想吃饭。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃太多的话，肚子会不舒服。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他早上没吃东西，肚子一直叫。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子吃了冷的东西，肚子疼。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我中午吃了两碗饭，肚子很饱。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗吃饱了，肚子圆圆的。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空着肚子不能喝酒。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喝点热汤，肚子里会舒服一些。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只猫肚子饿，一直在门口叫。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的肚子咕咕叫，大家都听到了。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "小肚子", "label": "复合"}, {"form": "大肚子", "label": "复合"}], "register": "口语", "sense_fingerprint": "装食物的肚子，饿、饱、疼等感觉所在", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd704c3d5-d131-4402-9bb4-f26ec0ee93c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95429, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "肚子", "is_correct": true, "explanation": "“肚子”（dù zi）指人或动物装食物的腹部，也是饥饿、疼痛感觉所在的部位。"}, {"text": "兔子", "is_correct": false, "explanation": "tù（第四声）与 dù（第四声）声母不同（t 与 d），意思是兔子。"}, {"text": "裤子", "is_correct": false, "explanation": "kù（第四声）与 dù（第四声）声母不同（k 与 d），意思是裤子。"}, {"text": "路子", "is_correct": false, "explanation": "lù（第四声）与 dù（第四声）声母不同（l 与 d），意思是路子。"}, {"text": "句子", "is_correct": false, "explanation": "jù（第四声）与 dù（第四声）声母不同（j 与 d），意思是句子。"}], "explanations": {"肚子": "“肚子”（dù zi）指人或动物装食物的腹部，也是饥饿、疼痛感觉所在的部位。", "兔子": "tù（第四声）与 dù（第四声）声母不同（t 与 d），意思是兔子。", "裤子": "kù（第四声）与 dù（第四声）声母不同（k 与 d），意思是裤子。", "路子": "lù（第四声）与 dù（第四声）声母不同（l 与 d），意思是路子。", "句子": "jù（第四声）与 dù（第四声）声母不同（j 与 d），意思是句子。"}, "sentence_index": null, "correct_answer": "肚子"}, "level_3": {"options": [{"text": "肚子", "is_correct": true, "explanation": "“肚子”指装食物的腹部，与“饿了，想吃饭”的语境相符。"}, {"text": "脑袋", "is_correct": false, "explanation": "语义：脑袋不会饿，“饿了，想吃饭”说的是胃肠的感受。"}, {"text": "手", "is_correct": false, "explanation": "搭配：“饿”只用于人或胃肠的感受，不能说手饿了。"}, {"text": "耳朵", "is_correct": false, "explanation": "搭配：“饿”不用于耳朵，耳朵没有饥饿的感觉。"}], "explanations": {"肚子": "“肚子”指装食物的腹部，与“饿了，想吃饭”的语境相符。", "脑袋": "语义：脑袋不会饿，“饿了，想吃饭”说的是胃肠的感受。", "手": "搭配：“饿”只用于人或胃肠的感受，不能说手饿了。", "耳朵": "搭配：“饿”不用于耳朵，耳朵没有饥饿的感觉。"}, "sentence_index": 0, "correct_answer": "肚子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他最近没有肚子，一口饭都不想吃。", "explanation": "这里应该用〈胃口〉。胃口指食欲，“肚子”指身体前面装食物的部位，不能用来表示没有食欲。"}, {"text": "他的肚子很重，特别喜欢吃辣的东西。", "explanation": "这里应该用〈口味〉。口味指对味道的喜好，“肚子”不能用来表示喜欢什么味道。"}, {"text": "他说话的肚子很小，大家都听不清。", "explanation": "这里应该用〈声音〉。“小”形容声音弱时说声音小，“肚子”是身体部位，不能用来形容说话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7937752-e703-4b5d-9a4a-a9a1ce602180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95429, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "肚子", "is_correct": true, "explanation": "“肚子”（dù zi）指人或动物装食物的腹部，也是饥饿、疼痛感觉所在的部位。"}, {"text": "柱子", "is_correct": false, "explanation": "zhù（第四声）与 dù（第四声）声母不同（zh 与 d），意思是柱子。"}, {"text": "铺子", "is_correct": false, "explanation": "pù（第四声）与 dù（第四声）声母不同（p 与 d），意思是商店。"}, {"text": "豆子", "is_correct": false, "explanation": "dòu（第四声）与 dù（第四声）韵母不同（ou 与 u），意思是豆子。"}, {"text": "独子", "is_correct": false, "explanation": "dú（第二声）与 dù（第四声）声母韵母相同、只差声调，意思是独生的儿子。"}], "explanations": {"肚子": "“肚子”（dù zi）指人或动物装食物的腹部，也是饥饿、疼痛感觉所在的部位。", "柱子": "zhù（第四声）与 dù（第四声）声母不同（zh 与 d），意思是柱子。", "铺子": "pù（第四声）与 dù（第四声）声母不同（p 与 d），意思是商店。", "豆子": "dòu（第四声）与 dù（第四声）韵母不同（ou 与 u），意思是豆子。", "独子": "dú（第二声）与 dù（第四声）声母韵母相同、只差声调，意思是独生的儿子。"}, "sentence_index": null, "correct_answer": "肚子"}, "level_3": {"options": [{"text": "肚子", "is_correct": true, "explanation": "“肚子”指装食物的腹部，“空着肚子”指没有吃东西，与“不能喝酒”的语境相符。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不会空着喝酒，句意说的是人的身体状态。"}, {"text": "肩膀", "is_correct": false, "explanation": "搭配：“空着”不用来形容肩膀，肩膀不能说空着。"}, {"text": "膝盖", "is_correct": false, "explanation": "语义：膝盖不能喝酒，与句中“不能喝酒”的语境不符。"}], "explanations": {"肚子": "“肚子”指装食物的腹部，“空着肚子”指没有吃东西，与“不能喝酒”的语境相符。", "书包": "语义：书包不会空着喝酒，句意说的是人的身体状态。", "肩膀": "搭配：“空着”不用来形容肩膀，肩膀不能说空着。", "膝盖": "语义：膝盖不能喝酒，与句中“不能喝酒”的语境不符。"}, "sentence_index": 6, "correct_answer": "肚子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他感冒了，肚子哑了。", "explanation": "这里应该用〈嗓子〉。“哑”形容嗓音发不出来，只能说嗓子哑，不能说肚子哑。"}, {"text": "他哭得厉害，肚子都红了。", "explanation": "这里应该用〈眼睛〉。“红”形容眼睛哭红，不能用来形容肚子。"}, {"text": "他一夜之间肚子全白了。", "explanation": "这里应该用〈头发〉。“白”形容头发变白，不能用来形容肚子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7937752-e703-4b5d-9a4a-a9a1ce602180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95429, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子吃了冷的东西，肚子得疼很厉害。", "corrected_sentence": "孩子吃了冷的东西，肚子疼得很厉害。", "error_description": "错误：“得疼”。“得”要放在动词或形容词后面引出补语，不能放在“疼”前面，应说“肚子疼得很厉害”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7937752-e703-4b5d-9a4a-a9a1ce602180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95429, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他晚上没吃饭，肚子饿睡不着。", "corrected_sentence": "他晚上没吃饭，肚子饿得睡不着。", "error_description": "错误：“饿睡不着”。“饿”后面要用“得”引出程度补语，应说“饿得睡不着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7937752-e703-4b5d-9a4a-a9a1ce602180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95430, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7937752-e703-4b5d-9a4a-a9a1ce602180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95430, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7937752-e703-4b5d-9a4a-a9a1ce602180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95430, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人或动物躯干中腹部的部分。", "primary_collocate": null, "pronunciation": "dù zi", "ipa": "tu˥˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "他最近胖了，肚子变大了。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生按了按我的肚子，问我疼不疼。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她怀孕了，肚子越来越大。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天做运动，想减掉肚子上的肉。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩躺在床上，肚子一上一下地动。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我趴在地上，肚子贴着地。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条裤子太小，肚子有点紧。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸的肚子又圆又大。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳的时候，水只到我的肚子。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只青蛙的肚子是白色的。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "小肚子", "label": "复合"}, {"form": "大肚子", "label": "复合"}], "register": "口语", "sense_fingerprint": "身体腹部的外形和位置，如大小、胖瘦", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd704c3d5-d131-4402-9bb4-f26ec0ee93c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95430, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "肚子", "is_correct": true, "explanation": "“肚子”（dù zi）指人或动物躯干中腹部的部分，即身体前面的外形。"}, {"text": "豆子", "is_correct": false, "explanation": "dòu（第四声）与 dù（第四声）韵母不同（ou 与 u），意思是豆子。"}, {"text": "句子", "is_correct": false, "explanation": "jù（第四声）与 dù（第四声）声母不同（j 与 d），意思是句子。"}, {"text": "铺子", "is_correct": false, "explanation": "pù（第四声）与 dù（第四声）声母不同（p 与 d），意思是商店。"}, {"text": "兔子", "is_correct": false, "explanation": "tù（第四声）与 dù（第四声）声母不同（t 与 d），意思是兔子。"}], "explanations": {"肚子": "“肚子”（dù zi）指人或动物躯干中腹部的部分，即身体前面的外形。", "豆子": "dòu（第四声）与 dù（第四声）韵母不同（ou 与 u），意思是豆子。", "句子": "jù（第四声）与 dù（第四声）声母不同（j 与 d），意思是句子。", "铺子": "pù（第四声）与 dù（第四声）声母不同（p 与 d），意思是商店。", "兔子": "tù（第四声）与 dù（第四声）声母不同（t 与 d），意思是兔子。"}, "sentence_index": null, "correct_answer": "肚子"}, "level_3": {"options": [{"text": "肚子", "is_correct": true, "explanation": "“肚子”指腹部的外形，“胖了，肚子变大了”说的正是腹部变大，与语境相符。"}, {"text": "头发", "is_correct": false, "explanation": "语义：头发不会随体重增加而变大，与“胖了”的语境不符。"}, {"text": "眉毛", "is_correct": false, "explanation": "语义：眉毛不会因为胖而变大，与句意不符。"}, {"text": "成绩", "is_correct": false, "explanation": "搭配：“变大”不用来形容成绩，成绩一般说提高或下降。"}], "explanations": {"肚子": "“肚子”指腹部的外形，“胖了，肚子变大了”说的正是腹部变大，与语境相符。", "头发": "语义：头发不会随体重增加而变大，与“胖了”的语境不符。", "眉毛": "语义：眉毛不会因为胖而变大，与句意不符。", "成绩": "搭配：“变大”不用来形容成绩，成绩一般说提高或下降。"}, "sentence_index": 0, "correct_answer": "肚子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的肚子很细，穿什么衣服都好看。", "explanation": "这里应该用〈腰〉。腰指身体中部两侧较细的部位，形容细要说腰细，“肚子”指腹部，不能说肚子细。"}, {"text": "他的肚子很长，跑得很快。", "explanation": "这里应该用〈腿〉。腿指身体下部用来走路的部位，形容长短和跑步要用腿，不能用肚子。"}, {"text": "他感冒了，肚子哑了。", "explanation": "这里应该用〈嗓子〉。“哑”形容嗓音发不出来，不能用来形容肚子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7937752-e703-4b5d-9a4a-a9a1ce602180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95430, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "肚子", "is_correct": true, "explanation": "“肚子”（dù zi）指人或动物躯干中腹部的部分，即身体前面的外形。"}, {"text": "路子", "is_correct": false, "explanation": "lù（第四声）与 dù（第四声）声母不同（l 与 d），意思是路子。"}, {"text": "柱子", "is_correct": false, "explanation": "zhù（第四声）与 dù（第四声）声母不同（zh 与 d），意思是柱子。"}, {"text": "独子", "is_correct": false, "explanation": "dú（第二声）与 dù（第四声）声母韵母相同、只差声调，意思是独生的儿子。"}, {"text": "裤子", "is_correct": false, "explanation": "kù（第四声）与 dù（第四声）声母不同（k 与 d），意思是裤子。"}], "explanations": {"肚子": "“肚子”（dù zi）指人或动物躯干中腹部的部分，即身体前面的外形。", "路子": "lù（第四声）与 dù（第四声）声母不同（l 与 d），意思是路子。", "柱子": "zhù（第四声）与 dù（第四声）声母不同（zh 与 d），意思是柱子。", "独子": "dú（第二声）与 dù（第四声）声母韵母相同、只差声调，意思是独生的儿子。", "裤子": "kù（第四声）与 dù（第四声）声母不同（k 与 d），意思是裤子。"}, "sentence_index": null, "correct_answer": "肚子"}, "level_3": {"options": [{"text": "肚子", "is_correct": true, "explanation": "“肚子”指腹部，“裤子太小，肚子有点紧”说的是腹部被裤子勒紧，与语境相符。"}, {"text": "脖子", "is_correct": false, "explanation": "语义：裤子不会勒紧脖子，句意说的是裤子太小。"}, {"text": "手腕", "is_correct": false, "explanation": "语义：这里说的是裤子太小，手腕与裤子无关，句意不通。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“紧”不用来形容眼睛，眼睛不能说有点紧。"}], "explanations": {"肚子": "“肚子”指腹部，“裤子太小，肚子有点紧”说的是腹部被裤子勒紧，与语境相符。", "脖子": "语义：裤子不会勒紧脖子，句意说的是裤子太小。", "手腕": "语义：这里说的是裤子太小，手腕与裤子无关，句意不通。", "眼睛": "搭配：“紧”不用来形容眼睛，眼睛不能说有点紧。"}, "sentence_index": 6, "correct_answer": "肚子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她听到消息，肚子都红了。", "explanation": "这里应该用〈耳朵〉。“红”形容因害羞或激动而泛红的耳朵，不用来形容肚子。"}, {"text": "他笑的时候，肚子很整齐，大家都夸他。", "explanation": "这里应该用〈牙齿〉。“整齐”多形容牙齿排列规整，不能用来形容肚子。"}, {"text": "他感冒了，肚子不通气。", "explanation": "这里应该用〈鼻子〉。“通气”指鼻子呼吸通畅，不能用来说肚子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7937752-e703-4b5d-9a4a-a9a1ce602180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95430, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的肚子大得起来了。", "corrected_sentence": "他的肚子大起来了。", "error_description": "错误：“大得起来”。“得”不能插在形容词“大”和趋向补语“起来”之间，应去掉“得”，说“大起来了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7937752-e703-4b5d-9a4a-a9a1ce602180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95430, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他吃得太饱，肚子鼓了下来。", "corrected_sentence": "他吃得太饱，肚子鼓了起来。", "error_description": "错误：“鼓了下来”。“鼓”表示向外膨胀，应用趋向补语“起来”，说“鼓了起来”，不能用“下来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7937752-e703-4b5d-9a4a-a9a1ce602180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
