INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95432, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用面粉、鸡蛋和糖等烤成的松软甜点。", "primary_collocate": null, "pronunciation": "dàn gāo", "ipa": "tan˥˩ kau˥", "syllable_count": 2, "sentences": [{"text": "妈妈用面粉和鸡蛋烤了一个蛋糕。", "target_word": "蛋糕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块蛋糕又软又甜。", "target_word": "蛋糕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烤蛋糕要先把鸡蛋和糖放在一起。", "target_word": "蛋糕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋糕在烤箱里烤了半个小时。", "target_word": "蛋糕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她买了面粉，准备做蛋糕。", "target_word": "蛋糕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的蛋糕卖得很好。", "target_word": "蛋糕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋糕上放着很多新鲜的水果。", "target_word": "蛋糕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次烤蛋糕，没有烤好。", "target_word": "蛋糕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想吃巧克力蛋糕吗？", "target_word": "蛋糕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋糕烤好以后，要等一会儿再吃。", "target_word": "蛋糕", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块蛋糕", "label": "量词"}, {"form": "蛋糕店", "label": "复合"}], "register": "中性", "sense_fingerprint": "以面粉、鸡蛋、糖烤制的松软甜点（制作与食物本身）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd704c3d5-d131-4402-9bb4-f26ec0ee93c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95432, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蛋糕", "is_correct": true, "explanation": "正确：蛋糕是用面粉、鸡蛋烤制的甜点，与句中的原料和“烤”相符。"}, {"text": "饺子", "is_correct": false, "explanation": "搭配：饺子一般是煮、煎或蒸的，不说“烤饺子”，与“烤”搭配不当。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说是文字作品，不能用面粉和鸡蛋烤出来，与句中的烤制内容矛盾。"}, {"text": "西瓜", "is_correct": false, "explanation": "搭配：西瓜是水果，不能用面粉和鸡蛋烤，“烤”与“西瓜”搭配不当。"}], "explanations": {"蛋糕": "正确：蛋糕是用面粉、鸡蛋烤制的甜点，与句中的原料和“烤”相符。", "饺子": "搭配：饺子一般是煮、煎或蒸的，不说“烤饺子”，与“烤”搭配不当。", "小说": "语义：小说是文字作品，不能用面粉和鸡蛋烤出来，与句中的烤制内容矛盾。", "西瓜": "搭配：西瓜是水果，不能用面粉和鸡蛋烤，“烤”与“西瓜”搭配不当。"}, "sentence_index": 0, "correct_answer": "蛋糕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只蛋糕送给朋友。", "explanation": "这里应该用〈块〉或〈个〉。蛋糕按块或个计量，“只”多用于动物或成对物品中的单个，不用来数蛋糕。"}, {"text": "妈妈给我做了一根蛋糕。", "explanation": "这里应该用〈块〉或〈个〉。“根”用于细长的东西，蛋糕不这样数。"}, {"text": "桌上放着一辆蛋糕。", "explanation": "这里应该用〈块〉或〈个〉。“辆”只用于车辆，不能用来数蛋糕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7937752-e703-4b5d-9a4a-a9a1ce602180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95432, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蛋糕", "is_correct": true, "explanation": "正确：蛋糕可以用水果做装饰，句中“上面放着新鲜水果”指的就是蛋糕的装饰。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是电子设备，不能用来承载新鲜水果，与句中食物的语境矛盾。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是用来挡雨的，不能用来摆放水果，与句意不符。"}, {"text": "汤", "is_correct": false, "explanation": "搭配：汤是液体，不说“汤上放着水果”，“放着……上”与“汤”搭配不当。"}], "explanations": {"蛋糕": "正确：蛋糕可以用水果做装饰，句中“上面放着新鲜水果”指的就是蛋糕的装饰。", "手机": "语义：手机是电子设备，不能用来承载新鲜水果，与句中食物的语境矛盾。", "雨伞": "语义：雨伞是用来挡雨的，不能用来摆放水果，与句意不符。", "汤": "搭配：汤是液体，不说“汤上放着水果”，“放着……上”与“汤”搭配不当。"}, "sentence_index": 6, "correct_answer": "蛋糕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "在很多欧洲国家，蛋糕是每天都要吃的主食。", "explanation": "这里应该用〈面包〉。蛋糕是甜点，不是日常的主食；“主食”指每天作为基本粮食吃的食物，应用面包。"}, {"text": "中秋节，家家户户都要吃的传统食品是蛋糕。", "explanation": "这里应该用〈月饼〉。中秋的传统食品是月饼，蛋糕不是这一节日的传统食物。"}, {"text": "我们用蛋糕包了几十个饺子。", "explanation": "这里应该用〈面皮〉。蛋糕不能用来包饺子，包饺子用的是面皮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7937752-e703-4b5d-9a4a-a9a1ce602180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95432, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们一起吃了一条蛋糕。", "corrected_sentence": "我们一起吃了一块蛋糕。", "error_description": "量词错误：“蛋糕”应用“块”计量，“条”用于细长的东西，应说“一块蛋糕”，不能说“一条蛋糕”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7937752-e703-4b5d-9a4a-a9a1ce602180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95432, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈端来了一台蛋糕。", "corrected_sentence": "妈妈端来了一块蛋糕。", "error_description": "量词错误：“蛋糕”应用“块”计量，“台”用于机器、演出等，不能用来数蛋糕，应说“一块蛋糕”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7937752-e703-4b5d-9a4a-a9a1ce602180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
