INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95433, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "到一个好看的地方去玩，看风景。", "primary_collocate": null, "pronunciation": "guān guāng", "ipa": "kwan˥ kwɑŋ˥", "syllable_count": 2, "sentences": [{"text": "周末我们一起去海边观光。", "target_word": "观光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每年夏天都去云南观光。", "target_word": "观光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想带父母去上海观光。", "target_word": "观光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "来这儿观光的人，今天特别多。", "target_word": "观光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们坐船在河上观光了一个下午。", "target_word": "观光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友从国外来，我陪她观光了三天。", "target_word": "观光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我没去过西藏，很想去那儿观光。", "target_word": "观光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，我们不能出去观光了。", "target_word": "观光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不是来工作的，只是来观光。", "target_word": "观光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "暑假我打算去山里观光，看看风景。", "target_word": "观光", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "观光了", "label": "体标"}, {"form": "观光客", "label": "复合"}, {"form": "觀光", "label": "繁体"}], "register": "中性", "sense_fingerprint": "为了玩和看风景而去某个好看的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6595b4a5-d1da-4ecc-9c20-7ed1df0b6017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95433, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "观光", "is_correct": true, "explanation": "正确：“观光”指为玩和看风景而去某地，与“海边”和“周末一起”相符。"}, {"text": "看病", "is_correct": false, "explanation": "语义：看病要去医院或诊所，与“去海边”的休闲出游不合。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试要在考场进行，去海边不是考试的地点。"}, {"text": "排队", "is_correct": false, "explanation": "搭配：“排队”不以“去海边”为目的，与“一起”的休闲语境不合。"}], "explanations": {"观光": "正确：“观光”指为玩和看风景而去某地，与“海边”和“周末一起”相符。", "看病": "语义：看病要去医院或诊所，与“去海边”的休闲出游不合。", "考试": "语义：考试要在考场进行，去海边不是考试的地点。", "排队": "搭配：“排队”不以“去海边”为目的，与“一起”的休闲语境不合。"}, "sentence_index": 0, "correct_answer": "观光"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我去医院观光奶奶。", "explanation": "这里应该用〈探望〉。“观光”指为游玩看风景而去某地，不能用于探望人。"}, {"text": "警察去现场观光。", "explanation": "这里应该用〈调查〉。“观光”是为玩看风景，警察去现场要用调查。"}, {"text": "我用显微镜观光细胞。", "explanation": "这里应该用〈观察〉。“观光”是游览风景，用显微镜看细胞要用观察。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b74e1261-5f5f-425d-9d1e-d585592b8400') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95433, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "观光", "is_correct": true, "explanation": "正确：“观光”指游玩和看风景，与“很想去那儿”的期待相符。"}, {"text": "吵架", "is_correct": false, "explanation": "搭配：“吵架”需要对象，不能只说“去那儿吵架”。"}, {"text": "发愁", "is_correct": false, "explanation": "语义：“发愁”是消极的情绪，与“很想去”的期待相反。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”不是人想去做的事，与“很想去”相矛盾。"}], "explanations": {"观光": "正确：“观光”指游玩和看风景，与“很想去那儿”的期待相符。", "吵架": "搭配：“吵架”需要对象，不能只说“去那儿吵架”。", "发愁": "语义：“发愁”是消极的情绪，与“很想去”的期待相反。", "生病": "语义：“生病”不是人想去做的事，与“很想去”相矛盾。"}, "sentence_index": 6, "correct_answer": "观光"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们在操场上观光。", "explanation": "这里应该用〈锻炼〉。“观光”是游玩看风景，在操场上活动应该用锻炼。"}, {"text": "我们去剧院观光演出。", "explanation": "这里应该用〈观看〉。“观光”的对象是风景名胜，看演出要用观看。"}, {"text": "他在办公室里观光了一整天。", "explanation": "这里应该用〈工作〉。“观光”是游玩看风景，在办公室度过一整天应该用工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b74e1261-5f5f-425d-9d1e-d585592b8400') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95433, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们明年想去杭州观光了。", "corrected_sentence": "我们明年想去杭州观光。", "error_description": "时态错误：“明年”指将来，“观光”后不能加“了”，应改为“我们明年想去杭州观光”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b74e1261-5f5f-425d-9d1e-d585592b8400') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95433, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们西安观光了三天。", "corrected_sentence": "我们在西安观光了三天。", "error_description": "介词缺失：表示处所的“在”不能省略，应说“在西安观光”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b74e1261-5f5f-425d-9d1e-d585592b8400') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
