INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95434, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "游览参观名胜、风景。", "primary_collocate": null, "pronunciation": "guān guāng", "ipa": "kwan˥ kwɑŋ˥", "syllable_count": 2, "sentences": [{"text": "游客们正在长城观光。", "target_word": "观光", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "外国客人到故宫观光，还拍了很多照片。", "target_word": "观光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个古城每年有很多人来观光。", "target_word": "观光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市长陪着客人观光了几个名胜。", "target_word": "观光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们来西安观光，参观了兵马俑。", "target_word": "观光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旅行团明天上午去西湖观光。", "target_word": "观光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们在导游带领下观光了整座古城。", "target_word": "观光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "来北京观光的人，都想去看看天安门。", "target_word": "观光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座山有很多名胜，吸引了不少人来观光。", "target_word": "观光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他退休以后，到各地的名胜观光。", "target_word": "观光", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "观光了", "label": "体标"}, {"form": "观光团", "label": "复合"}, {"form": "觀光", "label": "繁体"}], "register": "中性", "sense_fingerprint": "游览并参观名胜古迹等著名景点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6595b4a5-d1da-4ecc-9c20-7ed1df0b6017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95434, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "观光", "is_correct": true, "explanation": "正确：“观光”指游览名胜、风景，与“游客们正在长城”相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：长城上不能游泳，与游客在长城的游览场景不合。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与游客在长城游览的语境不符。"}, {"text": "驾驶", "is_correct": false, "explanation": "配价：“驾驶”需要带宾语（如车辆），单说“长城驾驶”不成立。"}], "explanations": {"观光": "正确：“观光”指游览名胜、风景，与“游客们正在长城”相符。", "游泳": "语义：长城上不能游泳，与游客在长城的游览场景不合。", "睡觉": "语义：“睡觉”与游客在长城游览的语境不符。", "驾驶": "配价：“驾驶”需要带宾语（如车辆），单说“长城驾驶”不成立。"}, "sentence_index": 0, "correct_answer": "观光"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "市长去灾区观光了一天。", "explanation": "这里应该用〈视察〉。“观光”是为玩看风景，去灾区检查工作要用视察。"}, {"text": "市长观光了开幕式。", "explanation": "这里应该用〈参加〉。“观光”的对象是风景名胜，参加仪式要用参加。"}, {"text": "市长在机场观光客人。", "explanation": "这里应该用〈迎接〉。“观光”不能带人作宾语，迎接客人要用迎接。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b74e1261-5f5f-425d-9d1e-d585592b8400') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95434, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "观光", "is_correct": true, "explanation": "正确：“观光”指游览名胜古迹，与“在导游带领下”相符。"}, {"text": "攻占", "is_correct": false, "explanation": "语义：“攻占”是军事行动，与导游带领的游览相矛盾。"}, {"text": "修建", "is_correct": false, "explanation": "语义：“修建”是建造，与“在导游带领下”的游览不符。"}, {"text": "装修", "is_correct": false, "explanation": "语义：装修是对房屋做装饰，不是游览，在导游带领下不能“装修”古城。"}], "explanations": {"观光": "正确：“观光”指游览名胜古迹，与“在导游带领下”相符。", "攻占": "语义：“攻占”是军事行动，与导游带领的游览相矛盾。", "修建": "语义：“修建”是建造，与“在导游带领下”的游览不符。", "装修": "语义：装修是对房屋做装饰，不是游览，在导游带领下不能“装修”古城。"}, "sentence_index": 6, "correct_answer": "观光"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司派他去非洲观光了一年。", "explanation": "这里应该用〈考察〉。“观光”是为游玩，考察是为调查研究。"}, {"text": "孩子们在教室里观光。", "explanation": "这里应该用〈上课〉。“观光”是游览风景，在教室里学习应该用上课。"}, {"text": "他每天在公司观光。", "explanation": "这里应该用〈办公〉。“观光”是游玩看风景，在公司工作要用办公。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b74e1261-5f5f-425d-9d1e-d585592b8400') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95434, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们下个月想去苏州观光了。", "corrected_sentence": "我们下个月想去苏州观光。", "error_description": "时态错误：“下个月”指将来，“观光”后不能加“了”，应改为“我们下个月想去苏州观光”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b74e1261-5f5f-425d-9d1e-d585592b8400') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95434, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们颐和园观光了一上午。", "corrected_sentence": "我们在颐和园观光了一上午。", "error_description": "介词缺失：表示处所的“在”不能省略，应说“在颐和园观光”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b74e1261-5f5f-425d-9d1e-d585592b8400') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
