INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95435, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对要进门的人说，请你走进来。", "primary_collocate": null, "pronunciation": "qǐng jìn", "ipa": "tɕʰiŋ˨˩˦ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "有人敲门，老师说：“请进！”", "target_word": "请进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“请进，门没有锁。”", "target_word": "请进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到敲门声，他大声说：“请进。”", "target_word": "请进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理在里面说：“请进，请坐。”", "target_word": "请进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我敲了门，里面的人说：“请进。”", "target_word": "请进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“请进，请进，不用换鞋。”", "target_word": "请进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门开着，王医生对我说：“请进。”", "target_word": "请进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她站在门口笑着说：“欢迎，请进！”", "target_word": "请进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“谁呀？请进！”奶奶在屋里喊。", "target_word": "请进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他敲门后，听到一声“请进”，就推门进去了。", "target_word": "请进", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "请进来", "label": "复合"}, {"form": "请进去", "label": "复合"}], "register": "中性", "sense_fingerprint": "对门外要进来的人说的招呼语：请你进来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e80955d-5d4f-40de-8cbf-bf9a5acaa222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95435, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "请进", "is_correct": true, "explanation": "请进 qǐng jìn：对门外要进来的人说的招呼语，正确答案。"}, {"text": "亲近", "is_correct": false, "explanation": "亲近 qīnjìn 的第一音节韵母为 -in、声调为第一声，与请进的 qǐng（-ng，第三声）不同，意思是关系密切。"}, {"text": "倾尽", "is_correct": false, "explanation": "倾尽 qīngjìn 只有第一音节声调不同（qīng 第一声，qǐng 第三声），意思是用尽全部。"}, {"text": "精进", "is_correct": false, "explanation": "精进 jīngjìn 的声母为 j（请进为 q），第一音节声调也不同，意思是努力上进。"}, {"text": "请见", "is_correct": false, "explanation": "请见 qǐngjiàn 第二音节韵母为 -ian（请进为 -in），意思是请求接见，也用于「请见附件」。"}], "explanations": {"请进": "请进 qǐng jìn：对门外要进来的人说的招呼语，正确答案。", "亲近": "亲近 qīnjìn 的第一音节韵母为 -in、声调为第一声，与请进的 qǐng（-ng，第三声）不同，意思是关系密切。", "倾尽": "倾尽 qīngjìn 只有第一音节声调不同（qīng 第一声，qǐng 第三声），意思是用尽全部。", "精进": "精进 jīngjìn 的声母为 j（请进为 q），第一音节声调也不同，意思是努力上进。", "请见": "请见 qǐngjiàn 第二音节韵母为 -ian（请进为 -in），意思是请求接见，也用于「请见附件」。"}, "sentence_index": null, "correct_answer": "请进"}, "level_3": {"options": [{"text": "请进", "is_correct": true, "explanation": "请进：对门外要进来的人说的招呼语，符合有人敲门的语境。"}, {"text": "请坐", "is_correct": false, "explanation": "语义：敲门后应先请人进门，请坐要在进门后才说，与敲门的语境冲突。"}, {"text": "请出去", "is_correct": false, "explanation": "语义：「请出去」是赶人离开，与对敲门人的礼貌招呼相矛盾。"}, {"text": "请回", "is_correct": false, "explanation": "搭配：「请回」多指请人返回，不接在敲门之后作招呼语。"}], "explanations": {"请进": "请进：对门外要进来的人说的招呼语，符合有人敲门的语境。", "请坐": "语义：敲门后应先请人进门，请坐要在进门后才说，与敲门的语境冲突。", "请出去": "语义：「请出去」是赶人离开，与对敲门人的礼貌招呼相矛盾。", "请回": "搭配：「请回」多指请人返回，不接在敲门之后作招呼语。"}, "sentence_index": 0, "correct_answer": "请进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他已经走进办公室了，我还在门口对他说：“请进。”", "explanation": "这里应该用〈请坐〉。请进是门外的人还没进来时招呼他进门，人已在屋里就不说请进。"}, {"text": "客人要走了，我对他说：“请进。”", "explanation": "这里应该用〈请慢走〉。请进是招呼人进来，客人离开时说请慢走。"}, {"text": "司机打开车门，对乘客说：“请进。”", "explanation": "这里应该用〈请上车〉。请进指请人进入房间或院子，招呼乘客上车要说请上车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992aa609-38af-47ce-a8c5-208f71a1ab07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95435, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "请进", "is_correct": true, "explanation": "请进：对门外要进来的人说的招呼语，符合门开着、王医生请我进屋的语境。"}, {"text": "请开门", "is_correct": false, "explanation": "语义：门已经开着，再请人开门与语境矛盾。"}, {"text": "请上车", "is_correct": false, "explanation": "搭配：「上车」用于车辆，不能用于进屋。"}, {"text": "请退后", "is_correct": false, "explanation": "语义：「请退后」是叫人往后站，与请人进屋的招呼相矛盾。"}], "explanations": {"请进": "请进：对门外要进来的人说的招呼语，符合门开着、王医生请我进屋的语境。", "请开门": "语义：门已经开着，再请人开门与语境矛盾。", "请上车": "搭配：「上车」用于车辆，不能用于进屋。", "请退后": "语义：「请退后」是叫人往后站，与请人进屋的招呼相矛盾。"}, "sentence_index": 6, "correct_answer": "请进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "还没有人敲门，他就大声说：“请进。”", "explanation": "这里应该用〈请稍等〉。请进要等有人敲门或来人时才说，没人来就说请进不合常理。"}, {"text": "我到了老同学家门口，对他说：“请进。”", "explanation": "这里应该用〈打扰了〉。请进是主人请客人进门时说的，客人到门口不能对主人说请进。"}, {"text": "孩子蹦蹦跳跳地跑出门，我说：“请进。”", "explanation": "这里应该用〈慢走〉。请进是请人进来，人正往外走时不说请进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992aa609-38af-47ce-a8c5-208f71a1ab07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95435, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "听到敲门声，老板说：“请进了吧。”", "corrected_sentence": "听到敲门声，老板说：“请进吧。”", "error_description": "错误：「请进了吧」；正确：「请进吧」。招呼别人进来是祈使语气，不能加「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992aa609-38af-47ce-a8c5-208f71a1ab07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95435, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "客人到了，他说：“请进着吧。”", "corrected_sentence": "客人到了，他说：“请进吧。”", "error_description": "错误：「请进着吧」；正确：「请进吧」。招呼别人进来是一次性的祈使，不能加表示持续的「着」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992aa609-38af-47ce-a8c5-208f71a1ab07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
