INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95441, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "路通向的那个方向。", "primary_collocate": null, "pronunciation": "lù xiàng", "ipa": "lu˥˩ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这条路的路向是向东。", "target_word": "路向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上能看清这条公路的路向。", "target_word": "路向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的小路，路向常常不好找。", "target_word": "路向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着地图，问我路向对不对。", "target_word": "路向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雪盖住了小路，看不出路向。", "target_word": "路向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我这条路的路向。", "target_word": "路向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里没有路牌，我们弄错了路向。", "target_word": "路向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人用手指着，说明了路向。", "target_word": "路向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两条公路的路向差不多。", "target_word": "路向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑以后，很难分清路向。", "target_word": "路向", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "道路实际通向的方位，如东、南、西、北", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebf1bab-7caf-4398-b821-cabf8dd12500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95441, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "路向", "is_correct": true, "explanation": "正确。路向 lù xiàng，指道路通向的方位。"}, {"text": "木像", "is_correct": false, "explanation": "mù 与 lù 声母不同（m 与 l），意思是木雕的像。"}, {"text": "具象", "is_correct": false, "explanation": "jù 与 lù 声母不同（j 与 l），意思是具体的形象，与道路方位无关。"}, {"text": "怒相", "is_correct": false, "explanation": "声母不同（n 与 l），声调相同，意思是愤怒的神色。"}, {"text": "立像", "is_correct": false, "explanation": "韵母不同（i 与 u），声调相同，意思是雕像，与道路无关。"}], "explanations": {"路向": "正确。路向 lù xiàng，指道路通向的方位。", "木像": "mù 与 lù 声母不同（m 与 l），意思是木雕的像。", "具象": "jù 与 lù 声母不同（j 与 l），意思是具体的形象，与道路方位无关。", "怒相": "声母不同（n 与 l），声调相同，意思是愤怒的神色。", "立像": "韵母不同（i 与 u），声调相同，意思是雕像，与道路无关。"}, "sentence_index": null, "correct_answer": "路向"}, "level_3": {"options": [{"text": "路向", "is_correct": true, "explanation": "正确。“这条路的路向是向东”中，路向指道路通向的方位，与“向东”呼应。"}, {"text": "路费", "is_correct": false, "explanation": "语义：路费指出行时付的钱，不是道路的方位，“路费是向东”说不通。"}, {"text": "路程", "is_correct": false, "explanation": "语义：路程指距离，不指方向，“这条路的路程是向东”说不通。"}, {"text": "路面", "is_correct": false, "explanation": "搭配：“路面”指路的表层，不能与“是向东”这样的方位搭配。"}], "explanations": {"路向": "正确。“这条路的路向是向东”中，路向指道路通向的方位，与“向东”呼应。", "路费": "语义：路费指出行时付的钱，不是道路的方位，“路费是向东”说不通。", "路程": "语义：路程指距离，不指方向，“这条路的路程是向东”说不通。", "路面": "搭配：“路面”指路的表层，不能与“是向东”这样的方位搭配。"}, "sentence_index": 0, "correct_answer": "路向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条公路的路向有两百公里长。", "explanation": "这里应该用〈路线〉。路向指道路通向的方位，说路有多长、怎么走要用路线。"}, {"text": "我们找到了最短的路向。", "explanation": "这里应该用〈路径〉。路向指方位，说最短的走法要用路径。"}, {"text": "这个路向太窄，车根本开不过去。", "explanation": "这里应该用〈道路〉。路向指道路通向的方位，不指道路本身，说路的宽窄要用道路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95441, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "路向", "is_correct": true, "explanation": "正确。路向 lù xiàng，指道路通向的方位。"}, {"text": "不像", "is_correct": false, "explanation": "声母不同（b 与 l），声调相同，意思是不相似。"}, {"text": "怒相", "is_correct": false, "explanation": "声母不同（n 与 l），声调相同，意思是愤怒的神色。"}, {"text": "巨象", "is_correct": false, "explanation": "jù 与 lù 声母不同（j 与 l），意思是体型巨大的象。"}, {"text": "立像", "is_correct": false, "explanation": "韵母不同（i 与 u），声调相同，意思是雕像，与道路无关。"}], "explanations": {"路向": "正确。路向 lù xiàng，指道路通向的方位。", "不像": "声母不同（b 与 l），声调相同，意思是不相似。", "怒相": "声母不同（n 与 l），声调相同，意思是愤怒的神色。", "巨象": "jù 与 lù 声母不同（j 与 l），意思是体型巨大的象。", "立像": "韵母不同（i 与 u），声调相同，意思是雕像，与道路无关。"}, "sentence_index": null, "correct_answer": "路向"}, "level_3": {"options": [{"text": "路向", "is_correct": true, "explanation": "正确。前文“没有路牌”说明难以辨认方位，“弄错了”的正是道路通向的方向。"}, {"text": "路灯", "is_correct": false, "explanation": "语义：路灯是照明设备，不是方位，不能被“弄错”。"}, {"text": "路人", "is_correct": false, "explanation": "语义：路人指路上的行人，与“弄错”的对象不搭。"}, {"text": "路桥", "is_correct": false, "explanation": "搭配：“路桥”指道路与桥梁，与“弄错”这样的动作不搭配。"}], "explanations": {"路向": "正确。前文“没有路牌”说明难以辨认方位，“弄错了”的正是道路通向的方向。", "路灯": "语义：路灯是照明设备，不是方位，不能被“弄错”。", "路人": "语义：路人指路上的行人，与“弄错”的对象不搭。", "路桥": "搭配：“路桥”指道路与桥梁，与“弄错”这样的动作不搭配。"}, "sentence_index": 6, "correct_answer": "路向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "从这里到学校的路向有三十公里。", "explanation": "这里应该用〈路程〉。路向指方位，说距离有多远要用路程。"}, {"text": "这段公路的路向很差，车开得很颠。", "explanation": "这里应该用〈路况〉。路向指方位，说路面和路的好坏要用路况。"}, {"text": "这一路向很窄，只能过一辆车。", "explanation": "这里应该用〈路段〉。路向指方位，说一段路的宽窄要用路段。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95441, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我问了路人，这条路向对不对？", "corrected_sentence": "我问了路人，这个路向对不对？", "error_description": "错误形式：“这条路向”；正确形式：“这个路向”。“条”用于路本身（如“这条路”），指方位的“路向”应用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95441, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我看清了山上小路路向。", "corrected_sentence": "我看清了山上小路的路向。", "error_description": "错误形式：“小路路向”；正确形式：“小路的路向”。修饰“路向”的名词之后须加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
