INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95447, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把借来的东西送回去给主人。", "primary_collocate": null, "pronunciation": "sòng huán", "ipa": "sʊŋ˥˩ xwan˧˥", "syllable_count": 2, "sentences": [{"text": "我骑车把借来的自行车送还主人。", "target_word": "送还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他亲自走到张叔叔家，送还了锤子。", "target_word": "送还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我周末要去同学家送还相机。", "target_word": "送还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停以后，我马上把借来的伞送还给老王。", "target_word": "送还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟把借走的球送还到我房间。", "target_word": "送还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她拿着借来的锅，走去送还邻居。", "target_word": "送还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服是借的，我得送还给姐姐。", "target_word": "送还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他骑着车，把书送还到朋友家。", "target_word": "送还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李把借的照相机送还给了主人。", "target_word": "送还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚饭后，我们一起把借来的桌椅送还。", "target_word": "送还", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "送还了", "label": "体标（了）"}, {"form": "送还过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "亲自把借来的东西送到主人那里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebf1bab-7caf-4398-b821-cabf8dd12500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95447, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "送还", "is_correct": true, "explanation": "正确。“我骑车把借来的自行车送还主人”，指亲自把借来的车送回原主人那里，与“骑车”“借来的”相符。"}, {"text": "赠送", "is_correct": false, "explanation": "语义：赠送指把东西送人，与“借来的”自行车矛盾。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是物件，不能说“修理主人”。"}, {"text": "锁", "is_correct": false, "explanation": "语义：“锁”指把门、车等锁上，不能用于把车送给主人。"}], "explanations": {"送还": "正确。“我骑车把借来的自行车送还主人”，指亲自把借来的车送回原主人那里，与“骑车”“借来的”相符。", "赠送": "语义：赠送指把东西送人，与“借来的”自行车矛盾。", "修理": "搭配：“修理”的对象是物件，不能说“修理主人”。", "锁": "语义：“锁”指把门、车等锁上，不能用于把车送给主人。"}, "sentence_index": 0, "correct_answer": "送还"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我从来没向老王借过伞，雨停以后，我却把伞送还给了他。", "explanation": "这里应该用〈送给〉。送还要求东西是借来的，此处并未借过伞，应说送给。"}, {"text": "雨中，我们在车站送还老王。", "explanation": "这里应该用〈送别〉。送还指归还借来的东西，此处是在车站告别老王，应说送别。"}, {"text": "警察把犯人送还到了法院。", "explanation": "这里应该用〈押送〉。送还指归还借来的东西，犯人并非借来的，押送犯人应说押送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95447, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "送还", "is_correct": true, "explanation": "正确。“这件衣服是借的，我得送还给姐姐”，指把借来的衣服还给原主，与“借的”相符。"}, {"text": "偷", "is_correct": false, "explanation": "语义：“偷”指暗中拿别人的东西，与把衣服还给姐姐的语境不符。"}, {"text": "烧", "is_correct": false, "explanation": "搭配：“烧给”多用于祭奠亡者，不能用于活人。"}, {"text": "砍", "is_correct": false, "explanation": "语义：“砍”指用刀斧等切断，与归还衣服的语境不符。"}], "explanations": {"送还": "正确。“这件衣服是借的，我得送还给姐姐”，指把借来的衣服还给原主，与“借的”相符。", "偷": "语义：“偷”指暗中拿别人的东西，与把衣服还给姐姐的语境不符。", "烧": "搭配：“烧给”多用于祭奠亡者，不能用于活人。", "砍": "语义：“砍”指用刀斧等切断，与归还衣服的语境不符。"}, "sentence_index": 6, "correct_answer": "送还"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家在门口送还刚到的客人。", "explanation": "这里应该用〈欢迎〉。送还只用于归还借来的东西，迎接刚到的客人要用欢迎。"}, {"text": "这些桌椅是我们刚买的，还没借给过别人，却已经送还了出去。", "explanation": "这里应该用〈出售〉。送还指归还借来的东西，刚买的东西没有借过，应说出售。"}, {"text": "学校接待了一位来访的专家，又把他送还了。", "explanation": "这里应该用〈接待〉。送还指归还借来的东西，专家并非借来的，接待来访者应说接待。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95447, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天骑车把借来的自行车送还了给主人。", "corrected_sentence": "我昨天骑车把借来的自行车送还给了主人。", "error_description": "错误形式：“送还了给主人”；正确形式：“送还给了主人”。“了”不能插在“送还”和“给”之间，应放在“给”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95447, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件衣服是借来的，我还得送还了给姐姐。", "corrected_sentence": "这件衣服是借来的，我还得送还给姐姐。", "error_description": "错误形式：“送还了给”；正确形式：“送还给”。“了”不能插在“送还”和“给”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
