INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95448, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95448, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把借用或拿来的东西归还。", "primary_collocate": null, "pronunciation": "sòng huán", "ipa": "sʊŋ˥˩ xwan˧˥", "syllable_count": 2, "sentences": [{"text": "你用完词典，请记得送还图书馆。", "target_word": "送还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把借的伞送还给我了。", "target_word": "送还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些借来的书，明天必须送还。", "target_word": "送还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我拿错了你的笔，现在送还给你。", "target_word": "送还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把朋友的外套洗好，送还了。", "target_word": "送还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "借的东西用完要及时送还。", "target_word": "送还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明把从同学那儿拿来的玩具送还了。", "target_word": "送还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居送还了上个月借走的梯子。", "target_word": "送还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直没有送还我的那本小说。", "target_word": "送还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们把拿来的工具送还。", "target_word": "送还", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "送还了", "label": "体标（了）"}, {"form": "送还过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "把借用或拿来的东西归还", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebf1bab-7caf-4398-b821-cabf8dd12500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95448, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "送还", "is_correct": true, "explanation": "正确。“送还”指把借来的东西还回去，与“用完词典”的语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，不能用于图书馆。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”只能带歌曲等对象，不能带“图书馆”作宾语。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”指拆毁或拆开，与“用完词典后归还”的语境不符。"}], "explanations": {"送还": "正确。“送还”指把借来的东西还回去，与“用完词典”的语境相符。", "吃": "语义：“吃”指进食，不能用于图书馆。", "唱": "搭配：“唱”只能带歌曲等对象，不能带“图书馆”作宾语。", "拆": "语义：“拆”指拆毁或拆开，与“用完词典后归还”的语境不符。"}, "sentence_index": 0, "correct_answer": "送还"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在车站送还朋友。", "explanation": "这里应该用〈送别〉。送还指归还借来的东西，在车站告别朋友应说送别。"}, {"text": "这是我第一次见到他，他却把伞送还给了我。", "explanation": "这里应该用〈送给〉。送还要求东西借自对方，初次见面就送还伞，应说送给。"}, {"text": "我把写好的信送还给了老师。", "explanation": "这里应该用〈寄送〉。送还只用于归还借来的东西，寄出自己写的信不是归还，要用寄送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95448, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "送还", "is_correct": true, "explanation": "正确。“小明把玩具送还了”，送还指归还借来的玩具，与“拿来的”相符。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”只用于食物，不能用于玩具。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”只与饮品等搭配，不能说“喝玩具”。"}, {"text": "送别", "is_correct": false, "explanation": "语义：送别指告别将要离开的人，不能用于玩具。"}], "explanations": {"送还": "正确。“小明把玩具送还了”，送还指归还借来的玩具，与“拿来的”相符。", "煮": "语义：“煮”只用于食物，不能用于玩具。", "喝": "搭配：“喝”只与饮品等搭配，不能说“喝玩具”。", "送别": "语义：送别指告别将要离开的人，不能用于玩具。"}, "sentence_index": 6, "correct_answer": "送还"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家在门口送还刚到的新同学。", "explanation": "这里应该用〈欢迎〉。送还只用于归还借来的东西，迎接刚到的人要用欢迎。"}, {"text": "我还没借过他的东西，他却把那本书送还给了我。", "explanation": "这里应该用〈赠送〉。送还要求东西借自对方，此处并未借过，应说赠送。"}, {"text": "工人把货物送还到了工厂，工厂却没有借过这批货。", "explanation": "这里应该用〈运送〉。送还要求东西借自对方，工厂并未借过货物，应说运送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95448, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我已经把新买的书送还给图书馆了。", "corrected_sentence": "我已经把借来的书送还给图书馆了。", "error_description": "错误：“新买的书”没有借过，不能用“送还”。“送还”只用于归还借来或拿来的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95448, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把借的钥匙送还了给邻居。", "corrected_sentence": "我把借的钥匙送还给了邻居。", "error_description": "错误形式：“送还了给”；正确形式：“送还给了”。“了”应放在“送还给”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95449, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出生", "is_correct": true, "explanation": "正确：出生与逝世是一对反义词，分别指人降生与去世。"}, {"text": "工作", "is_correct": false, "explanation": "与“逝世”没有反义关系，只是同属动词，意思无对立。"}, {"text": "旅行", "is_correct": false, "explanation": "与“逝世”没有反义关系，指外出游览，与去世无对立。"}, {"text": "睡觉", "is_correct": false, "explanation": "与“逝世”没有反义关系，指休息入睡，二者不构成对立。"}], "correct_answer": "出生", "explanations": {"出生": "正确：出生与逝世是一对反义词，分别指人降生与去世。", "工作": "与“逝世”没有反义关系，只是同属动词，意思无对立。", "旅行": "与“逝世”没有反义关系，指外出游览，与去世无对立。", "睡觉": "与“逝世”没有反义关系，指休息入睡，二者不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ac0ca0-d16b-45be-ac1e-5dbb03f8730c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95449, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出生", "is_correct": true, "explanation": "正确：出生与逝世是一对反义词，分别指人降生与去世。"}, {"text": "学习", "is_correct": false, "explanation": "与“逝世”没有反义关系，指获取知识，与去世无对立。"}, {"text": "读书", "is_correct": false, "explanation": "与“逝世”没有反义关系，指阅读书籍，与去世无对立。"}, {"text": "唱歌", "is_correct": false, "explanation": "与“逝世”没有反义关系，指发出乐音，与去世无对立。"}], "correct_answer": "出生", "explanations": {"出生": "正确：出生与逝世是一对反义词，分别指人降生与去世。", "学习": "与“逝世”没有反义关系，指获取知识，与去世无对立。", "读书": "与“逝世”没有反义关系，指阅读书籍，与去世无对立。", "唱歌": "与“逝世”没有反义关系，指发出乐音，与去世无对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ac0ca0-d16b-45be-ac1e-5dbb03f8730c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95449, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对很受人尊敬的人去世的说法。", "primary_collocate": null, "pronunciation": "shì shì", "ipa": "ʂɻ̩˥˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他尊敬的老师上个月逝世。", "target_word": "逝世", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老教授逝世时，学生都来送他。", "target_word": "逝世", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先生逝世的那天，天正下着雨。", "target_word": "逝世", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说那位老先生是半夜逝世的。", "target_word": "逝世", "complexity_tier": "T3", "furigana": "yīshēng shuō nà wèi lǎo xiānsheng shì bànyè shìshì de.", "sentence_source": "generated"}, {"text": "她尊敬的外婆去年冬天逝世。", "target_word": "逝世", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老英雄逝世后，人们把他的故事写成书。", "target_word": "逝世", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们为逝世的老前辈默哀。", "target_word": "逝世", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位诗人在家乡逝世。", "target_word": "逝世", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直怀念逝世的恩师。", "target_word": "逝世", "complexity_tier": "T3", "furigana": "tā yìzhí huáiniàn shìshì de ēnshī.", "sentence_source": "generated"}, {"text": "老将军逝世的消息传来，大家都沉默了。", "target_word": "逝世", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "逝世了", "label": "体标"}], "register": "正式", "sense_fingerprint": "谈到很受尊敬的人去世时的说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55addd89-518c-40da-814b-2ea91ff12618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95449, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "逝世", "is_correct": true, "explanation": "正确：逝世，对很受人尊敬的人去世的说法。"}, {"text": "实事", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）第一音节声调不同，意思是“实事”，指实际的事情。"}, {"text": "史事", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）第一音节声调不同，意思是“史事”，指历史上的事件。"}, {"text": "试试", "is_correct": false, "explanation": "第二音节为轻声，与 shì（第四声）声调不同，意思是“试一试”。"}], "explanations": {"逝世": "正确：逝世，对很受人尊敬的人去世的说法。", "实事": "shí（第二声）与 shì（第四声）第一音节声调不同，意思是“实事”，指实际的事情。", "史事": "shǐ（第三声）与 shì（第四声）第一音节声调不同，意思是“史事”，指历史上的事件。", "试试": "第二音节为轻声，与 shì（第四声）声调不同，意思是“试一试”。"}, "sentence_index": null, "correct_answer": "逝世"}, "level_3": {"options": [{"text": "逝世", "is_correct": true, "explanation": "正确。逝世表示去世，与“上个月”的时间词相配。"}, {"text": "融化", "is_correct": false, "explanation": "语义：融化用于冰、雪等物体，不能用于人。"}, {"text": "出版", "is_correct": false, "explanation": "配价：出版需要带宾语，单独用于此处不成立。"}, {"text": "降雨", "is_correct": false, "explanation": "语义：降雨是天气现象，不能用于人。"}], "explanations": {"逝世": "正确。逝世表示去世，与“上个月”的时间词相配。", "融化": "语义：融化用于冰、雪等物体，不能用于人。", "出版": "配价：出版需要带宾语，单独用于此处不成立。", "降雨": "语义：降雨是天气现象，不能用于人。"}, "sentence_index": 0, "correct_answer": "逝世"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的同桌小明上周逝世了，大家都很难过。", "explanation": "这里应该用〈去世〉。〈逝世〉是敬称，只用于受人尊敬的人，不用于同学。"}, {"text": "我家的金鱼昨天逝世了，我哭了很久。", "explanation": "这里应该用〈死〉。〈逝世〉只用于受人尊敬的人，不用于鱼。"}, {"text": "那台老式收音机去年逝世了，我没舍得扔。", "explanation": "这里应该用〈报废〉。〈逝世〉只用于受人尊敬的人，不用于收音机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ac0ca0-d16b-45be-ac1e-5dbb03f8730c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95449, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "逝世", "is_correct": true, "explanation": "正确：逝世，对很受人尊敬的人去世的说法。"}, {"text": "时事", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）第一音节声调不同，意思是“时事”，指当前发生的事情。"}, {"text": "失事", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）第一音节声调不同，意思是“失事”，指发生事故。"}, {"text": "事实", "is_correct": false, "explanation": "shì shí（第二声）与 shì shì（第四声）第二音节声调不同，意思是“事实”。"}], "explanations": {"逝世": "正确：逝世，对很受人尊敬的人去世的说法。", "时事": "shí（第二声）与 shì（第四声）第一音节声调不同，意思是“时事”，指当前发生的事情。", "失事": "shī（第一声）与 shì（第四声）第一音节声调不同，意思是“失事”，指发生事故。", "事实": "shì shí（第二声）与 shì shì（第四声）第二音节声调不同，意思是“事实”。"}, "sentence_index": null, "correct_answer": "逝世"}, "level_3": {"options": [{"text": "逝世", "is_correct": true, "explanation": "正确。“逝世的”修饰老前辈，表示已经去世，与默哀相符。"}, {"text": "生病", "is_correct": false, "explanation": "语义：默哀是对已去世者的悼念，“生病的老前辈”不需要默哀。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步是活人的日常活动，与默哀不搭。"}, {"text": "写", "is_correct": false, "explanation": "配价：“写”需要带宾语（如“文章”），“写的老前辈”不成立。"}], "explanations": {"逝世": "正确。“逝世的”修饰老前辈，表示已经去世，与默哀相符。", "生病": "语义：默哀是对已去世者的悼念，“生病的老前辈”不需要默哀。", "散步": "语义：散步是活人的日常活动，与默哀不搭。", "写": "配价：“写”需要带宾语（如“文章”），“写的老前辈”不成立。"}, "sentence_index": 6, "correct_answer": "逝世"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这棵老树前年逝世，树叶都落光了。", "explanation": "这里应该用〈枯死〉。〈逝世〉只用于人，不能用于树。"}, {"text": "这条小河去年逝世了，村里的人很伤心。", "explanation": "这里应该用〈干涸〉。〈逝世〉只用于人，不能用于河流。"}, {"text": "那辆旧自行车去年逝世了，车链子也断了。", "explanation": "这里应该用〈报废〉。〈逝世〉只用于人，不能用于自行车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ac0ca0-d16b-45be-ac1e-5dbb03f8730c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95449, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那位老工程师上个月被逝世了。", "corrected_sentence": "那位老工程师上个月逝世了。", "error_description": "被字句错误：“逝世”不能用“被”构成被动句。应改为“那位老工程师上个月逝世了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ac0ca0-d16b-45be-ac1e-5dbb03f8730c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95449, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老英雄在战场上逝世着。", "corrected_sentence": "老英雄在战场上逝世了。", "error_description": "“了”“着”用错：“逝世”表示一次性完成的变化，应用“了”，不能用“着”。应改为“在战场上逝世了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ac0ca0-d16b-45be-ac1e-5dbb03f8730c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95453, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "早", "is_correct": true, "explanation": "“早”与“迟”相对，指比约定时间靠前，是本义项的反义词。"}, {"text": "深", "is_correct": false, "explanation": "“深”与“迟”没有反义关系，“深”说距离或程度的深浅。"}, {"text": "硬", "is_correct": false, "explanation": "“硬”说质地，与“迟”的时间义没有反义关系。"}, {"text": "新", "is_correct": false, "explanation": "“新”与“旧”相对，与“迟”没有反义关系。"}], "correct_answer": "早", "explanations": {"早": "“早”与“迟”相对，指比约定时间靠前，是本义项的反义词。", "深": "“深”与“迟”没有反义关系，“深”说距离或程度的深浅。", "硬": "“硬”说质地，与“迟”的时间义没有反义关系。", "新": "“新”与“旧”相对，与“迟”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b74e1261-5f5f-425d-9d1e-d585592b8400') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
