INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95453, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "比说好的时间晚了。", "primary_collocate": null, "pronunciation": "chí", "ipa": "ʈʂʰɻ̩˧˥", "syllable_count": 1, "sentences": [{"text": "对不起，我来迟了。", "target_word": "迟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "说好八点见面，你来得太迟了。", "target_word": "迟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车坏了，所以我回来迟了。", "target_word": "迟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每次约会都来得很迟。", "target_word": "迟", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你怎么现在才来？有点迟了吧。", "target_word": "迟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们说好六点吃饭，他到得迟了一点。", "target_word": "迟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对不起，让你等了这么久，我来迟了。", "target_word": "迟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "快递说好今天到，却迟了两天。", "target_word": "迟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他总是早到，今天却迟了十分钟。", "target_word": "迟", "complexity_tier": "T3", "furigana": "tā zǒngshì zǎo dào, jīntiān què chí le shí fēnzhōng.", "sentence_source": "generated"}, {"text": "我知道自己迟了，一路跑着来。", "target_word": "迟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "迟了", "label": "体标"}, {"form": "迟到", "label": "复合"}, {"form": "遲", "label": "繁体"}], "register": "中性", "sense_fingerprint": "比约好的时间到得晚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6595b4a5-d1da-4ecc-9c20-7ed1df0b6017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95453, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "迟", "is_correct": true, "explanation": "正确答案。“迟”读 chí，指比约好的时间晚。"}, {"text": "吃", "is_correct": false, "explanation": "chī（第一声）与 chí（第二声）声调不同，意思是吃。"}, {"text": "尺", "is_correct": false, "explanation": "chǐ（第三声）与 chí（第二声）声调不同，意思是尺子。"}, {"text": "翅", "is_correct": false, "explanation": "chì（第四声）与 chí（第二声）声调不同，意思是翅膀。"}, {"text": "赤", "is_correct": false, "explanation": "chì（第四声）与 chí（第二声）声调不同，意思是红色。"}], "explanations": {"迟": "正确答案。“迟”读 chí，指比约好的时间晚。", "吃": "chī（第一声）与 chí（第二声）声调不同，意思是吃。", "尺": "chǐ（第三声）与 chí（第二声）声调不同，意思是尺子。", "翅": "chì（第四声）与 chí（第二声）声调不同，意思是翅膀。", "赤": "chì（第四声）与 chí（第二声）声调不同，意思是红色。"}, "sentence_index": null, "correct_answer": "迟"}, "level_3": {"options": [{"text": "迟", "is_correct": true, "explanation": "正确答案。“迟”表示比约好的时间晚，符合“对不起，我来迟了”的致歉语境。"}, {"text": "早", "is_correct": false, "explanation": "语义：“早”说到得太早，与“对不起”的致歉语境相反。"}, {"text": "深", "is_correct": false, "explanation": "语义：“深”说深浅，“我来深了”不成立，与致歉语境不合。"}, {"text": "久", "is_correct": false, "explanation": "语义：“久”说时间长，“来久了”指到达已经很久，与“对不起”的致歉语境不合。"}], "explanations": {"迟": "正确答案。“迟”表示比约好的时间晚，符合“对不起，我来迟了”的致歉语境。", "早": "语义：“早”说到得太早，与“对不起”的致歉语境相反。", "深": "语义：“深”说深浅，“我来深了”不成立，与致歉语境不合。", "久": "语义：“久”说时间长，“来久了”指到达已经很久，与“对不起”的致歉语境不合。"}, "sentence_index": 0, "correct_answer": "迟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个西瓜很迟。", "explanation": "这里应该用〈重〉。“迟”只表示时间，不能形容东西的轻重，西瓜的重量要用“重”。"}, {"text": "我家离学校很迟。", "explanation": "这里应该用〈远〉。“迟”只用于时间，不能形容两地之间的距离。"}, {"text": "今天天气很迟。", "explanation": "这里应该用〈热〉。“迟”只用于时间，不能形容天气的冷热。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b74e1261-5f5f-425d-9d1e-d585592b8400') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95453, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "迟", "is_correct": true, "explanation": "正确答案。“迟”读 chí，指比约好的时间晚。"}, {"text": "齿", "is_correct": false, "explanation": "chǐ（第三声）与 chí（第二声）声调不同，意思是牙齿。"}, {"text": "痴", "is_correct": false, "explanation": "chī（第一声）与 chí（第二声）声调不同，意思是痴呆。"}, {"text": "斥", "is_correct": false, "explanation": "chì（第四声）与 chí（第二声）声调不同，意思是斥责。"}, {"text": "炽", "is_correct": false, "explanation": "chì（第四声）与 chí（第二声）声调不同，意思是火旺、炽热。"}], "explanations": {"迟": "正确答案。“迟”读 chí，指比约好的时间晚。", "齿": "chǐ（第三声）与 chí（第二声）声调不同，意思是牙齿。", "痴": "chī（第一声）与 chí（第二声）声调不同，意思是痴呆。", "斥": "chì（第四声）与 chí（第二声）声调不同，意思是斥责。", "炽": "chì（第四声）与 chí（第二声）声调不同，意思是火旺、炽热。"}, "sentence_index": null, "correct_answer": "迟"}, "level_3": {"options": [{"text": "迟", "is_correct": true, "explanation": "正确答案。“迟”表示比约好的时间晚，符合“我来迟了”的致歉语境。"}, {"text": "快", "is_correct": false, "explanation": "语义：“快”说速度快，“我来快了”与“让你等了这么久”的语境相反。"}, {"text": "远", "is_correct": false, "explanation": "搭配：“来”后接“远”说路程远，不能说“我来远了”来表示迟到。"}, {"text": "近", "is_correct": false, "explanation": "语义：“近”说距离近，“我来近了”不指迟到，与“等了这么久”的语境矛盾。"}], "explanations": {"迟": "正确答案。“迟”表示比约好的时间晚，符合“我来迟了”的致歉语境。", "快": "语义：“快”说速度快，“我来快了”与“让你等了这么久”的语境相反。", "远": "搭配：“来”后接“远”说路程远，不能说“我来远了”来表示迟到。", "近": "语义：“近”说距离近，“我来近了”不指迟到，与“等了这么久”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "迟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的成绩比去年迟了一些。", "explanation": "这里应该用〈高〉。“迟”只表示时间晚，成绩的提高要用“高”。"}, {"text": "这把椅子很迟。", "explanation": "这里应该用〈矮〉。“迟”只用于时间，不能形容椅子的高矮。"}, {"text": "他在这里住了很迟。", "explanation": "这里应该用〈久〉。“迟”不用于表示持续时间的长短，说住了很久要用“久”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b74e1261-5f5f-425d-9d1e-d585592b8400') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_us