INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95453, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们说好九点见面，他来了迟。", "corrected_sentence": "我们说好九点见面，他来迟了。", "error_description": "错误形式：“来了迟”；正确形式：“来迟了”。表示完成的“了”要放在补语“迟”之后，放在“迟”之前不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b74e1261-5f5f-425d-9d1e-d585592b8400') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95453, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们约好八点见面，他又了迟。", "corrected_sentence": "我们约好八点见面，他又迟了。", "error_description": "错误形式：“了迟”；正确形式：“迟了”。表示变化或完成的“了”要放在“迟”之后，“又了迟”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b74e1261-5f5f-425d-9d1e-d585592b8400') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
