INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95454, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们计划地太迟，任务完不成了。", "corrected_sentence": "我们计划得太迟，任务完不成了。", "error_description": "错误形式：“地”；正确形式：“得”。“太迟”是“计划”的补语，补语前要用“得”，不用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b74e1261-5f5f-425d-9d1e-d585592b8400') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95454, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们种菜种太得迟，收不成了。", "corrected_sentence": "我们种菜种得太迟，收不成了。", "error_description": "错误形式：“太得迟”；正确形式：“种得太迟”。“得”要紧接动词“种”，放在动词和补语“太迟”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b74e1261-5f5f-425d-9d1e-d585592b8400') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95459, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "家养", "is_correct": true, "explanation": "反义：“家养”指人饲养的，与“野生”（自然中自行生长）相对。"}, {"text": "迅速", "is_correct": false, "explanation": "无关：“迅速”形容速度快，与动物的来源无关。"}, {"text": "安静", "is_correct": false, "explanation": "无关：“安静”形容状态平和，与动物的来源无关。"}, {"text": "清楚", "is_correct": false, "explanation": "无关：“清楚”形容明白，与动物的来源无关。"}], "correct_answer": "家养", "explanations": {"家养": "反义：“家养”指人饲养的，与“野生”（自然中自行生长）相对。", "迅速": "无关：“迅速”形容速度快，与动物的来源无关。", "安静": "无关：“安静”形容状态平和，与动物的来源无关。", "清楚": "无关：“清楚”形容明白，与动物的来源无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95459, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "人工", "is_correct": true, "explanation": "反义：“人工”指人为培育，与“野生”相对。"}, {"text": "灿烂", "is_correct": false, "explanation": "无关：“灿烂”形容光彩夺目，与花的来源无关。"}, {"text": "锋利", "is_correct": false, "explanation": "无关：“锋利”形容刀刃等尖锐，与花的来源无关。"}, {"text": "冷淡", "is_correct": false, "explanation": "无关：“冷淡”形容态度，与花的来源无关。"}], "correct_answer": "人工", "explanations": {"人工": "反义：“人工”指人为培育，与“野生”相对。", "灿烂": "无关：“灿烂”形容光彩夺目，与花的来源无关。", "锋利": "无关：“锋利”形容刀刃等尖锐，与花的来源无关。", "冷淡": "无关：“冷淡”形容态度，与花的来源无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95459, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不是人养的，自己在山里和树林里长大的。", "primary_collocate": null, "pronunciation": "yě shēng", "ipa": "jɛ˨˩ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "山里的这只小鹿没人养，是野生的。", "target_word": "野生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树林中长着很多野生的果树。", "target_word": "野生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只鸟不是人养的，是野生的。", "target_word": "野生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在山里看见一群野生的猴子。", "target_word": "野生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说这些野生竹子没人种过。", "target_word": "野生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "野生的小马在树林里自己长大。", "target_word": "野生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶从山上采了野生的草莓。", "target_word": "野生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的树都是野生的，没人栽。", "target_word": "野生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里的野生兔子很怕人。", "target_word": "野生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山坡上那些花都是野生的。", "target_word": "野生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "野生动物", "label": "复合词"}, {"form": "野生植物", "label": "复合词"}], "register": "中性", "sense_fingerprint": "不是人养的，在山林里自己长大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebf1bab-7caf-4398-b821-cabf8dd12500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95459, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "野生", "is_correct": true, "explanation": "正确：“野生”指不是人养的、在山里自己长大，与句意相符。"}, {"text": "家养", "is_correct": false, "explanation": "语义：“家养”指人饲养的，与“山里”的自然环境矛盾。"}, {"text": "凶猛", "is_correct": false, "explanation": "语义：“凶猛”形容性情暴烈，不适合用来描述这只小鹿。"}, {"text": "人工", "is_correct": false, "explanation": "语义：“人工”指人为培育的，与“没人养”的小鹿矛盾。"}], "explanations": {"野生": "正确：“野生”指不是人养的、在山里自己长大，与句意相符。", "家养": "语义：“家养”指人饲养的，与“山里”的自然环境矛盾。", "凶猛": "语义：“凶猛”形容性情暴烈，不适合用来描述这只小鹿。", "人工": "语义：“人工”指人为培育的，与“没人养”的小鹿矛盾。"}, "sentence_index": 0, "correct_answer": "野生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的那只狗很野生，每天都在门口等我回家。", "explanation": "这里应该用〈家养〉。“野生”指不是人养的，而句中的狗在门口等主人，说明是家养的。"}, {"text": "他买了一台野生的电脑，很快就坏了。", "explanation": "这里应该用〈人造〉。“野生”指不是人养、自己长大的动植物，电脑是人造产品，不能用“野生”形容。"}, {"text": "他每天野生地喂养这群猴子。", "explanation": "这里应该用〈饲养〉。“野生”指不是人养的，而句中是每天人工喂养，应说“饲养”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95459, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "野生", "is_correct": true, "explanation": "正确：“野生”指草莓在山上自然生长，与句意相符。"}, {"text": "人工", "is_correct": false, "explanation": "语义：“人工”指人为培育，与“从山上采”的情境矛盾。"}, {"text": "昏暗", "is_correct": false, "explanation": "搭配：“昏暗”形容光线，不能修饰草莓。"}, {"text": "沉重", "is_correct": false, "explanation": "体貌：“沉重”形容重量，草莓不会用这样的特征来形容。"}], "explanations": {"野生": "正确：“野生”指草莓在山上自然生长，与句意相符。", "人工": "语义：“人工”指人为培育，与“从山上采”的情境矛盾。", "昏暗": "搭配：“昏暗”形容光线，不能修饰草莓。", "沉重": "体貌：“沉重”形容重量，草莓不会用这样的特征来形容。"}, "sentence_index": 6, "correct_answer": "野生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的脾气很野生，从来不生气。", "explanation": "这里把“野生”误用为“性情粗野”的意思。“野生”只指动植物不是人养、自己长大的，不用来形容人的脾气，应说“脾气很野”。"}, {"text": "这些花都是野生培育的，花店里每天都有新货。", "explanation": "这里应该用〈人工〉。“野生”指没有人培育，句中的“培育”说明是人工培育的。"}, {"text": "这里的野生花很多，都是花店买的。", "explanation": "这里应该用〈人工〉。“野生”指不是人养、自己长大的，花店买来的花是人工栽培的，句中不能说“野生花”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95459, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山里有一群野生地猴子。", "corrected_sentence": "山里有一群野生的猴子。", "error_description": "错误形式：“野生地猴子”；正确形式：“野生的猴子”。“野生”修饰名词“猴子”时要用“的”，“地”只用于修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95459, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些草莓野生的长在山坡上。", "corrected_sentence": "这些草莓野生地长在山坡上。", "error_description": "“野生”作状语修饰动词“长”时要用“地”，说“野生地长”，不说“野生的长”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95460, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "人工", "is_correct": true, "explanation": "反义：蘑菇人工栽培，与“野生”（自然生长）相对。"}, {"text": "美丽", "is_correct": false, "explanation": "无关：“美丽”形容外貌好看，与生长方式无关。"}, {"text": "巨大", "is_correct": false, "explanation": "无关：“巨大”形容体积，与生长方式无关。"}, {"text": "安静", "is_correct": false, "explanation": "无关：“安静”形容状态平和，与生长方式无关。"}], "correct_answer": "人工", "explanations": {"人工": "反义：蘑菇人工栽培，与“野生”（自然生长）相对。", "美丽": "无关：“美丽”形容外貌好看，与生长方式无关。", "巨大": "无关：“巨大”形容体积，与生长方式无关。", "安静": "无关：“安静”形容状态平和，与生长方式无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95460, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "人工", "is_correct": true, "explanation": "反义：茶树人工栽培，与“野生”相对。"}, {"text": "陡峭", "is_correct": false, "explanation": "无关：“陡峭”形容山坡的坡度，与生长方式无关。"}, {"text": "迅速", "is_correct": false, "explanation": "无关：“迅速”形容速度快，与生长方式无关。"}, {"text": "清晰", "is_correct": false, "explanation": "无关：“清晰”形容清楚明白，与生长方式无关。"}], "correct_answer": "人工", "explanations": {"人工": "反义：茶树人工栽培，与“野生”相对。", "陡峭": "无关：“陡峭”形容山坡的坡度，与生长方式无关。", "迅速": "无关：“迅速”形容速度快，与生长方式无关。", "清晰": "无关：“清晰”形容清楚明白，与生长方式无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95460, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "动植物在自然环境中自行生长的，不是人工饲养或栽培的。", "primary_collocate": null, "pronunciation": "yě shēng", "ipa": "jɛ˨˩ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "这个保护区有很多野生动物。", "target_word": "野生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "野生鱼比养的鱼贵很多。", "target_word": "野生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的野生植物越来越少了。", "target_word": "野生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种野生蘑菇不能随便吃。", "target_word": "野生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场上卖的是野生蜂蜜，价格不低。", "target_word": "野生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拍了许多野生鸟类的照片。", "target_word": "野生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "野生老虎的数量一直在减少。", "target_word": "野生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些花是野生的，不是花店买的。", "target_word": "野生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究人员在海边观察野生海龟。", "target_word": "野生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "野生茶树长在高山上，产量很少。", "target_word": "野生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "野生动物", "label": "复合词"}, {"form": "野生植物", "label": "复合词"}], "register": "中性", "sense_fingerprint": "动植物在自然中自行生长，非人工饲养或栽培", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebf1bab-7caf-4398-b821-cabf8dd12500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95460, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "野生", "is_correct": true, "explanation": "正确：“野生”指动物在自然中自行生长，保护区里的动物正是如此。"}, {"text": "人工", "is_correct": false, "explanation": "语义：“人工”指人为造出或培育的，保护区里的动物不应是人造的。"}, {"text": "昂贵", "is_correct": false, "explanation": "搭配：“昂贵”说价格或物品，不用来形容动物。"}, {"text": "陡峭", "is_correct": false, "explanation": "搭配：“陡峭”形容山坡等地形，不能修饰动物。"}], "explanations": {"野生": "正确：“野生”指动物在自然中自行生长，保护区里的动物正是如此。", "人工": "语义：“人工”指人为造出或培育的，保护区里的动物不应是人造的。", "昂贵": "搭配：“昂贵”说价格或物品，不用来形容动物。", "陡峭": "搭配：“陡峭”形容山坡等地形，不能修饰动物。"}, "sentence_index": 0, "correct_answer": "野生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些大棚里的番茄都是野生种出来的，农民每天浇水施肥。", "explanation": "这里应该用〈人工〉。“野生”指不经人栽培而自然生长，句中农民每天浇水施肥，应说“人工种出来的”。"}, {"text": "这台野生手机性能很好，价格也便宜。", "explanation": "这里应该用〈人造〉。“野生”指动植物在自然中自行生长，手机是人造产品，不能用“野生”形容。"}, {"text": "这种野生蘑菇是我自己在花盆里一点点培育出来的。", "explanation": "这里应该用〈人工〉。“野生”指自然生长，句中是在花盆里一点点培育的，应说“人工培育出来的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95460, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "野生", "is_correct": true, "explanation": "正确：“野生”指老虎在自然中生长，符合句意。"}, {"text": "香甜", "is_correct": false, "explanation": "搭配：“香甜”形容味道，不能修饰老虎。"}, {"text": "锋利", "is_correct": false, "explanation": "搭配：“锋利”形容刀刃，不能修饰老虎。"}, {"text": "温暖", "is_correct": false, "explanation": "语义：“温暖”指温度，与“数量一直在减少”的动物种群无关。"}], "explanations": {"野生": "正确：“野生”指老虎在自然中生长，符合句意。", "香甜": "搭配：“香甜”形容味道，不能修饰老虎。", "锋利": "搭配：“锋利”形容刀刃，不能修饰老虎。", "温暖": "语义：“温暖”指温度，与“数量一直在减少”的动物种群无关。"}, "sentence_index": 6, "correct_answer": "野生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些野生茶树是我每天浇水施肥照顾的。", "explanation": "这里应该用〈人工〉。“野生”指无人栽培照料而自然生长，句中每天浇水施肥照顾，应说“人工栽培的”。"}, {"text": "这座城市的街道很野生，开车最好小心。", "explanation": "这里把“野生”误用为“杂乱无序”的意思，应说〈乱〉。“野生”只指动植物自然生长，不用来形容街道等人造环境。"}, {"text": "这颗宝石是野生的，价格很高。", "explanation": "这里应该用〈天然〉。“野生”只指动植物自然生长，宝石是矿物，应说“天然的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95460, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片山林里有很多野动物。", "corrected_sentence": "这片山林里有很多野生动物。", "error_description": "错误形式：“野动物”；正确形式：“野生动物”。“野生”是双音节词，不能漏掉“生”，应说“野生动物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95460, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些竹子是野生，不是人种的。", "corrected_sentence": "这些竹子是野生的，不是人种的。", "error_description": "“野生”作谓语时后面要带“的”，应说“是野生的”，不说“是野生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e7f39aa-3278-4d85-a78e-7c7bc7e47aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95461, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "直接", "is_correct": true, "explanation": "正确答案。“直接”与“间接”是反义词，指不经过中间环节。"}, {"text": "具体", "is_correct": false, "explanation": "“具体”形容事物详细明确，与“间接”没有反义关系。"}, {"text": "公开", "is_correct": false, "explanation": "“公开”的反义词是“秘密”，与“间接”的意思无关。"}, {"text": "鲜明", "is_correct": false, "explanation": "“鲜明”形容颜色或态度清楚醒目，与“间接”没有反义关系。"}], "correct_answer": "直接", "explanations": {"直接": "正确答案。“直接”与“间接”是反义词，指不经过中间环节。", "具体": "“具体”形容事物详细明确，与“间接”没有反义关系。", "公开": "“公开”的反义词是“秘密”，与“间接”的意思无关。", "鲜明": "“鲜明”形容颜色或态度清楚醒目，与“间接”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3804a8c4-77d5-473c-a855-186802e79ed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95461, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "直接", "is_correct": true, "explanation": "正确答案。“直接”与“间接”是反义词，指不经过中间环节。"}, {"text": "确切", "is_correct": false, "explanation": "“确切”形容准确可靠，与“间接”没有反义关系。"}, {"text": "清晰", "is_correct": false, "explanation": "“清晰”形容清楚分明，与“间接”没有反义关系。"}, {"text": "突出", "is_correct": false, "explanation": "“突出”形容明显、超出一般，与“间接”没有反义关系。"}], "correct_answer": "直接", "explanations": {"直接": "正确答案。“直接”与“间接”是反义词，指不经过中间环节。", "确切": "“确切”形容准确可靠，与“间接”没有反义关系。", "清晰": "“清晰”形容清楚分明，与“间接”没有反义关系。", "突出": "“突出”形容明显、超出一般，与“间接”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3804a8c4-77d5-473c-a855-186802e79ed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95461, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不是直接去做，中间还隔着别的人或事。", "primary_collocate": null, "pronunciation": "jiàn jiē", "ipa": "tɕjɛn˥˩ tɕjɛ˥", "syllable_count": 2, "sentences": [{"text": "他没有直接告诉我，是用间接的方式说的。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我是间接听说这件事的。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她通过朋友间接认识了老板。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题很敏感，我们可以托朋友间接打听一下。", "target_word": "间接", "complexity_tier": "T3", "furigana": "Zhè ge wèn tí hěn mǐn gǎn, wǒ men kě yǐ tuō péng you jiàn jiē dǎ tīng yí xià.", "sentence_source": "generated"}, {"text": "他不好意思直接拒绝，只能用间接的方式表示。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没见过他，只是间接知道他的名字。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以请经理间接问问他的想法。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李间接告诉我，他不想去了。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师没有直接批评他，而是找他的朋友间接转告。", "target_word": "间接", "complexity_tier": "T3", "furigana": "Lǎo shī méi yǒu zhí jiē pī píng tā, ér shì zhǎo tā de péng you jiàn jiē zhuǎn gào.", "sentence_source": "generated"}, {"text": "这些消息都是间接得到的，不一定对。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "间接地", "label": "副词形式"}], "register": "中性", "sense_fingerprint": "做事或表达的方式不直接，中间通过别人或别的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abbedf5-65ef-4d8e-91b6-0fff13c7738f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95461, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "间接", "is_correct": true, "explanation": "正确答案。间接 jiàn jiē，指不直接去做，中间隔着别的人或事。"}, {"text": "见解", "is_correct": false, "explanation": "jiě（第三声）与 jiē（第一声）声调不同，见解指对事情的看法，与“间接”无关。"}, {"text": "简洁", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn（第四声）、jié（第二声）与 jiē（第一声）声调都不同，简洁指简单明了。"}, {"text": "剪接", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn（第四声）声调不同，剪接指影视作品的剪辑连接。"}, {"text": "间歇", "is_correct": false, "explanation": "xiē 与 jiē 声母不同（x 与 j），间歇指一段一段地停止。"}, {"text": "简介", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn 声调不同，jiè（第四声）与 jiē（第一声）声调也不同，简介指简单的介绍。"}], "explanations": {"间接": "正确答案。间接 jiàn jiē，指不直接去做，中间隔着别的人或事。", "见解": "jiě（第三声）与 jiē（第一声）声调不同，见解指对事情的看法，与“间接”无关。", "简洁": "jiǎn（第三声）与 jiàn（第四声）、jié（第二声）与 jiē（第一声）声调都不同，简洁指简单明了。", "剪接": "jiǎn（第三声）与 jiàn（第四声）声调不同，剪接指影视作品的剪辑连接。", "间歇": "xiē 与 jiē 声母不同（x 与 j），间歇指一段一段地停止。", "简介": "jiǎn（第三声）与 jiàn 声调不同，jiè（第四声）与 jiē（第一声）声调也不同，简介指简单的介绍。"}, "sentence_index": null, "correct_answer": "间接"}, "level_3": {"options": [{"text": "间接", "is_correct": true, "explanation": "正确答案。“间接的方式”指经过中间环节的方式，与“没有直接告诉我”相合。"}, {"text": "直接", "is_correct": false, "explanation": "语义：“直接”与前句的“没有直接告诉我”重复且相互矛盾，不能描述这种说话方式。"}, {"text": "明确", "is_correct": false, "explanation": "语义：“明确”指说得清清楚楚，与“没有直接告诉我”的语境相冲突。"}, {"text": "清楚", "is_correct": false, "explanation": "语义：“清楚”强调表达明白，与前句表示不直说的语境相冲突。"}], "explanations": {"间接": "正确答案。“间接的方式”指经过中间环节的方式，与“没有直接告诉我”相合。", "直接": "语义：“直接”与前句的“没有直接告诉我”重复且相互矛盾，不能描述这种说话方式。", "明确": "语义：“明确”指说得清清楚楚，与“没有直接告诉我”的语境相冲突。", "清楚": "语义：“清楚”强调表达明白，与前句表示不直说的语境相冲突。"}, "sentence_index": 0, "correct_answer": "间接"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他间接咬了一口苹果。", "explanation": "这里应该用〈直接〉。咬东西是本人直接完成的动作，“间接”指经过中间环节，用在这里说不通。"}, {"text": "校长间接握了我的手。", "explanation": "这里应该用〈亲自〉。握手需要本人直接接触，“间接”表示经过别人，与握手的动作矛盾。"}, {"text": "我每天都间接刷牙。", "explanation": "这里应该用〈自己〉。刷牙是本人亲手完成的事，不能说“间接刷牙”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3804a8c4-77d5-473c-a855-186802e79ed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95461, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "间接", "is_correct": true, "explanation": "正确答案。“间接”修饰“问”，表示通过别人去问。"}, {"text": "狠狠", "is_correct": false, "explanation": "搭配：“狠狠”表示用力、猛烈，与“问问想法”这种轻柔的询问不搭。"}, {"text": "强行", "is_correct": false, "explanation": "语义：“强行”含强迫的意思，与“你可以请”的商量语气相反。"}, {"text": "猛然", "is_correct": false, "explanation": "语义：“猛然”指突然发生，与“请经理问问想法”这种有计划的做法不符。"}], "explanations": {"间接": "正确答案。“间接”修饰“问”，表示通过别人去问。", "狠狠": "搭配：“狠狠”表示用力、猛烈，与“问问想法”这种轻柔的询问不搭。", "强行": "语义：“强行”含强迫的意思，与“你可以请”的商量语气相反。", "猛然": "语义：“猛然”指突然发生，与“请经理问问想法”这种有计划的做法不符。"}, "sentence_index": 6, "correct_answer": "间接"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他间接摔了一跤。", "explanation": "这里应该用〈亲身〉。摔跤是本人直接发生的事，“间接”表示经过中间环节，用在这里说不通。"}, {"text": "他间接跑完了马拉松。", "explanation": "这里应该用〈亲自〉。跑完马拉松要本人亲身完成，“间接”表示经过别人，与“跑完”矛盾。"}, {"text": "他间接笑了一下。", "explanation": "笑是本人直接做出的表情，“间接”表示经过中间环节，用在这里说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3804a8c4-77d5-473c-a855-186802e79ed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95461, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们用间接地方式把消息告诉了他。", "corrected_sentence": "我们用间接的方式把消息告诉了他。", "error_description": "错误：“间接”修饰名词“方式”，应写作“间接的方式”，不能用副词词尾“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3804a8c4-77d5-473c-a855-186802e79ed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95461, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她间接认识着那位老板。", "corrected_sentence": "她间接认识了那位老板。", "error_description": "错误：动作已经完成，应在“认识”后用“了”，写作“认识了”；“着”表示持续的状态，“认识着”说不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3804a8c4-77d5-473c-a855-186802e79ed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
