INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95462, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不直接发生关系，经过中间环节的。", "primary_collocate": null, "pronunciation": "jiàn jiē", "ipa": "tɕjɛn˥˩ tɕjɛ˥", "syllable_count": 2, "sentences": [{"text": "天气不好间接影响了今年的菜价。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事和我没有直接关系，只有间接关系。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作压力会间接影响人的睡眠。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房价上涨间接让很多年轻人不敢结婚。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是直接负责人，只是间接参与了这个项目。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水多了，间接让今年的大米更便宜。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吸烟对别人的健康也有间接的坏处。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个政策间接帮助了很多小公司。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广告对销量有间接的作用。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书价上涨间接影响了学生的买书。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "间接地", "label": "副词形式"}], "register": "中性", "sense_fingerprint": "两件事之间没有直接联系，要经过中间环节才发生影响", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abbedf5-65ef-4d8e-91b6-0fff13c7738f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95462, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "间接", "is_correct": true, "explanation": "正确答案。间接 jiàn jiē，指经过中间环节，不直接发生关系。"}, {"text": "见解", "is_correct": false, "explanation": "jiě（第三声）与 jiē（第一声）声调不同，见解指对事情的看法。"}, {"text": "简洁", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn（第四声）、jié（第二声）与 jiē（第一声）声调都不同，简洁指简单明了。"}, {"text": "剪接", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn（第四声）声调不同，剪接指影视作品的剪辑连接。"}, {"text": "间歇", "is_correct": false, "explanation": "xiē 与 jiē 声母不同（x 与 j），间歇指一段一段地停止。"}], "explanations": {"间接": "正确答案。间接 jiàn jiē，指经过中间环节，不直接发生关系。", "见解": "jiě（第三声）与 jiē（第一声）声调不同，见解指对事情的看法。", "简洁": "jiǎn（第三声）与 jiàn（第四声）、jié（第二声）与 jiē（第一声）声调都不同，简洁指简单明了。", "剪接": "jiǎn（第三声）与 jiàn（第四声）声调不同，剪接指影视作品的剪辑连接。", "间歇": "xiē 与 jiē 声母不同（x 与 j），间歇指一段一段地停止。"}, "sentence_index": null, "correct_answer": "间接"}, "level_3": {"options": [{"text": "间接", "is_correct": true, "explanation": "正确答案。“间接影响”指通过中间环节产生的影响，与“天气不好”的因果链相合。"}, {"text": "亲自", "is_correct": false, "explanation": "语义：“亲自”要求施事是有意志的人，天气不能亲自行动。"}, {"text": "故意", "is_correct": false, "explanation": "语义：“故意”表示有意图，天气没有主观意图。"}, {"text": "亲手", "is_correct": false, "explanation": "语义：“亲手”要求有人亲自动手，天气不能亲手做任何事，句子说不通。"}], "explanations": {"间接": "正确答案。“间接影响”指通过中间环节产生的影响，与“天气不好”的因果链相合。", "亲自": "语义：“亲自”要求施事是有意志的人，天气不能亲自行动。", "故意": "语义：“故意”表示有意图，天气没有主观意图。", "亲手": "语义：“亲手”要求有人亲自动手，天气不能亲手做任何事，句子说不通。"}, "sentence_index": 0, "correct_answer": "间接"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两件事之间完全间接，毫无关联。", "explanation": "这里应该用〈无关〉。“间接”指有关系但要经过中间环节，“完全间接”说不通，两件事没有关系应说“无关”。"}, {"text": "我每天间接走路上学。", "explanation": "这里应该用〈自己〉。走路上学是本人直接完成的动作，“间接”表示经过别人或别的事，用在这里说不通。"}, {"text": "孩子们间接跳起了舞。", "explanation": "这里应该用〈亲自〉。跳舞是本人亲身完成的动作，“间接跳舞”说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3804a8c4-77d5-473c-a855-186802e79ed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95462, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "间接", "is_correct": true, "explanation": "正确答案。“间接的坏处”指通过间接途径产生的不利影响。"}, {"text": "甜蜜", "is_correct": false, "explanation": "语义：“甜蜜”带有愉快的感情色彩，与“坏处”相反。"}, {"text": "柔软", "is_correct": false, "explanation": "搭配：“柔软”多形容物体的质地，不能修饰“坏处”。"}, {"text": "伟大", "is_correct": false, "explanation": "语义：“伟大”形容价值或成就很高，与“坏处”的意思相反。"}], "explanations": {"间接": "正确答案。“间接的坏处”指通过间接途径产生的不利影响。", "甜蜜": "语义：“甜蜜”带有愉快的感情色彩，与“坏处”相反。", "柔软": "搭配：“柔软”多形容物体的质地，不能修饰“坏处”。", "伟大": "语义：“伟大”形容价值或成就很高，与“坏处”的意思相反。"}, "sentence_index": 6, "correct_answer": "间接"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他间接出生在北京。", "explanation": "出生是本人直接发生的事，不经过中间环节，“间接”用在这里说不通。"}, {"text": "他间接睡了一觉。", "explanation": "睡觉是本人亲身完成的事，不经过中间环节，“间接”用在这里说不通。"}, {"text": "他间接吃了三碗饭。", "explanation": "这里应该用〈直接〉。吃饭是本人亲身完成的事，“间接”表示经过中间环节，用在这里说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3804a8c4-77d5-473c-a855-186802e79ed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95462, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两件事之间只有间接地关系。", "corrected_sentence": "这两件事之间只有间接的关系。", "error_description": "错误：“间接”修饰名词“关系”，应写作“间接的关系”，不能用副词词尾“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3804a8c4-77d5-473c-a855-186802e79ed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95462, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这笔钱是间接转了给他的。", "corrected_sentence": "这笔钱是间接转给他的。", "error_description": "错误：“了”插在“转”和“给”之间，破坏了动词结构，这里不需要“了”，应写作“间接转给他的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3804a8c4-77d5-473c-a855-186802e79ed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
