INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95463, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "子女或社会供养老人，使老人晚年生活有保障。", "primary_collocate": null, "pronunciation": "yǎng lǎo", "ipa": "jɑŋ˨˩˦ lɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他每月给父母养老，从不让他们操心。", "target_word": "养老", "complexity_tier": "T3", "furigana": "yǎng lǎo", "sentence_source": "generated"}, {"text": "他每月寄钱，给父母养老。", "target_word": "养老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都很孝顺，让老人安心养老。", "target_word": "养老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们兄弟三人轮流给母亲养老。", "target_word": "养老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有孩子，担心以后没人给他养老。", "target_word": "养老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按照老规矩，儿子要给父母养老。", "target_word": "养老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了新房，让父母住进来养老。", "target_word": "养老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的钱不多，但孩子们都愿意给他养老。", "target_word": "养老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府帮助没有子女的老人养老。", "target_word": "养老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女儿嫁到外地，还是每年接妈妈来养老。", "target_word": "养老", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "养老院", "label": "复合"}, {"form": "养老金", "label": "复合"}], "register": "中性", "sense_fingerprint": "子女或社会照顾老人，使老人晚年生活有保障", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e80955d-5d4f-40de-8cbf-bf9a5acaa222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95463, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "养老", "is_correct": true, "explanation": "养老 yǎng lǎo：子女供养父母，使老人晚年生活有保障，正确答案。"}, {"text": "养料", "is_correct": false, "explanation": "养料 yǎngliào 的第二音节为 liào（第四声，带介音 i），与养老的 lǎo 不同，意思是营养物质。"}, {"text": "养好", "is_correct": false, "explanation": "养好 yǎnghǎo 第二音节声母为 h（养老为 l），意思是调养得好。"}, {"text": "养草", "is_correct": false, "explanation": "养草 yǎngcǎo：第二音节声母为 c（养老为 l），声调相同，意思是培育草类。"}], "explanations": {"养老": "养老 yǎng lǎo：子女供养父母，使老人晚年生活有保障，正确答案。", "养料": "养料 yǎngliào 的第二音节为 liào（第四声，带介音 i），与养老的 lǎo 不同，意思是营养物质。", "养好": "养好 yǎnghǎo 第二音节声母为 h（养老为 l），意思是调养得好。", "养草": "养草 yǎngcǎo：第二音节声母为 c（养老为 l），声调相同，意思是培育草类。"}, "sentence_index": null, "correct_answer": "养老"}, "level_3": {"options": [{"text": "养老", "is_correct": true, "explanation": "养老：子女供养父母，使其晚年生活有保障，符合「每月给父母」的语境。"}, {"text": "收养", "is_correct": false, "explanation": "搭配：「收养」多用于孩子或宠物，不说收养父母。"}, {"text": "寄养", "is_correct": false, "explanation": "语义：「寄养」指把人或动物托给别人抚养，与子女每月供养父母的语境不符。"}, {"text": "喂养", "is_correct": false, "explanation": "搭配：「喂养」多用于婴儿或动物，不说喂养父母。"}], "explanations": {"养老": "养老：子女供养父母，使其晚年生活有保障，符合「每月给父母」的语境。", "收养": "搭配：「收养」多用于孩子或宠物，不说收养父母。", "寄养": "语义：「寄养」指把人或动物托给别人抚养，与子女每月供养父母的语境不符。", "喂养": "搭配：「喂养」多用于婴儿或动物，不说喂养父母。"}, "sentence_index": 0, "correct_answer": "养老"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校轮流给学生养老。", "explanation": "这里应该用〈培养〉。养老指子女供养老人，学校培养学生要说培养。"}, {"text": "妈妈每天给刚出生的孩子养老，很辛苦。", "explanation": "这里应该用〈抚养〉。养老针对老年人，刚出生的孩子要说抚养。"}, {"text": "饲养员每天给牲口养老。", "explanation": "这里应该用〈饲养〉。养老只用于人，喂养牲口要说饲养。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992aa609-38af-47ce-a8c5-208f71a1ab07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95463, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "养老", "is_correct": true, "explanation": "养老：子女让父母住进来安度晚年，符合「买了新房」的语境。"}, {"text": "打工", "is_correct": false, "explanation": "语义：父母住进来打工，与养老的语境冲突，也不符合子女照顾老人的意思。"}, {"text": "出差", "is_correct": false, "explanation": "语义：「出差」指外出办事，与父母住进来的安排矛盾。"}, {"text": "上学", "is_correct": false, "explanation": "搭配：「上学」多指学生，不说让父母住进来上学。"}], "explanations": {"养老": "养老：子女让父母住进来安度晚年，符合「买了新房」的语境。", "打工": "语义：父母住进来打工，与养老的语境冲突，也不符合子女照顾老人的意思。", "出差": "语义：「出差」指外出办事，与父母住进来的安排矛盾。", "上学": "搭配：「上学」多指学生，不说让父母住进来上学。"}, "sentence_index": 6, "correct_answer": "养老"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "士兵每天给边疆养老。", "explanation": "这里应该用〈守护〉。养老指子女供养老人，士兵守护边疆要说守护。"}, {"text": "孤儿院给孤儿养老。", "explanation": "这里应该用〈抚养〉。养老针对老年人，孤儿需要抚养，不能说养老。"}, {"text": "工人定期给铁路养老。", "explanation": "这里应该用〈养护〉。养老只能用于老人，铁路要说养护。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992aa609-38af-47ce-a8c5-208f71a1ab07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95463, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "儿子每年给父亲很养老，让他很放心。", "corrected_sentence": "儿子每年给父亲养老，让他很放心。", "error_description": "错误：「很养老」；正确：「养老」。「很」修饰的是形容词或心理动词，不能直接修饰动词「养老」，应删去「很」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992aa609-38af-47ce-a8c5-208f71a1ab07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95463, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "儿子在国外工作，每年接父亲来养老着。", "corrected_sentence": "儿子在国外工作，每年接父亲来养老。", "error_description": "错误：「来养老着」；正确：「来养老」。「接……来养老」是为老人养老的目的性说法，句末不能加表示持续的「着」，应删去「着」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992aa609-38af-47ce-a8c5-208f71a1ab07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
