INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95466, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "人或动物身体的重量。", "primary_collocate": null, "pronunciation": "tǐ zhòng", "ipa": "tʰi˨˩˦ ʈʂoŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这只小猫的体重只有两公斤。", "target_word": "体重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大象的体重可以超过五千公斤。", "target_word": "体重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小猪出生时体重很轻。", "target_word": "体重", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "兽医先给小狗称了体重。", "target_word": "体重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人的体重慢慢变轻了。", "target_word": "体重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "熊在冬天以前，体重会增加很多。", "target_word": "体重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子的体重比去年重了五公斤。", "target_word": "体重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生根据病人的体重决定吃多少药。", "target_word": "体重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这头牛的体重比那头牛重。", "target_word": "体重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鸟的体重很轻，所以能飞起来。", "target_word": "体重", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "體重", "label": "繁体"}, {"form": "体重秤", "label": "复合"}], "register": "通用", "sense_fingerprint": "名词，指人或动物身体的重量，可用于猫、狗、大象等动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abbedf5-65ef-4d8e-91b6-0fff13c7738f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95466, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体重", "is_correct": true, "explanation": "正确。“这只小猫的体重只有两公斤”表示小猫身体的重量。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高指身体的高矮，不用公斤计量，与“两公斤”不符。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：寿命指存活的年限，不用“两公斤”来表示。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“脚步”不能用“只有两公斤”来描述。"}], "explanations": {"体重": "正确。“这只小猫的体重只有两公斤”表示小猫身体的重量。", "身高": "语义：身高指身体的高矮，不用公斤计量，与“两公斤”不符。", "寿命": "搭配：寿命指存活的年限，不用“两公斤”来表示。", "脚步": "搭配：“脚步”不能用“只有两公斤”来描述。"}, "sentence_index": 0, "correct_answer": "体重"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条蛇的体重有两米。", "explanation": "这里应该用〈身长〉。体重是重量，不能用长度单位“米”计量。"}, {"text": "这只乌龟的体重很长。", "explanation": "这里应该用〈寿命〉。体重只能说轻或重，不能用“长”来形容。"}, {"text": "这箱苹果的体重是二十公斤。", "explanation": "这里应该用〈重量〉。体重只用于人或动物的身体，箱子里的苹果要说重量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3804a8c4-77d5-473c-a855-186802e79ed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95466, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体重", "is_correct": true, "explanation": "正确。“孩子的体重比去年重了五公斤”表示孩子身体的重量变化。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不是身体的重量，“比去年重了五公斤”说不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄表示岁数，不能说“重了五公斤”。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：脾气不能用“重”和公斤来计量。"}], "explanations": {"体重": "正确。“孩子的体重比去年重了五公斤”表示孩子身体的重量变化。", "作业": "语义：作业不是身体的重量，“比去年重了五公斤”说不通。", "年龄": "语义：年龄表示岁数，不能说“重了五公斤”。", "脾气": "搭配：脾气不能用“重”和公斤来计量。"}, "sentence_index": 6, "correct_answer": "体重"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只猫的体重是黑的。", "explanation": "这里应该用〈毛色〉。体重表示重量，不能用颜色词“黑的”来形容。"}, {"text": "这只鸟的体重很快。", "explanation": "这里应该用〈飞行速度〉。体重只能说轻或重，不能用“快”来形容。"}, {"text": "这只小狗的体重很响。", "explanation": "这里应该用〈叫声〉。体重是重量，不能用“响”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3804a8c4-77d5-473c-a855-186802e79ed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95466, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只小狗的体重增加了到十公斤。", "corrected_sentence": "这只小狗的体重增加到了十公斤。", "error_description": "错误形式“增加了到”，正确形式“增加到了”。“了”应紧跟补语“到”之后，插在动词和补语之间是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3804a8c4-77d5-473c-a855-186802e79ed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95466, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这匹马的体重比那匹一百公斤。", "corrected_sentence": "这匹马的体重比那匹轻一百公斤。", "error_description": "错误形式“比那匹一百公斤”，缺少比较结果的形容词“轻”，正确形式“比那匹轻一百公斤”。比较句中表示差距的数量词应放在形容词“轻”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3804a8c4-77d5-473c-a855-186802e79ed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95471, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "容易", "is_correct": true, "explanation": "“容易”与“不易”在这个义项上构成反义，一个指做起来费力，一个指做起来不费力。"}, {"text": "漂亮", "is_correct": false, "explanation": "“漂亮”形容外貌或事物好看，与“不易”的难度义无关，不是反义词。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线充足，与“不易”表示的困难程度没有反义关系。"}, {"text": "整洁", "is_correct": false, "explanation": "“整洁”形容干净有序，与“不易”的难度义没有反义关系。"}], "correct_answer": "容易", "explanations": {"容易": "“容易”与“不易”在这个义项上构成反义，一个指做起来费力，一个指做起来不费力。", "漂亮": "“漂亮”形容外貌或事物好看，与“不易”的难度义无关，不是反义词。", "明亮": "“明亮”形容光线充足，与“不易”表示的困难程度没有反义关系。", "整洁": "“整洁”形容干净有序，与“不易”的难度义没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992aa609-38af-47ce-a8c5-208f71a1ab07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95471, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "容易", "is_correct": true, "explanation": "“容易”与“不易”在这个义项上构成反义，一个说难做，一个说不费力。"}, {"text": "狭窄", "is_correct": false, "explanation": "“狭窄”形容空间小，与“不易”的难度义无关，不是反义词。"}, {"text": "热情", "is_correct": false, "explanation": "“热情”形容待人的态度，与“不易”表示的困难程度没有反义关系。"}, {"text": "高大", "is_correct": false, "explanation": "“高大”形容体形或事物的高度，与“不易”的难度义无关，不构成反义。"}], "correct_answer": "容易", "explanations": {"容易": "“容易”与“不易”在这个义项上构成反义，一个说难做，一个说不费力。", "狭窄": "“狭窄”形容空间小，与“不易”的难度义无关，不是反义词。", "热情": "“热情”形容待人的态度，与“不易”表示的困难程度没有反义关系。", "高大": "“高大”形容体形或事物的高度，与“不易”的难度义无关，不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992aa609-38af-47ce-a8c5-208f71a1ab07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95471, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不容易，要花很多力气才能做到。", "primary_collocate": null, "pronunciation": "bú yì", "ipa": "pu˧˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "他花了十年才拿到这个奖，很不易。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从农村考上大学，这条路很不易。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一个人把店开到今天，实在不易。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在沙漠里种树成活，非常不易。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人坚持每天走路，十年不变，很不易。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把一门外语学好，其实很不易。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从工人做到经理，一路走来很不易。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这么大的桥修好，真不易。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了供孩子上学，他们省吃俭用，很不易。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "能有今天的成绩，每一步都不易。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不容易", "label": "口语形式"}], "register": "书面", "sense_fingerprint": "做成某事需要付出很多力气和时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e80955d-5d4f-40de-8cbf-bf9a5acaa222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95471, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不易", "is_correct": true, "explanation": "“不易”说明做成某事需要付出很多力气，与“花了十年才拿到这个奖”相合。"}, {"text": "容易", "is_correct": false, "explanation": "语义：“花了十年才拿到”说明过程艰难，说“容易”与句中的时间长短相矛盾。"}, {"text": "迅速", "is_correct": false, "explanation": "语义：“迅速”指速度快，与“花了十年”的漫长时间正相反。"}, {"text": "清楚", "is_correct": false, "explanation": "搭配：“清楚”说明情况明白，不用来评价获奖过程的难易。"}], "explanations": {"不易": "“不易”说明做成某事需要付出很多力气，与“花了十年才拿到这个奖”相合。", "容易": "语义：“花了十年才拿到”说明过程艰难，说“容易”与句中的时间长短相矛盾。", "迅速": "语义：“迅速”指速度快，与“花了十年”的漫长时间正相反。", "清楚": "搭配：“清楚”说明情况明白，不用来评价获奖过程的难易。"}, "sentence_index": 0, "correct_answer": "不易"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑很不易，买回来就用了三年。", "explanation": "这里是把“不易”当成描写物品质量的形容词（如“不耐用”）来用，但“不易”只说做事费力、困难，不能形容电脑本身。"}, {"text": "这块石头很不易，搬起来很重。", "explanation": "这里是把“不易”当成描写物品性质的形容词（如“很沉”）来用，但“不易”只说做事困难，不能形容石头本身。"}, {"text": "吸烟对健康很不易，应该早点戒掉。", "explanation": "这里应该用〈不利〉。“不利”说对身体有害，“不易”说做事困难，放在这里意思不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992aa609-38af-47ce-a8c5-208f71a1ab07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95471, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不易", "is_correct": true, "explanation": "“不易”概括整个经历的艰难，与“一路走来”相合，是本句需要的词。"}, {"text": "安静", "is_correct": false, "explanation": "搭配：“安静”多用于环境，不说“一路走来很安静”这样的经历。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：“吵闹”形容声音杂乱，与“一路走来”说的经历毫不相干，句子说不通。"}, {"text": "凉快", "is_correct": false, "explanation": "语义：“凉快”形容温度，与“一路走来”的成长过程毫不相干。"}], "explanations": {"不易": "“不易”概括整个经历的艰难，与“一路走来”相合，是本句需要的词。", "安静": "搭配：“安静”多用于环境，不说“一路走来很安静”这样的经历。", "吵闹": "语义：“吵闹”形容声音杂乱，与“一路走来”说的经历毫不相干，句子说不通。", "凉快": "语义：“凉快”形容温度，与“一路走来”的成长过程毫不相干。"}, "sentence_index": 6, "correct_answer": "不易"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周末你不易送我，我自己回去就行。", "explanation": "这里应该用〈不必〉。“不必”表示没有必要，“不易”说难做，放在这里意思不通，不能表示不需要。"}, {"text": "孩子不易玩火，很危险。", "explanation": "这里应该用〈不要〉。“不要”表示劝阻，玩火很危险，应该用劝阻的说法；“不易”只说做事困难，意思不对。"}, {"text": "长期熬夜对身体很不易。", "explanation": "这里应该用〈不利〉。“不利”说对身体有害，“不易”说做事困难，放在这里意思不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992aa609-38af-47ce-a8c5-208f71a1ab07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95471, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一个人养大三个孩子，实在不易地。", "corrected_sentence": "他一个人养大三个孩子，实在不易。", "error_description": "“不易”是形容词，后面不能加“地”。正确的说法是“实在不易”，不要加“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992aa609-38af-47ce-a8c5-208f71a1ab07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95471, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事做起来得不易。", "corrected_sentence": "这件事做起来很不易。", "error_description": "“不易”前应用程度副词“很”，不能用结构助词“得”代替。“做起来得不易”不成句，正确的说法是“做起来很不易”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992aa609-38af-47ce-a8c5-208f71a1ab07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95472, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "容易", "is_correct": true, "explanation": "“容易”与“不易”在这个义项上构成反义：一个指做起来困难，一个指做起来不费力。"}, {"text": "美丽", "is_correct": false, "explanation": "“美丽”形容外貌或景色之美，与“不易”的难度义无关，不是它的反义词。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线充足或颜色鲜亮，与“不易”的难度义没有反义关系。"}, {"text": "宽敞", "is_correct": false, "explanation": "“宽敞”形容空间大，与“不易”表示的困难程度无关，不构成反义。"}], "correct_answer": "容易", "explanations": {"容易": "“容易”与“不易”在这个义项上构成反义：一个指做起来困难，一个指做起来不费力。", "美丽": "“美丽”形容外貌或景色之美，与“不易”的难度义无关，不是它的反义词。", "明亮": "“明亮”形容光线充足或颜色鲜亮，与“不易”的难度义没有反义关系。", "宽敞": "“宽敞”形容空间大，与“不易”表示的困难程度无关，不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992aa609-38af-47ce-a8c5-208f71a1ab07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95472, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "容易", "is_correct": true, "explanation": "“容易”与“不易”在这个义项上构成反义，一个说难做，一个说不费力。"}, {"text": "复杂", "is_correct": false, "explanation": "“复杂”的反义词是“简单”，与“不易”的难度义没有反义关系。"}, {"text": "热情", "is_correct": false, "explanation": "“热情”形容待人的态度，与“不易”表示的困难程度没有反义关系。"}, {"text": "高大", "is_correct": false, "explanation": "“高大”形容体形或事物的高度，与“不易”的难度义无关，不构成反义。"}], "correct_answer": "容易", "explanations": {"容易": "“容易”与“不易”在这个义项上构成反义，一个说难做，一个说不费力。", "复杂": "“复杂”的反义词是“简单”，与“不易”的难度义没有反义关系。", "热情": "“热情”形容待人的态度，与“不易”表示的困难程度没有反义关系。", "高大": "“高大”形容体形或事物的高度，与“不易”的难度义无关，不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992aa609-38af-47ce-a8c5-208f71a1ab07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95472, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不容易；困难。", "primary_collocate": null, "pronunciation": "bú yì", "ipa": "pu˧˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "一个人在外地生活，很不易。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做父母不易，请多体谅他们。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在大城市买房实在不易。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人带大三个孩子，十分不易。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年大家的日子都不易。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要在这么短的时间里完成，实属不易。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "创业不易，守业更难。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人独自生活，真的不易。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "找到一份好工作不易。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生活在这座城市，大家都不易。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不容易", "label": "口语形式"}], "register": "书面", "sense_fingerprint": "处境或事情不容易，生活、工作等方面有困难", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e80955d-5d4f-40de-8cbf-bf9a5acaa222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95472, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不易", "is_correct": true, "explanation": "“不易”表示处境困难，与“一个人在外地生活”的艰难相合，是本句需要的词。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“一个人”独自在外，与“热闹”的景象相矛盾。"}, {"text": "清楚", "is_correct": false, "explanation": "搭配：“清楚”说明情况明白，不用来评价生活的难易。"}, {"text": "迅速", "is_correct": false, "explanation": "搭配：“迅速”形容速度，不能修饰“生活”这种长期状态。"}], "explanations": {"不易": "“不易”表示处境困难，与“一个人在外地生活”的艰难相合，是本句需要的词。", "热闹": "语义：“一个人”独自在外，与“热闹”的景象相矛盾。", "清楚": "搭配：“清楚”说明情况明白，不用来评价生活的难易。", "迅速": "搭配：“迅速”形容速度，不能修饰“生活”这种长期状态。"}, "sentence_index": 0, "correct_answer": "不易"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子很不易，坐上去不太舒服。", "explanation": "这里是把“不易”当成描写物品质量的形容词（如“不结实”）来用，但“不易”只说做事困难，不能形容椅子本身。"}, {"text": "这张桌子很不易，搬来搬去很麻烦。", "explanation": "这里是把“不易”当成描写物品性质的形容词（如“不好搬”）来用，但“不易”只说做某事困难，不能形容桌子本身。"}, {"text": "熬夜对皮肤很不易，要早点休息。", "explanation": "这里应该用〈不利〉。“不利”说对身体有害，“不易”说做事困难，放在这里意思不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992aa609-38af-47ce-a8c5-208f71a1ab07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95472, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不易", "is_correct": true, "explanation": "“不易”与后句“守业更难”对比，说明创业本身困难，这里需要这个词。"}, {"text": "安静", "is_correct": false, "explanation": "搭配：“安静”多用于环境，不说“创业安静”。"}, {"text": "干净", "is_correct": false, "explanation": "搭配：“干净”形容物品或环境是否清洁，不能用来说创业的难易。"}, {"text": "凉快", "is_correct": false, "explanation": "语义：“凉快”形容天气或环境的温度，与“创业”这件事的难度毫不相关。"}], "explanations": {"不易": "“不易”与后句“守业更难”对比，说明创业本身困难，这里需要这个词。", "安静": "搭配：“安静”多用于环境，不说“创业安静”。", "干净": "搭配：“干净”形容物品或环境是否清洁，不能用来说创业的难易。", "凉快": "语义：“凉快”形容天气或环境的温度，与“创业”这件事的难度毫不相关。"}, "sentence_index": 6, "correct_answer": "不易"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你的建议不易考虑一下。", "explanation": "这里应该用〈不妨〉。“不妨”表示可以这样做，“不易”说做事困难，两者意思不同，不能互换。"}, {"text": "公共场所不易吸烟。", "explanation": "这里应该用〈不得〉。“不得”表示禁止，“不易”只说难做，不表示禁止，这里不能这样用。"}, {"text": "喝酒对肝脏很不易。", "explanation": "这里应该用〈不利〉。“不利”说对身体有害，“不易”说做事困难，放在这里意思不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992aa609-38af-47ce-a8c5-208f71a1ab07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95472, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份工作要长期坚持，实在不易地。", "corrected_sentence": "这份工作要长期坚持，实在不易。", "error_description": "“不易”是形容词，后面不能加“地”。正确的说法是“实在不易”，不要在它后面加“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992aa609-38af-47ce-a8c5-208f71a1ab07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95472, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些年，他们过得很易。", "corrected_sentence": "这些年，他们过得很不易。", "error_description": "“不易”前的否定词“不”被漏掉，“很易”变成“很容易”的意思，与句意相反；应为“过得很不易”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992aa609-38af-47ce-a8c5-208f71a1ab07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
