INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95474, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "主要的力量。", "primary_collocate": null, "pronunciation": "zhǔ lì", "ipa": "ʈʂu˨˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "这款手机是公司今年的销售主力。", "target_word": "主力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电动车会成为未来汽车市场的主力。", "target_word": "主力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个小村子里，运输的主力是摩托车。", "target_word": "主力", "complexity_tier": "T3", "furigana": "Zài zhè ge xiǎo cūn zi lǐ, yùn shū de zhǔ lì shì mó tuō chē.", "sentence_source": "generated"}, {"text": "军队的主力已经到了河边。", "target_word": "主力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的主力是便宜的家常菜。", "target_word": "主力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中小企业是这个城市经济的主力。", "target_word": "主力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白天，地铁是城市出行的主力。", "target_word": "主力", "complexity_tier": "T3", "furigana": "Bái tiān, dì tiě shì chéng shì chū xíng de zhǔ lì.", "sentence_source": "generated"}, {"text": "敌人的主力在山后面等着。", "target_word": "主力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这三款老产品是他们公司的主力。", "target_word": "主力", "complexity_tier": "T3", "furigana": "Zhè sān kuǎn lǎo chǎn pǐn shì tā men gōng sī de zhǔ lì.", "sentence_source": "generated"}, {"text": "现在，网购已经成了零售市场的主力。", "target_word": "主力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "主力军", "label": "复合词"}], "register": "中性", "sense_fingerprint": "某个领域或行动中起主要作用的力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abbedf5-65ef-4d8e-91b6-0fff13c7738f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95474, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "主力", "is_correct": true, "explanation": "正确答案。主力 zhǔ lì，指起主要作用的力量。"}, {"text": "助力", "is_correct": false, "explanation": "zhù（第四声）与 zhǔ（第三声）声调不同，助力指帮助的力量。"}, {"text": "阻力", "is_correct": false, "explanation": "z 与 zh 声母不同，阻力指阻碍的力量。"}, {"text": "努力", "is_correct": false, "explanation": "n 与 zh 声母不同，努力指尽力去做。"}], "explanations": {"主力": "正确答案。主力 zhǔ lì，指起主要作用的力量。", "助力": "zhù（第四声）与 zhǔ（第三声）声调不同，助力指帮助的力量。", "阻力": "z 与 zh 声母不同，阻力指阻碍的力量。", "努力": "n 与 zh 声母不同，努力指尽力去做。"}, "sentence_index": null, "correct_answer": "主力"}, "level_3": {"options": [{"text": "主力", "is_correct": true, "explanation": "正确答案。“销售主力”指起主要作用的销售产品。"}, {"text": "销售员", "is_correct": false, "explanation": "语义：手机是产品，不能充当销售员。"}, {"text": "销售方案", "is_correct": false, "explanation": "语义：手机是产品，不是方案，这句话说不通。"}, {"text": "销售时间", "is_correct": false, "explanation": "语义：手机是产品，不是时间段，“销售时间”放在这句话里说不通。"}], "explanations": {"主力": "正确答案。“销售主力”指起主要作用的销售产品。", "销售员": "语义：手机是产品，不能充当销售员。", "销售方案": "语义：手机是产品，不是方案，这句话说不通。", "销售时间": "语义：手机是产品，不是时间段，“销售时间”放在这句话里说不通。"}, "sentence_index": 0, "correct_answer": "主力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司的主力是明天的天气。", "explanation": "这里应该用〈因素〉。“主力”指起主要作用的力量，不能用来指天气这类外部条件。"}, {"text": "这次作文比赛的主力是一本词典。", "explanation": "这里应该用〈工具〉。“主力”指起主要作用的力量，词典只是工具，不能算作文比赛的主力。"}, {"text": "这次宴会的主力是一支铅笔。", "explanation": "这里应该用〈道具〉。“主力”指起主要作用的力量，铅笔只是道具，不能算宴会的主力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3804a8c4-77d5-473c-a855-186802e79ed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95474, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主力", "is_correct": true, "explanation": "正确答案。“城市出行的主力”指城市出行中起主要作用的交通方式。"}, {"text": "裁判", "is_correct": false, "explanation": "语义：地铁不是人，不能充当裁判。"}, {"text": "宠物", "is_correct": false, "explanation": "语义：地铁不是动物，不能当宠物。"}, {"text": "小说", "is_correct": false, "explanation": "配价：“城市出行的”后面要求是交通方式，小说不能充当。"}], "explanations": {"主力": "正确答案。“城市出行的主力”指城市出行中起主要作用的交通方式。", "裁判": "语义：地铁不是人，不能充当裁判。", "宠物": "语义：地铁不是动物，不能当宠物。", "小说": "配价：“城市出行的”后面要求是交通方式，小说不能充当。"}, "sentence_index": 6, "correct_answer": "主力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "网购只是零售市场的主力。", "explanation": "这里应该用〈配角〉。“只是”表示次要，与“主力”的主要含义相反。"}, {"text": "这些小花是房间的主力。", "explanation": "这里应该用〈装饰〉。小花只起装饰作用，不能说是房间的主力。"}, {"text": "葱花是汤的主力。", "explanation": "这里应该用〈配料〉。葱花只是配料，不是起主要作用的力量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3804a8c4-77d5-473c-a855-186802e79ed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95474, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这款新产品很快会成为公司的一把主力产品。", "corrected_sentence": "这款新产品很快会成为公司的一款主力产品。", "error_description": "错误：“主力产品”的量词应为“款”，写成“把”是量词用错了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3804a8c4-77d5-473c-a855-186802e79ed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95474, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电动车是未来交通的主力的。", "corrected_sentence": "电动车是未来交通的主力。", "error_description": "错误：“主力”后多加了一个“的”，应写作“未来交通的主力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3804a8c4-77d5-473c-a855-186802e79ed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
