INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95476, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "负责一部书刊或一家报刊编辑工作的主要负责人。", "primary_collocate": null, "pronunciation": "zhǔ biān", "ipa": "ʈʂu˨˩˦ pi̯ɛn˥˥", "syllable_count": 2, "sentences": [{"text": "他是这家报社的主编。", "target_word": "主编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套书的主编是一位老教授。", "target_word": "主编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李老师担任这部词典的主编。", "target_word": "主编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杂志社新来了一位主编。", "target_word": "主编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主编负责整本杂志的编辑工作。", "target_word": "主编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位主编编过很多有名的书。", "target_word": "主编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从记者做到了主编。", "target_word": "主编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总经理请主编谈谈下个月的计划。", "target_word": "主编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主编和作者一起讨论这本书的内容。", "target_word": "主编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家报纸的主编换人了。", "target_word": "主编", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位主编", "label": "量词"}, {"form": "副主编", "label": "复合"}, {"form": "主編", "label": "繁体"}], "register": "中性", "sense_fingerprint": "书刊或报刊编辑工作的主要负责人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e80955d-5d4f-40de-8cbf-bf9a5acaa222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95476, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主编", "is_correct": true, "explanation": "“主编”指报刊编辑工作的主要负责人，“这家报社的”搭配自然，符合句意。"}, {"text": "歌手", "is_correct": false, "explanation": "语义：报社的负责人与唱歌无关，“报社的歌手”说不通。"}, {"text": "演员", "is_correct": false, "explanation": "语义：报社不是演出的地方，“报社的演员”与句子的语境不符。"}, {"text": "教练", "is_correct": false, "explanation": "搭配：“教练”通常用于体育或训练，与报社的职位搭配不当。"}], "explanations": {"主编": "“主编”指报刊编辑工作的主要负责人，“这家报社的”搭配自然，符合句意。", "歌手": "语义：报社的负责人与唱歌无关，“报社的歌手”说不通。", "演员": "语义：报社不是演出的地方，“报社的演员”与句子的语境不符。", "教练": "搭配：“教练”通常用于体育或训练，与报社的职位搭配不当。"}, "sentence_index": 0, "correct_answer": "主编"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所大学的主编很严格。", "explanation": "这里应该用〈院长〉。“主编”只用于书刊、报刊，大学的负责人要用“院长”。"}, {"text": "球队的主编带领大家训练。", "explanation": "这里应该用〈队长〉。“主编”只用于书刊、报刊，带领球队的人要用“队长”。"}, {"text": "班里的主编负责记录考勤。", "explanation": "这里应该用〈班长〉。“主编”只用于书刊、报刊，班级的负责人要用“班长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992aa609-38af-47ce-a8c5-208f71a1ab07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95476, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主编", "is_correct": true, "explanation": "“主编”是报刊编辑工作的负责人，“从记者做到了”之后接这个职位，符合句意。"}, {"text": "园丁", "is_correct": false, "explanation": "语义：园丁与报社的工作无关，“从记者做到了园丁”说不通。"}, {"text": "船长", "is_correct": false, "explanation": "语义：记者与船长之间没有职业升迁的关系，句子说不通。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师与记者、编辑工作之间没有职业升迁的关系，句子说不通。"}], "explanations": {"主编": "“主编”是报刊编辑工作的负责人，“从记者做到了”之后接这个职位，符合句意。", "园丁": "语义：园丁与报社的工作无关，“从记者做到了园丁”说不通。", "船长": "语义：记者与船长之间没有职业升迁的关系，句子说不通。", "厨师": "语义：厨师与记者、编辑工作之间没有职业升迁的关系，句子说不通。"}, "sentence_index": 6, "correct_answer": "主编"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工厂请了一位主编。", "explanation": "这里应该用〈厂长〉。“主编”只用于书刊、报刊的编辑工作，工厂的负责人要用“厂长”。"}, {"text": "这家餐厅请了一位主编。", "explanation": "这里应该用〈经理〉。“主编”只用于书刊、报刊，餐厅的负责人要用“经理”。"}, {"text": "这家银行请了一位主编。", "explanation": "这里应该用〈行长〉。“主编”只用于书刊、报刊，银行的负责人要用“行长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992aa609-38af-47ce-a8c5-208f71a1ab07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95476, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家杂志社聘请了一只资深主编。", "corrected_sentence": "这家杂志社聘请了一位资深主编。", "error_description": "“主编”指人，量词应当用“位”（或“个”），不能用“只”。正确的说法是“一位资深主编”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992aa609-38af-47ce-a8c5-208f71a1ab07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95476, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把书稿交给着主编审阅。", "corrected_sentence": "她把书稿交给了主编审阅。", "error_description": "“交给”表示动作已经完成，应用“了”，这里误用了“着”，句子不通。正确的说法是“交给了主编审阅”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992aa609-38af-47ce-a8c5-208f71a1ab07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95479, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "恶劣", "is_correct": true, "explanation": "正确答案。恶劣是“优良”的反义词，指条件或质量很差，与这里的好坏相对。"}, {"text": "干净", "is_correct": false, "explanation": "干净只说清洁程度，与“优良”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "安静形容声音或环境不吵，与“优良”不是反义词。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚指明白、不模糊，与“优良”没有反义关系。"}], "correct_answer": "恶劣", "explanations": {"恶劣": "正确答案。恶劣是“优良”的反义词，指条件或质量很差，与这里的好坏相对。", "干净": "干净只说清洁程度，与“优良”没有反义关系。", "安静": "安静形容声音或环境不吵，与“优良”不是反义词。", "清楚": "清楚指明白、不模糊，与“优良”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7937752-e703-4b5d-9a4a-a9a1ce602180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95479, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "恶劣", "is_correct": true, "explanation": "正确答案。恶劣是“优良”的反义词，指条件或质量很差，与这里的好坏相对。"}, {"text": "整齐", "is_correct": false, "explanation": "整齐指排列有序，与“优良”没有反义关系。"}, {"text": "粗心", "is_correct": false, "explanation": "粗心指做事不仔细，与“优良”不是反义词。"}, {"text": "热闹", "is_correct": false, "explanation": "热闹指人多声音大，与“优良”没有反义关系。"}], "correct_answer": "恶劣", "explanations": {"恶劣": "正确答案。恶劣是“优良”的反义词，指条件或质量很差，与这里的好坏相对。", "整齐": "整齐指排列有序，与“优良”没有反义关系。", "粗心": "粗心指做事不仔细，与“优良”不是反义词。", "热闹": "热闹指人多声音大，与“优良”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7937752-e703-4b5d-9a4a-a9a1ce602180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95479, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很好，比一般的更好。", "primary_collocate": null, "pronunciation": "yōu liáng", "ipa": "joʊ˥˥ ljɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这里的空气质量优良。", "target_word": "优良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水果是优良品种，又大又甜。", "target_word": "优良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂的设备优良，工人也很努力。", "target_word": "优良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民选了优良的种子。", "target_word": "优良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个学校的学习环境非常优良。", "target_word": "优良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种布质地优良，穿着很舒服。", "target_word": "优良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有优良的身体条件，适合踢足球。", "target_word": "优良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天路况优良，开车很安全。", "target_word": "优良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给客人提供优良的服务。", "target_word": "优良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方有优良的港口，船很多。", "target_word": "优良", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "优良品种", "label": "复合"}, {"form": "优良传统", "label": "复合"}, {"form": "優良", "label": "繁体"}], "register": "书面", "sense_fingerprint": "事物条件、质量等明显好于一般", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd704c3d5-d131-4402-9bb4-f26ec0ee93c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95479, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "优良", "is_correct": true, "explanation": "正确答案。优良（yōu liáng）指很好、比一般的更好。"}, {"text": "油粮", "is_correct": false, "explanation": "油粮（yóu liáng）与优良（yōu liáng）第一个音节声调不同，意思是油料和粮食。"}, {"text": "悠扬", "is_correct": false, "explanation": "悠扬（yōu yáng）与优良（yōu liáng）第二个音节声母不同，liáng 有 l 声母，yáng 没有，意思是声音悠长动听。"}, {"text": "油量", "is_correct": false, "explanation": "油量（yóu liàng）与优良（yōu liáng）第一个音节声调不同，第二个音节声调也不同，意思是油的数量。"}], "explanations": {"优良": "正确答案。优良（yōu liáng）指很好、比一般的更好。", "油粮": "油粮（yóu liáng）与优良（yōu liáng）第一个音节声调不同，意思是油料和粮食。", "悠扬": "悠扬（yōu yáng）与优良（yōu liáng）第二个音节声母不同，liáng 有 l 声母，yáng 没有，意思是声音悠长动听。", "油量": "油量（yóu liàng）与优良（yōu liáng）第一个音节声调不同，第二个音节声调也不同，意思是油的数量。"}, "sentence_index": null, "correct_answer": "优良"}, "level_3": {"options": [{"text": "优良", "is_correct": true, "explanation": "正确答案。优良表示质量很好，正好用来评价空气质量。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”只形容外表好看，不能用来评价空气质量。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容人的头脑灵活，不能用来评价空气质量。"}, {"text": "脏", "is_correct": false, "explanation": "搭配：“脏”说卫生状况不干净，一般不说“空气质量脏”，这里不通。"}], "explanations": {"优良": "正确答案。优良表示质量很好，正好用来评价空气质量。", "漂亮": "体貌：“漂亮”只形容外表好看，不能用来评价空气质量。", "聪明": "语义：“聪明”形容人的头脑灵活，不能用来评价空气质量。", "脏": "搭配：“脏”说卫生状况不干净，一般不说“空气质量脏”，这里不通。"}, "sentence_index": 0, "correct_answer": "优良"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他长得很优良。", "explanation": "这里应该用〈好看〉。优良说事物的质量或条件，不用来形容人的外貌。"}, {"text": "这道菜的味道很优良，我想再吃一碗。", "explanation": "这里应该用〈好吃〉。优良说质量或条件，不用来形容味道的好坏。"}, {"text": "他跑得很优良。", "explanation": "这里应该用〈好〉。优良不用来评价动作的做法，说跑得好要用〈好〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7937752-e703-4b5d-9a4a-a9a1ce602180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95479, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "优良", "is_correct": true, "explanation": "正确答案。优良表示质量好，用来形容身体条件很好，符合句子。"}, {"text": "贵", "is_correct": false, "explanation": "搭配：“贵”说价格高，不能用来形容身体条件。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“高兴”说心情，不能用来形容身体条件。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”说味道，不能用来形容身体条件。"}], "explanations": {"优良": "正确答案。优良表示质量好，用来形容身体条件很好，符合句子。", "贵": "搭配：“贵”说价格高，不能用来形容身体条件。", "高兴": "语义：“高兴”说心情，不能用来形容身体条件。", "甜": "语义：“甜”说味道，不能用来形容身体条件。"}, "sentence_index": 6, "correct_answer": "优良"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次会议的参加人数很优良。", "explanation": "这里应该用〈多〉。优良说质量，不用来说人数的多少。"}, {"text": "这座山很优良，有三千米高。", "explanation": "这里应该用〈高〉。优良不表示高度，说山的高度要用〈高〉。"}, {"text": "这家饭店的价格很优良，一个人只要十块钱。", "explanation": "这里应该用〈便宜〉。优良说质量或条件，不用来说价格的高低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7937752-e703-4b5d-9a4a-a9a1ce602180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95479, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家商店的服务没优良，顾客很多。", "corrected_sentence": "这家商店的服务不优良，顾客很多。", "error_description": "错误形式：“没优良”；正确形式：“不优良”。表示性质的否定要用“不”，“没”一般不用来否定形容词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7937752-e703-4b5d-9a4a-a9a1ce602180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95479, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小区的环境比以前很优良得多，适合老人住。", "corrected_sentence": "这个小区的环境比以前优良得多，适合老人住。", "error_description": "错误：“很优良得多”。比较句中“得多”已表示程度差别，不能再加“很”，应去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7937752-e703-4b5d-9a4a-a9a1ce602180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95480, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低劣", "is_correct": true, "explanation": "正确答案。低劣是“优良”的反义词，指品质差，与这里的品质好坏相对。"}, {"text": "干净", "is_correct": false, "explanation": "干净只说清洁程度，与“优良”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "安静形容声音或环境不吵，与“优良”不是反义词。"}, {"text": "整齐", "is_correct": false, "explanation": "整齐指排列有序，与“优良”没有反义关系。"}], "correct_answer": "低劣", "explanations": {"低劣": "正确答案。低劣是“优良”的反义词，指品质差，与这里的品质好坏相对。", "干净": "干净只说清洁程度，与“优良”没有反义关系。", "安静": "安静形容声音或环境不吵，与“优良”不是反义词。", "整齐": "整齐指排列有序，与“优良”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7937752-e703-4b5d-9a4a-a9a1ce602180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
