INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95480, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "品质、成绩等良好。", "primary_collocate": null, "pronunciation": "yōu liáng", "ipa": "joʊ˥˥ ljɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他这次考试成绩优良。", "target_word": "优良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的学习成绩一直很优良。", "target_word": "优良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的品德优良，大家都喜欢他。", "target_word": "优良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批产品质量优良，可以卖到国外。", "target_word": "优良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国人有很多优良的传统。", "target_word": "优良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子要养成优良的习惯。", "target_word": "优良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本学期他的成绩优良，没有不及格。", "target_word": "优良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个班的大部分考试成绩都很优良。", "target_word": "优良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小受到优良的教育。", "target_word": "优良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要保持这种优良的作风。", "target_word": "优良", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "优良传统", "label": "复合"}, {"form": "优良作风", "label": "复合"}, {"form": "優良", "label": "繁体"}], "register": "书面", "sense_fingerprint": "品质、成绩、品德、传统等良好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd704c3d5-d131-4402-9bb4-f26ec0ee93c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
