INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95486, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "法院依法对罪犯作出刑罚的判决。", "primary_collocate": null, "pronunciation": "pàn chǔ", "ipa": "pʰan˥˩ ʈʂʰu˨˩˦", "syllable_count": 2, "sentences": [{"text": "法院依法判处他有期徒刑五年。", "target_word": "判处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院判处这个罪犯无期徒刑。", "target_word": "判处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官判处小偷拘役三个月。", "target_word": "判处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他犯了重罪，法院判处他死刑。", "target_word": "判处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院判处公司老板罚款十万元。", "target_word": "判处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院依法判处两名罪犯有期徒刑。", "target_word": "判处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官当众判处那个人三年徒刑。", "target_word": "判处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个案子，法院判处他缓刑一年。", "target_word": "判处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院判处他有期徒刑，他不服。", "target_word": "判处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法庭上，法官判处罪犯十年有期徒刑。", "target_word": "判处", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "判处了", "label": "体标"}], "register": "正式", "sense_fingerprint": "法院依法给罪犯定下刑罚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55addd89-518c-40da-814b-2ea91ff12618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95486, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "审理", "is_correct": false, "explanation": "语义：审理是受理、审查案件，不能直接给人定下刑期，“有期徒刑五年”接在它后面说不通。"}, {"text": "判处", "is_correct": true, "explanation": "判处：法院依法给罪犯定下刑罚，与“有期徒刑五年”相合。"}, {"text": "赔偿", "is_correct": false, "explanation": "搭配：“赔偿”的对象是损失或钱款，不能接“有期徒刑五年”。"}, {"text": "释放", "is_correct": false, "explanation": "语义：释放是把人放出来，与“有期徒刑五年”的判决正好相反。"}], "explanations": {"审理": "语义：审理是受理、审查案件，不能直接给人定下刑期，“有期徒刑五年”接在它后面说不通。", "判处": "判处：法院依法给罪犯定下刑罚，与“有期徒刑五年”相合。", "赔偿": "搭配：“赔偿”的对象是损失或钱款，不能接“有期徒刑五年”。", "释放": "语义：释放是把人放出来，与“有期徒刑五年”的判决正好相反。"}, "sentence_index": 0, "correct_answer": "判处"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "法院判处了他的道歉。", "explanation": "这里应该用〈接受〉。判处只针对罪犯定刑，对道歉应说〈接受〉。"}, {"text": "学校判处了打架的学生。", "explanation": "这里应该用〈处罚〉。判处只用于法院对罪犯定罪，学校处理学生要用〈处罚〉。"}, {"text": "法院今天判处了这起案件。", "explanation": "这里应该用〈宣判〉。判处的对象是罪犯，案件的判决结果要用〈宣判〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ac0ca0-d16b-45be-ac1e-5dbb03f8730c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95486, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "关押", "is_correct": false, "explanation": "配价：“关押”不能直接带“三年徒刑”作宾语，刑期不是被关押的对象。"}, {"text": "判处", "is_correct": true, "explanation": "判处：法官依法定下刑罚，“三年徒刑”与之相合。"}, {"text": "审讯", "is_correct": false, "explanation": "语义：审讯是讯问，不是判定刑期，与“三年徒刑”接不上。"}, {"text": "逮捕", "is_correct": false, "explanation": "语义：逮捕是拘捕人身，不是定下刑期，句子表达的意思不成立。"}], "explanations": {"关押": "配价：“关押”不能直接带“三年徒刑”作宾语，刑期不是被关押的对象。", "判处": "判处：法官依法定下刑罚，“三年徒刑”与之相合。", "审讯": "语义：审讯是讯问，不是判定刑期，与“三年徒刑”接不上。", "逮捕": "语义：逮捕是拘捕人身，不是定下刑期，句子表达的意思不成立。"}, "sentence_index": 6, "correct_answer": "判处"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "法院判处他三天后出庭。", "explanation": "这里应该用〈通知〉。判处是对罪犯定下刑罚，不能用来告知开庭时间。"}, {"text": "法院判处了他的上诉。", "explanation": "这里应该用〈受理〉。判处的对象是罪犯，法院接受上诉要用〈受理〉。"}, {"text": "法院判处了搜查令。", "explanation": "这里应该用〈颁发〉。判处用于给人定刑罚，搜查令是文件，要用〈颁发〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ac0ca0-d16b-45be-ac1e-5dbb03f8730c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95486, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "法院判处给那名司机两年有期徒刑。", "corrected_sentence": "法院判处那名司机两年有期徒刑。", "error_description": "多加了“给”：判处直接带双宾语（先接受判的人，再接刑罚），不能在“判处”后加“给”，应说“法院判处那名司机两年有期徒刑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ac0ca0-d16b-45be-ac1e-5dbb03f8730c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95486, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他判处了五年有期徒刑。", "corrected_sentence": "他被法院判处了五年有期徒刑。", "error_description": "被动句漏用“被”：“他”是被判处的人，应说“他被法院判处了五年有期徒刑”；“他判处了……”中“他”成了施事，说不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ac0ca0-d16b-45be-ac1e-5dbb03f8730c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
