INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95487, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "第一个把一件大事、一家公司做起来的人。", "primary_collocate": null, "pronunciation": "chuàng shǐ rén", "ipa": "ʈʂʰu̯ɑŋ˥˩ ʂʐ̩˨˩˦ ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "他是这家公司的创始人。", "target_word": "创始人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司创始人每天都早早来上班。", "target_word": "创始人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店的创始人以前是一位厨师。", "target_word": "创始人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "创始人把所有的钱都放进了公司。", "target_word": "创始人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很想见一见这家网站的创始人。", "target_word": "创始人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "创始人说，公司最难的是第一年。", "target_word": "创始人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个品牌的创始人已经七十岁了。", "target_word": "创始人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "创始人给新来的员工讲了公司的故事。", "target_word": "创始人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是这家学校的创始人之一。", "target_word": "创始人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的创始人想把生意做到国外去。", "target_word": "创始人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位创始人", "label": "量词"}, {"form": "联合创始人", "label": "复合"}, {"form": "創始人", "label": "繁体"}], "register": "中性", "sense_fingerprint": "第一个把公司或大事做起来的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e80955d-5d4f-40de-8cbf-bf9a5acaa222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95487, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "创始人", "is_correct": true, "explanation": "正确。“创始人”指第一个把公司做起来的人，“这家公司的”后面正好接这一身份。"}, {"text": "校长", "is_correct": false, "explanation": "搭配：“校长”管理学校，公司不说“校长”。"}, {"text": "院长", "is_correct": false, "explanation": "搭配：“院长”多指学院、医院的负责人，不用于公司。"}, {"text": "病人", "is_correct": false, "explanation": "语义：“病人”指患病的人，句子说的是公司的身份，与此不合。"}], "explanations": {"创始人": "正确。“创始人”指第一个把公司做起来的人，“这家公司的”后面正好接这一身份。", "校长": "搭配：“校长”管理学校，公司不说“校长”。", "院长": "搭配：“院长”多指学院、医院的负责人，不用于公司。", "病人": "语义：“病人”指患病的人，句子说的是公司的身份，与此不合。"}, "sentence_index": 0, "correct_answer": "创始人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本小说的创始人是一位年轻的女作家。", "explanation": "这里应该用〈作者〉。“创始人”指创立公司、组织或事业的人，小说是作者写出来的，不能说“创始人”。"}, {"text": "这台机器的创始人是一位德国工程师。", "explanation": "这里应该用〈发明人〉。“创始人”指创立公司、组织或事业的人，机器是被发明出来的，要用“发明人”。"}, {"text": "这首歌的创始人是一位年轻的歌手。", "explanation": "这里应该用〈作曲家〉。“创始人”指创立组织或事业的人，歌曲是作曲家创作出来的，不能说“创始人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992aa609-38af-47ce-a8c5-208f71a1ab07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95487, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "创始人", "is_correct": true, "explanation": "正确。“创始人”指创立品牌的人，句中说他已经七十岁，符合身份。"}, {"text": "班主任", "is_correct": false, "explanation": "搭配：“班主任”管理班级，品牌不能有班主任。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿不可能已经七十岁，与句中的年龄矛盾。"}, {"text": "学生", "is_correct": false, "explanation": "语义：“学生”指在校读书的人，品牌的学生已七十岁，与常理不符。"}], "explanations": {"创始人": "正确。“创始人”指创立品牌的人，句中说他已经七十岁，符合身份。", "班主任": "搭配：“班主任”管理班级，品牌不能有班主任。", "婴儿": "语义：婴儿不可能已经七十岁，与句中的年龄矛盾。", "学生": "语义：“学生”指在校读书的人，品牌的学生已七十岁，与常理不符。"}, "sentence_index": 6, "correct_answer": "创始人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子的创始人很有名。", "explanation": "这里应该用〈设计师〉。“创始人”指创立公司、组织或事业的人，椅子是设计出来的，不能说“创始人”。"}, {"text": "这只猫的创始人是一位老奶奶。", "explanation": "这里应该用〈主人〉。“创始人”指创立事业或组织的人，不能用于动物的所有者。"}, {"text": "这部电影的创始人今年刚满三十岁。", "explanation": "这里应该用〈导演〉。“创始人”指创立事业或组织的人，电影是拍摄出来的，不能说“创始人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992aa609-38af-47ce-a8c5-208f71a1ab07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95487, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我认识这家公司的一只创始人。", "corrected_sentence": "我认识这家公司的一位创始人。", "error_description": "“创始人”指人，量词应用“位”，不能用“只”（“只”多用于动物或物品）。“一只创始人”应改为“一位创始人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992aa609-38af-47ce-a8c5-208f71a1ab07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95487, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司得创始人很喜欢打篮球。", "corrected_sentence": "这家公司的创始人很喜欢打篮球。", "error_description": "“创始人”前面用“这家公司”修饰时要用“的”，不能用“得”。“得”用在动词或形容词后面表示程度或结果，不能修饰名词。应改为“这家公司的创始人很喜欢打篮球。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992aa609-38af-47ce-a8c5-208f71a1ab07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
