INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95495, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在有些国家里，被选出来替大家商量大事的人。", "primary_collocate": null, "pronunciation": "cān yì yuán", "ipa": "tsʰan˥ i˥˩ ɥɛn˧˥", "syllable_count": 3, "sentences": [{"text": "人们选他当参议员，替大家说话。", "target_word": "参议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位参议员替老百姓商量大事。", "target_word": "参议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参议员是选出来的，不是考出来的。", "target_word": "参议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很想让选民选他做参议员。", "target_word": "参议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的参议员由人民选出。", "target_word": "参议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位参议员常常去听选民的意见。", "target_word": "参议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她当了参议员，要替家乡人说话。", "target_word": "参议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参议员要为大家商量国家大事。", "target_word": "参议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参议员昨天到学校看望了同学们。", "target_word": "参议员", "complexity_tier": "T3", "furigana": "cān yì yuán zuó tiān dào xué xiào kàn wàng le tóng xué men", "sentence_source": "generated"}, {"text": "选民今年选出了一位新参议员。", "target_word": "参议员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "女参议员", "label": "复合"}], "register": "书面", "sense_fingerprint": "选出来替大家商量大事的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0240c25c-1339-443c-bf73-9fd83a71d5f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95495, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "参议员", "is_correct": true, "explanation": "参议员：由选民选出、替大家商量大事的人，符合“人们选他当……替大家说话”的语境。"}, {"text": "木匠", "is_correct": false, "explanation": "语义：木匠不是由选民选出来替大家商量大事的人，句中“替大家说话”说不通。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师不负责替大家发言，句中“替大家说话”说不通。"}, {"text": "老爷", "is_correct": false, "explanation": "语域：“老爷”是旧式的尊称，与现代“选”和“替大家说话”的语境不合。"}], "explanations": {"参议员": "参议员：由选民选出、替大家商量大事的人，符合“人们选他当……替大家说话”的语境。", "木匠": "语义：木匠不是由选民选出来替大家商量大事的人，句中“替大家说话”说不通。", "厨师": "语义：厨师不负责替大家发言，句中“替大家说话”说不通。", "老爷": "语域：“老爷”是旧式的尊称，与现代“选”和“替大家说话”的语境不合。"}, "sentence_index": 0, "correct_answer": "参议员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班选他做参议员，负责管理班费。", "explanation": "这里应该用〈班长〉。班里选出的是班长；参议员是国家议会的议员，不能用于班级。"}, {"text": "公司选出了一名参议员，去和客户谈判。", "explanation": "这里应该用〈代表〉。公司派去谈判的是代表；参议员是议会的议员，与公司无关。"}, {"text": "他是参加高考的参议员，每天复习功课。", "explanation": "这里应该用〈考生〉。参加高考、每天复习功课的是考生；参议员是选出来替大家商量大事的人，与考试无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95bade41-f44b-48bc-8fad-b923e7b51524') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95495, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "参议员", "is_correct": true, "explanation": "参议员：由选民选出、替选民说话的人，符合“她当了……要替家乡人说话”的语境。"}, {"text": "司机", "is_correct": false, "explanation": "语义：司机不是选出来替大家商量大事的人，“替家乡人说话”说不通。"}, {"text": "理发师", "is_correct": false, "explanation": "语义：理发师没有替人发言的职责，与“当了……要替家乡人说话”不合。"}, {"text": "主子", "is_correct": false, "explanation": "语域：“主子”是旧时的称呼，与现代选举语境下“替家乡人说话”的说法不合。"}], "explanations": {"参议员": "参议员：由选民选出、替选民说话的人，符合“她当了……要替家乡人说话”的语境。", "司机": "语义：司机不是选出来替大家商量大事的人，“替家乡人说话”说不通。", "理发师": "语义：理发师没有替人发言的职责，与“当了……要替家乡人说话”不合。", "主子": "语域：“主子”是旧时的称呼，与现代选举语境下“替家乡人说话”的说法不合。"}, "sentence_index": 6, "correct_answer": "参议员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那位参议员每天给病人量体温。", "explanation": "这里应该用〈护士〉。给病人量体温的是护士，参议员不做这类工作。"}, {"text": "那位参议员每天在田里种小麦。", "explanation": "这里应该用〈农民〉。在田里种小麦的是农民，参议员与种地无关。"}, {"text": "那位参议员每天在街上巡逻，维护治安。", "explanation": "这里应该用〈警察〉。在街上巡逻、维护治安的是警察；参议员是替大家商量大事的人，不负责治安。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95bade41-f44b-48bc-8fad-b923e7b51524') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95495, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "选民选他成参议员。", "corrected_sentence": "选民选他为参议员。", "error_description": "错误：“选成”。正确：“选为”。“选为”表示经选举担任某个职务，“为”是结果补语，“成”不能用于这一结构。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95bade41-f44b-48bc-8fad-b923e7b51524') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95495, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们州选出了一位年轻地参议员。", "corrected_sentence": "我们州选出了一位年轻的参议员。", "error_description": "错误：修饰“参议员”的“年轻”后应用“的”，却用了“地”。正确：“年轻的参议员”。“地”用于修饰动词，修饰名词要用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95bade41-f44b-48bc-8fad-b923e7b51524') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
