INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95501, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "有一点吃惊的时候，说出来的声音。", "primary_collocate": null, "pronunciation": "yō", "ipa": "jɔ˥˥", "syllable_count": 1, "sentences": [{"text": "哟，你今天怎么来这么早？", "target_word": "哟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哟，这是谁的新手机？", "target_word": "哟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哟，外面下雪了！", "target_word": "哟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哟，你的头发剪短了。", "target_word": "哟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哟，这么多人都在等你呢。", "target_word": "哟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哟，今天的菜真丰富。", "target_word": "哟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哟，你什么时候学会做饭的？", "target_word": "哟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哟，这孩子长得真快。", "target_word": "哟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哟，你们都在这儿啊。", "target_word": "哟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哟，这条裙子真好看！", "target_word": "哟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "喲", "label": "繁体"}], "register": "口语", "sense_fingerprint": "句首叹词，表示有点吃惊", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e80955d-5d4f-40de-8cbf-bf9a5acaa222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95501, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "哟", "is_correct": true, "explanation": "正确：哟 yō，句首表示有点吃惊时说出的声音。"}, {"text": "压", "is_correct": false, "explanation": "压（第一声）与哟的区别在于韵母：yā 与 yō 元音不同，意思是用力按住。"}, {"text": "窝", "is_correct": false, "explanation": "窝（第一声）与哟的区别在于声母：wō 与 yō 声母不同，意思是鸟巢或住处。"}, {"text": "波", "is_correct": false, "explanation": "波（第一声）与哟的区别在于声母：bō 与 yō 声母不同，意思是水的起伏。"}, {"text": "摸", "is_correct": false, "explanation": "摸（第一声）与哟的区别在于声母：mō 与 yō 声母不同，意思是用手触碰。"}, {"text": "坡", "is_correct": false, "explanation": "坡（第一声）与哟的区别在于声母：pō 与 yō 声母不同，意思是斜面。"}], "explanations": {"哟": "正确：哟 yō，句首表示有点吃惊时说出的声音。", "压": "压（第一声）与哟的区别在于韵母：yā 与 yō 元音不同，意思是用力按住。", "窝": "窝（第一声）与哟的区别在于声母：wō 与 yō 声母不同，意思是鸟巢或住处。", "波": "波（第一声）与哟的区别在于声母：bō 与 yō 声母不同，意思是水的起伏。", "摸": "摸（第一声）与哟的区别在于声母：mō 与 yō 声母不同，意思是用手触碰。", "坡": "坡（第一声）与哟的区别在于声母：pō 与 yō 声母不同，意思是斜面。"}, "sentence_index": null, "correct_answer": "哟"}, "level_3": {"options": [{"text": "哟", "is_correct": true, "explanation": "正确。句首的哟表示有点吃惊，适合这里的意外语气。"}, {"text": "嘘", "is_correct": false, "explanation": "语义：“嘘”用来让人安静，与这里的惊讶和询问不合。"}, {"text": "啧", "is_correct": false, "explanation": "语义：“啧”表示不满或咂嘴，与这里的惊讶不合。"}, {"text": "呸", "is_correct": false, "explanation": "语域：“呸”表示唾弃、鄙视，对同事这样说非常失礼。"}], "explanations": {"哟": "正确。句首的哟表示有点吃惊，适合这里的意外语气。", "嘘": "语义：“嘘”用来让人安静，与这里的惊讶和询问不合。", "啧": "语义：“啧”表示不满或咂嘴，与这里的惊讶不合。", "呸": "语域：“呸”表示唾弃、鄙视，对同事这样说非常失礼。"}, "sentence_index": 0, "correct_answer": "哟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "哟，我的脚扭了，疼死了！", "explanation": "这里表示疼痛应用〈哎哟〉。“哟”表示吃惊，不用于表示疼痛。"}, {"text": "哟，会议定于下午三点在二楼会议室召开。", "explanation": "这里是正式通知，应直接陈述。表示吃惊的叹词“哟”用在这种语境中不合语体。"}, {"text": "哟，老人家昨天去世了，大家都很难过。", "explanation": "这里表示哀伤应用〈唉〉。“哟”表示吃惊，不用于哀伤的语境。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992aa609-38af-47ce-a8c5-208f71a1ab07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95501, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哟", "is_correct": true, "explanation": "正确。句首的哟表示有点吃惊，符合这句的好奇询问。"}, {"text": "唉", "is_correct": false, "explanation": "语义：“唉”表示叹气或遗憾，与这句的好奇询问不符。"}, {"text": "嗟", "is_correct": false, "explanation": "语域：“嗟”是文言的叹词，用于这种口语询问很不协调。"}, {"text": "哼", "is_correct": false, "explanation": "语义：“哼”表示不屑或不满，与“学会做饭”的好奇语气相反。"}], "explanations": {"哟": "正确。句首的哟表示有点吃惊，符合这句的好奇询问。", "唉": "语义：“唉”表示叹气或遗憾，与这句的好奇询问不符。", "嗟": "语域：“嗟”是文言的叹词，用于这种口语询问很不协调。", "哼": "语义：“哼”表示不屑或不满，与“学会做饭”的好奇语气相反。"}, "sentence_index": 6, "correct_answer": "哟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "哟，我的名字叫李明。", "explanation": "这里“哟”表示吃惊，用在平静的自我介绍中语气不对。应直接陈述，不用表示惊讶的叹词。"}, {"text": "哟，请您把门关上。", "explanation": "这里“哟”表示吃惊，用在礼貌的请求句开头语气不对。礼貌请求不用表示惊讶的叹词。"}, {"text": "哟，明天的天气是晴天。", "explanation": "这里“哟”表示吃惊，用在平淡的天气预报中语气不对。平静陈述事实时不用表示惊讶的叹词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992aa609-38af-47ce-a8c5-208f71a1ab07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95501, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "哟，这件衣服哟真便宜！", "corrected_sentence": "哟，这件衣服真便宜！", "error_description": "“哟”作叹词表示吃惊时只能放在句首，不能插在“这件衣服”和“真”之间。应改为“哟，这件衣服真便宜！”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992aa609-38af-47ce-a8c5-208f71a1ab07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95501, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "哟，你怎么又迟到哟了！", "corrected_sentence": "哟，你怎么又迟到了！", "error_description": "“哟”作叹词表示吃惊时只用于句首，不能插在动词和“了”之间。应改为“哟，你怎么又迟到了！”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992aa609-38af-47ce-a8c5-208f71a1ab07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
