INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95502, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "句末语气词，表示提醒、叮嘱的语气。", "primary_collocate": null, "pronunciation": "yo", "ipa": "jo", "syllable_count": 1, "sentences": [{"text": "小心点儿哟，地上很滑。", "target_word": "哟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快点儿哟，车马上就要开了。", "target_word": "哟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别忘了带伞哟。", "target_word": "哟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天很冷哟，多穿一件衣服。", "target_word": "哟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上慢点儿开哟！", "target_word": "哟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天要考试哟，今晚早点睡。", "target_word": "哟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人是你老师哟，要打招呼。", "target_word": "哟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汤很烫哟，先别喝。", "target_word": "哟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是最后一次机会哟。", "target_word": "哟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记得给妈妈打电话哟。", "target_word": "哟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "喲", "label": "繁体"}], "register": "口语", "sense_fingerprint": "句末语气词，表示提醒、叮嘱的语气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e80955d-5d4f-40de-8cbf-bf9a5acaa222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95502, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哟", "is_correct": true, "explanation": "正确。句末的哟表示提醒、叮嘱，符合“小心点儿”的语气。"}, {"text": "吗", "is_correct": false, "explanation": "语义：“吗”用于疑问句，这里是叮嘱，加上“吗”就变成了问句，句意不通。"}, {"text": "了", "is_correct": false, "explanation": "体貌：“了”表示动作完成或状态变化，不能用在“小心点儿”这样的祈使句后。"}, {"text": "乎", "is_correct": false, "explanation": "语域：“乎”是文言语气词，用在这种口语叮嘱里很不协调。"}], "explanations": {"哟": "正确。句末的哟表示提醒、叮嘱，符合“小心点儿”的语气。", "吗": "语义：“吗”用于疑问句，这里是叮嘱，加上“吗”就变成了问句，句意不通。", "了": "体貌：“了”表示动作完成或状态变化，不能用在“小心点儿”这样的祈使句后。", "乎": "语域：“乎”是文言语气词，用在这种口语叮嘱里很不协调。"}, "sentence_index": 0, "correct_answer": "哟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请各位于本月底前提交书面报告哟。", "explanation": "这里是正式的书面要求，句末口语语气词“哟”与之不合。"}, {"text": "本规定自发布之日起施行哟。", "explanation": "这里是法规用语，句末语气词“哟”语体不合。"}, {"text": "特此通知，全体人员须佩戴工作证入场哟。", "explanation": "这里是公告文体，句末语气词“哟”语体不合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992aa609-38af-47ce-a8c5-208f71a1ab07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95502, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哟", "is_correct": true, "explanation": "正确。句末的哟表示提醒，符合这句的叮嘱语气。"}, {"text": "着", "is_correct": false, "explanation": "体貌：“着”表示动作进行或状态持续，用在“是……”这样的判断句后不通。"}, {"text": "矣", "is_correct": false, "explanation": "语域：“矣”是文言语气词，用于口语叮嘱很不协调。"}, {"text": "哉", "is_correct": false, "explanation": "语域：“哉”是文言的感叹语气词，与这句口语叮嘱不符。"}], "explanations": {"哟": "正确。句末的哟表示提醒，符合这句的叮嘱语气。", "着": "体貌：“着”表示动作进行或状态持续，用在“是……”这样的判断句后不通。", "矣": "语域：“矣”是文言语气词，用于口语叮嘱很不协调。", "哉": "语域：“哉”是文言的感叹语气词，与这句口语叮嘱不符。"}, "sentence_index": 6, "correct_answer": "哟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "根据公司规定，员工须在三日内完成登记哟。", "explanation": "这里是正式规定，句末语气词“哟”语体不合，应去掉。"}, {"text": "本次考试的成绩将于下周正式公布哟。", "explanation": "这里是正式通知，句末口语语气词“哟”与之不合。"}, {"text": "关于办公用品管理的通知已经下发哟。", "explanation": "这里是公文用语，句末语气词“哟”语体不合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992aa609-38af-47ce-a8c5-208f71a1ab07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95502, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "晚上别忘了关窗户哟哟。", "corrected_sentence": "晚上别忘了关窗户哟。", "error_description": "“哟”作句末语气词只用一次，重复成“哟哟”不自然。应改为“晚上别忘了关窗户哟。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992aa609-38af-47ce-a8c5-208f71a1ab07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95502, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明早记得带哟伞。", "corrected_sentence": "明早记得带伞哟。", "error_description": "“哟”是句末语气词，应放在句尾，不能插在“带”和“伞”之间。应改为“明早记得带伞哟。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992aa609-38af-47ce-a8c5-208f71a1ab07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
