INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95505, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "一件事一直让人心里烦、不舒服。", "primary_collocate": null, "pronunciation": "kùn rǎo", "ipa": "kʰuən˥˩ ɻaʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "一个坏消息困扰着我。", "target_word": "困扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那件事一直困扰着她。", "target_word": "困扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居的声音困扰了我一晚上。", "target_word": "困扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个想法困扰着他很多天。", "target_word": "困扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试的事困扰着我，睡不着。", "target_word": "困扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "找不到工作的事困扰着哥哥。", "target_word": "困扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牙疼困扰了他一个星期。", "target_word": "困扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要让坏心情困扰你。", "target_word": "困扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学说的话一直困扰着我。", "target_word": "困扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同样的梦困扰着她很多年。", "target_word": "困扰", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "困扰着", "label": "体标"}, {"form": "困扰了", "label": "体标"}, {"form": "困扰过", "label": "体标"}, {"form": "困擾", "label": "繁体"}], "register": "书面", "sense_fingerprint": "某件事持续让人心烦不舒服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7e57d5e-0600-40a5-bf17-17abc02ebec0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95505, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "困扰", "is_correct": true, "explanation": "正确。“困扰”表示一件事持续让人心烦，符合“坏消息一直让我不舒服”的语境。"}, {"text": "鼓舞", "is_correct": false, "explanation": "语义：坏消息会使人沮丧，不能鼓舞人。"}, {"text": "安慰", "is_correct": false, "explanation": "语义：坏消息不能安慰人。"}, {"text": "照顾", "is_correct": false, "explanation": "搭配：“照顾”的施事要是人，坏消息不能照顾我。"}], "explanations": {"困扰": "正确。“困扰”表示一件事持续让人心烦，符合“坏消息一直让我不舒服”的语境。", "鼓舞": "语义：坏消息会使人沮丧，不能鼓舞人。", "安慰": "语义：坏消息不能安慰人。", "照顾": "搭配：“照顾”的施事要是人，坏消息不能照顾我。"}, "sentence_index": 0, "correct_answer": "困扰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "别困扰爷爷看书。", "explanation": "这里应该用〈打搅〉。“打搅”指妨碍别人做事，“困扰”指使人心里烦恼，不用于妨碍看书。"}, {"text": "他困扰着这个想法很多天。", "explanation": "句子颠倒了施受关系：“困扰”的主语应是让人烦恼的事，宾语是人；应表达“这个想法让他烦恼”。"}, {"text": "这个好消息困扰着他，他笑个不停。", "explanation": "句子说他笑个不停，应该用〈令人高兴〉之类的词；“困扰”指使人烦恼，与此矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aa0cdb8-5c9f-4351-9ef8-5b17def290c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95505, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "困扰", "is_correct": true, "explanation": "正确。牙疼使他长时间烦恼，符合句意。"}, {"text": "治疗", "is_correct": false, "explanation": "搭配：“治疗”的施事应是医生或药物，“牙疼”是病症，不能作主语治疗他。"}, {"text": "检查", "is_correct": false, "explanation": "语义：牙疼是症状，不能进行检查。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：牙疼不能感谢他人。"}], "explanations": {"困扰": "正确。牙疼使他长时间烦恼，符合句意。", "治疗": "搭配：“治疗”的施事应是医生或药物，“牙疼”是病症，不能作主语治疗他。", "检查": "语义：牙疼是症状，不能进行检查。", "感谢": "语义：牙疼不能感谢他人。"}, "sentence_index": 6, "correct_answer": "困扰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电话困扰了我的思路。", "explanation": "这里应该用〈打断〉。“打断”指中途使事情停止，“困扰”指使人心里烦恼，不表示中断。"}, {"text": "爸爸一直困扰着那辆旧自行车。", "explanation": "句子是说爸爸修理那辆自行车，应该用〈修理〉；“困扰”只能用于能感到烦恼的人。"}, {"text": "这个好玩的游戏困扰着孩子们很多年。", "explanation": "句子说游戏好玩，应该用〈吸引〉之类的词；“困扰”指使人烦恼，与“好玩”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aa0cdb8-5c9f-4351-9ef8-5b17def290c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95505, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个问题困扰我着好几天。", "corrected_sentence": "这个问题困扰着我好几天。", "error_description": "错误在目标词的“着”的位置。“着”应紧跟动词“困扰”，正确说法是“困扰着我好几天”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aa0cdb8-5c9f-4351-9ef8-5b17def290c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95505, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那次争吵困扰着了他一个月。", "corrected_sentence": "那次争吵困扰了他一个月。", "error_description": "错误在目标词的动态助词。“困扰”后不能同时带“着”和“了”，正确说法是“困扰了他一个月”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aa0cdb8-5c9f-4351-9ef8-5b17def290c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
