INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95506, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "使人处于难以摆脱的烦恼之中。", "primary_collocate": null, "pronunciation": "kùn rǎo", "ipa": "kʰuən˥˩ ɻaʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "失眠一直困扰着他。", "target_word": "困扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题困扰了我很久。", "target_word": "困扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "噪音困扰着住在附近的人。", "target_word": "困扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作压力困扰着很多年轻人。", "target_word": "困扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别让这些小事困扰你。", "target_word": "困扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的学习困扰着妈妈。", "target_word": "困扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "堵车每天都困扰着上班的人。", "target_word": "困扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病困扰了他十年。", "target_word": "困扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱的问题困扰着这个家。", "target_word": "困扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，不要让考试成绩困扰你。", "target_word": "困扰", "complexity_tier": "T3", "furigana": "lǎo shī shuō, bú yào ràng kǎo shì chéng jì kùn rǎo nǐ.", "sentence_source": "generated"}], "morphological_forms": [{"form": "困扰着", "label": "体标"}, {"form": "困扰了", "label": "体标"}, {"form": "困扰过", "label": "体标"}, {"form": "困擾", "label": "繁体"}], "register": "书面", "sense_fingerprint": "问题或烦恼使人难以摆脱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7e57d5e-0600-40a5-bf17-17abc02ebec0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95506, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "困扰", "is_correct": true, "explanation": "正确。“困扰”表示使人长期烦恼，与“失眠一直……着他”相合。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：失眠不能感谢他人。"}, {"text": "理解", "is_correct": false, "explanation": "语义：失眠是一种病症，不能理解人。"}, {"text": "帮助", "is_correct": false, "explanation": "搭配：“帮助”的施事应是能帮人的人或事物，“失眠”不能这样帮他。"}], "explanations": {"困扰": "正确。“困扰”表示使人长期烦恼，与“失眠一直……着他”相合。", "感谢": "语义：失眠不能感谢他人。", "理解": "语义：失眠是一种病症，不能理解人。", "帮助": "搭配：“帮助”的施事应是能帮人的人或事物，“失眠”不能这样帮他。"}, "sentence_index": 0, "correct_answer": "困扰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请不要困扰他的休息。", "explanation": "这里应该用〈打扰〉。“打扰”指妨碍别人休息或工作，“困扰”指使人心里烦恼，不用于妨碍休息。"}, {"text": "妈妈每天都困扰着洗衣机。", "explanation": "句子是在说妈妈照顾洗衣机，应该用〈照顾〉；“困扰”只能用于能感到烦恼的人。"}, {"text": "这份礼物一直困扰着她，她高兴得不得了。", "explanation": "句子后半说她高兴得不得了，应该用〈令人高兴〉之类表示喜悦的词；“困扰”指使人烦恼，与此矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aa0cdb8-5c9f-4351-9ef8-5b17def290c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95506, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "困扰", "is_correct": true, "explanation": "正确。“困扰”指堵车长期使上班的人烦恼，符合句意。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：堵车不会欢迎人。"}, {"text": "祝福", "is_correct": false, "explanation": "语义：堵车不能祝福他人。"}, {"text": "送", "is_correct": false, "explanation": "搭配：“送”的施事应是人或车辆，堵车不能送人。"}], "explanations": {"困扰": "正确。“困扰”指堵车长期使上班的人烦恼，符合句意。", "欢迎": "语义：堵车不会欢迎人。", "祝福": "语义：堵车不能祝福他人。", "送": "搭配：“送”的施事应是人或车辆，堵车不能送人。"}, "sentence_index": 6, "correct_answer": "困扰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份工作很轻松，一直困扰着她。", "explanation": "句子说工作很轻松，应该用〈令人舒心〉之类的词；“困扰”指使人烦恼，与此矛盾。"}, {"text": "这个笑话很有趣，一直困扰着大家。", "explanation": "句子说笑话很有趣，应该用〈逗乐〉之类的词；“困扰”指使人烦恼，与此矛盾。"}, {"text": "爸爸一直困扰着院子里的那棵树。", "explanation": "句子是说爸爸照料那棵树，应该用〈照料〉；“困扰”只能用于能感到烦恼的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aa0cdb8-5c9f-4351-9ef8-5b17def290c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95506, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事一直被困扰着我。", "corrected_sentence": "这件事一直困扰着我。", "error_description": "错误在“被”字句的施受关系：“困扰”的施事是“这件事”，受事是“我”。“被”字句须以受事作主语，所以应说“我一直被这件事困扰着”；直接说“这件事一直困扰着我”也可以。原句把施事“这件事”放在“被”前作主语，句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aa0cdb8-5c9f-4351-9ef8-5b17def290c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95506, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事困扰着了我一整天。", "corrected_sentence": "这件事困扰了我一整天。", "error_description": "错误在目标词的动态助词。“着”和“了”不能同时用在“困扰”后面，正确说法是“困扰了我一整天”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aa0cdb8-5c9f-4351-9ef8-5b17def290c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
