INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95507, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很高很大的石头房子，故事里国王住在里面。", "primary_collocate": null, "pronunciation": "chéng bǎo", "ipa": "ʈʂʰɤŋ˧˥ pɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "故事里的国王住在高高的城堡里。", "target_word": "城堡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座城堡又高又大，是石头做的。", "target_word": "城堡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小公主在城堡里等着王子。", "target_word": "城堡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们画了一座大城堡。", "target_word": "城堡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城堡的门很大，国王在里面吃饭。", "target_word": "城堡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里有一个漂亮的城堡。", "target_word": "城堡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王子骑着马来到了城堡前。", "target_word": "城堡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把城堡画在纸的中间。", "target_word": "城堡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老国王站在城堡的窗口看雪。", "target_word": "城堡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里的坏人把公主关在城堡里。", "target_word": "城堡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "古城堡", "label": "复合"}], "register": "中性", "sense_fingerprint": "故事里国王住的高大石头房子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0240c25c-1339-443c-bf73-9fd83a71d5f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95507, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "城堡", "is_correct": true, "explanation": "城堡：故事里国王住的高大石头房子，符合“高高的”和“国王住在里面”的语境。"}, {"text": "村庄", "is_correct": false, "explanation": "体貌：村庄是一片居民区，不能说“高高的”，与故事里高大的建筑不符。"}, {"text": "水井", "is_correct": false, "explanation": "语义：水井挖在地下，国王不会住在水井里。"}, {"text": "老窝", "is_correct": false, "explanation": "语域：“老窝”是口语，多指坏人或野兽的巢穴，与童话中国王的住所不合。"}], "explanations": {"城堡": "城堡：故事里国王住的高大石头房子，符合“高高的”和“国王住在里面”的语境。", "村庄": "体貌：村庄是一片居民区，不能说“高高的”，与故事里高大的建筑不符。", "水井": "语义：水井挖在地下，国王不会住在水井里。", "老窝": "语域：“老窝”是口语，多指坏人或野兽的巢穴，与童话中国王的住所不合。"}, "sentence_index": 0, "correct_answer": "城堡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每周去城堡存钱。", "explanation": "这里应该用〈银行〉。存钱要去银行；城堡是石头房子，不是金融机构。"}, {"text": "周日，村里的人去城堡做礼拜。", "explanation": "这里应该用〈教堂〉。做礼拜要去教堂；城堡是贵族的住所和防御建筑，不是礼拜场所。"}, {"text": "妈妈在城堡里买菜。", "explanation": "这里应该用〈超市〉。买菜要去超市或菜市场，城堡不是买东西的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95bade41-f44b-48bc-8fad-b923e7b51524') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95507, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "城堡", "is_correct": true, "explanation": "城堡：王子骑马来到的大型石头建筑，符合“来到了……前”的语境。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，王子骑马“来到厨房前”的句意说不通。"}, {"text": "鸟窝", "is_correct": false, "explanation": "语义：鸟窝是鸟住的地方，王子不会骑马来到鸟窝前。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是教室里的书写用具，王子骑马来到黑板前的句意说不通。"}], "explanations": {"城堡": "城堡：王子骑马来到的大型石头建筑，符合“来到了……前”的语境。", "厨房": "语义：厨房是做饭的地方，王子骑马“来到厨房前”的句意说不通。", "鸟窝": "语义：鸟窝是鸟住的地方，王子不会骑马来到鸟窝前。", "黑板": "语义：黑板是教室里的书写用具，王子骑马来到黑板前的句意说不通。"}, "sentence_index": 6, "correct_answer": "城堡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人在城堡里做衣服。", "explanation": "这里应该用〈工厂〉。做衣服的地方是工厂，城堡不是生产场所。"}, {"text": "医生在城堡里给病人看病。", "explanation": "这里应该用〈医院〉。看病要去医院，城堡不是医疗场所。"}, {"text": "旅客每天在城堡里等火车。", "explanation": "这里应该用〈车站〉。等火车要去车站；城堡不是交通场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95bade41-f44b-48bc-8fad-b923e7b51524') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95507, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山上有许多城堡们。", "corrected_sentence": "山上有许多城堡。", "error_description": "错误：“城堡们”。正确：“城堡”。“们”只加在指人的名词后面，城堡是物，不能加“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95bade41-f44b-48bc-8fad-b923e7b51524') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95507, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "河的前面有一条城堡。", "corrected_sentence": "河的前面有一座城堡。", "error_description": "错误：“一条城堡”量词用错。正确：“一座城堡”。“条”用于长条形的东西，城堡是大型建筑，应用“座”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95bade41-f44b-48bc-8fad-b923e7b51524') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
