INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95509, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "本地", "is_correct": true, "explanation": "“本地”与“外来”相对，指原本就在这里的，是反义词。"}, {"text": "迅速", "is_correct": false, "explanation": "“迅速”说速度快，与“外来”没有反义关系。"}, {"text": "雪白", "is_correct": false, "explanation": "“雪白”说颜色，与“外来”没有反义关系。"}, {"text": "笨重", "is_correct": false, "explanation": "“笨重”说体积或动作，与“外来”没有反义关系。"}], "correct_answer": "本地", "explanations": {"本地": "“本地”与“外来”相对，指原本就在这里的，是反义词。", "迅速": "“迅速”说速度快，与“外来”没有反义关系。", "雪白": "“雪白”说颜色，与“外来”没有反义关系。", "笨重": "“笨重”说体积或动作，与“外来”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b74e1261-5f5f-425d-9d1e-d585592b8400') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95509, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "本地", "is_correct": true, "explanation": "“本地”与“外来”相对，指原本就在这里的，是反义词。"}, {"text": "严肃", "is_correct": false, "explanation": "“严肃”说态度或气氛，与“外来”没有反义关系。"}, {"text": "清脆", "is_correct": false, "explanation": "“清脆”说声音，与“外来”没有反义关系。"}, {"text": "懒散", "is_correct": false, "explanation": "“懒散”说人的作风，与“外来”没有反义关系。"}], "correct_answer": "本地", "explanations": {"本地": "“本地”与“外来”相对，指原本就在这里的，是反义词。", "严肃": "“严肃”说态度或气氛，与“外来”没有反义关系。", "清脆": "“清脆”说声音，与“外来”没有反义关系。", "懒散": "“懒散”说人的作风，与“外来”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b74e1261-5f5f-425d-9d1e-d585592b8400') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95509, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不是本地的，是从别的地方来的。", "primary_collocate": null, "pronunciation": "wài lái", "ipa": "waɪ˥˩ laɪ˧˥", "syllable_count": 2, "sentences": [{"text": "外来的客人很多。", "target_word": "外来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这里有很多外来的人。", "target_word": "外来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他是外来的，不太懂这里的规矩。", "target_word": "外来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外来的游客都想尝尝当地菜。", "target_word": "外来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里来了几个外来的工人。", "target_word": "外来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外来的车不能进这个小区。", "target_word": "外来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们班的当地同学和外来的交换生关系很好。", "target_word": "外来", "complexity_tier": "T3", "furigana": "wǒ men bān de dāng dì tóng xué hé wài lái de jiāo huàn shēng guān xi hěn hǎo", "sentence_source": "generated"}, {"text": "这家店的客人大多是外来的。", "target_word": "外来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外来的学生要先住在学校里。", "target_word": "外来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城里有不少外来的打工者，他们来自农村。", "target_word": "外来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "外来人口", "label": "复合"}], "register": "中性", "sense_fingerprint": "不属于本地、从别处来的（人或事物）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6595b4a5-d1da-4ecc-9c20-7ed1df0b6017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95509, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外来", "is_correct": true, "explanation": "“外来”修饰“客人”，指从外地来的客人，与句意相符。"}, {"text": "透明", "is_correct": false, "explanation": "语义：客人是人，不能说“透明”。"}, {"text": "先进", "is_correct": false, "explanation": "搭配：“先进”多用于技术、方法、思想，不修饰“客人”。"}, {"text": "锋利", "is_correct": false, "explanation": "语义：“锋利”说的是刀具等物，不能用来形容客人。"}], "explanations": {"外来": "“外来”修饰“客人”，指从外地来的客人，与句意相符。", "透明": "语义：客人是人，不能说“透明”。", "先进": "搭配：“先进”多用于技术、方法、思想，不修饰“客人”。", "锋利": "语义：“锋利”说的是刀具等物，不能用来形容客人。"}, "sentence_index": 0, "correct_answer": "外来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在本地出生，是外来的。", "explanation": "这里应该用〈当地人〉，不用〈外来〉。在这里出生的人是当地人，不是从别处来的，不能用“外来”说自己。"}, {"text": "这位老北京是外来的。", "explanation": "这里应该用〈土生土长〉。老北京世代生活在北京，不是从外地来的，不能用“外来”形容。"}, {"text": "这些茶叶是我们村自己种的，是外来的。", "explanation": "这里应该用〈本地产的〉。外来指从别处来的，本村自己种的茶叶是本地产的，不能说是外来的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b74e1261-5f5f-425d-9d1e-d585592b8400') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95509, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外来", "is_correct": true, "explanation": "“外来”修饰“交换生”，指从别处来的学生，与前面的“当地同学”形成对照。"}, {"text": "本地", "is_correct": false, "explanation": "语义：与“当地同学”形成对照的应是从外地来的交换生，不能说“本地的交换生”。"}, {"text": "年迈", "is_correct": false, "explanation": "语义：交换生是年轻的学生，不能说“年迈”。"}, {"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”多形容水、眼睛等，不用来修饰人的身份。"}], "explanations": {"外来": "“外来”修饰“交换生”，指从别处来的学生，与前面的“当地同学”形成对照。", "本地": "语义：与“当地同学”形成对照的应是从外地来的交换生，不能说“本地的交换生”。", "年迈": "语义：交换生是年轻的学生，不能说“年迈”。", "清澈": "搭配：“清澈”多形容水、眼睛等，不用来修饰人的身份。"}, "sentence_index": 6, "correct_answer": "外来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市的居民祖祖辈辈都住在这里，都是外来的。", "explanation": "这里应该用〈土生土长〉。祖祖辈辈住在这里的居民是土生土长的，不是从别处来的，不能用“外来”。"}, {"text": "我的老同学和我一起长大，他是外来的。", "explanation": "这里应该用〈本地人〉。和我一起长大的同学是本地人，不是从别处来的。"}, {"text": "这条河的水是外来的，是从这里的山上流下来的。", "explanation": "这里应该用〈本地〉。外来指从别处来的，从本地山上流下来的水是本地的，不能说是外来的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b74e1261-5f5f-425d-9d1e-d585592b8400') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95509, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个朋友是外来。", "corrected_sentence": "这个朋友是外来的。", "error_description": "错误：“是外来”。正确：“是外来的”。“外来”作谓语时要在后面加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b74e1261-5f5f-425d-9d1e-d585592b8400') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95509, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些外来地打工者住在工地旁边。", "corrected_sentence": "这些外来的打工者住在工地旁边。", "error_description": "错误：“外来地打工者”。正确：“外来的打工者”。“外来”修饰名词时要用“的”，“地”用于修饰动词，不能修饰名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b74e1261-5f5f-425d-9d1e-d585592b8400') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
