INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95510, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "从外地或外国来的。", "primary_collocate": null, "pronunciation": "wài lái", "ipa": "waɪ˥˩ laɪ˧˥", "syllable_count": 2, "sentences": [{"text": "汉语里有很多外来的词。", "target_word": "外来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这种鱼是外来的物种。", "target_word": "外来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "外来的文化丰富了我们的生活。", "target_word": "外来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "“沙发”是一个外来的词。", "target_word": "外来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "外来的物种可能会伤害本地的鱼。", "target_word": "外来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对外来的新技术很感兴趣。", "target_word": "外来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有些外来的食品在中国很受欢迎。", "target_word": "外来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司引进了外来的先进设备。", "target_word": "外来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外来的音乐影响了很多年轻人。", "target_word": "外来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些外来的植物是从国外带进来的。", "target_word": "外来", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "外来词", "label": "复合"}], "register": "中性", "sense_fingerprint": "从外国或外地传入的（词语、物种、文化等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6595b4a5-d1da-4ecc-9c20-7ed1df0b6017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95510, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外来", "is_correct": true, "explanation": "“外来”修饰“词”，指从外国引入的词，与句意相符。"}, {"text": "冷冻", "is_correct": false, "explanation": "语义：词语不能冷冻，句意说不通。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：词语不能潮湿，句意说不通。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”多形容人或建筑，不修饰“词”。"}], "explanations": {"外来": "“外来”修饰“词”，指从外国引入的词，与句意相符。", "冷冻": "语义：词语不能冷冻，句意说不通。", "潮湿": "语义：词语不能潮湿，句意说不通。", "高大": "搭配：“高大”多形容人或建筑，不修饰“词”。"}, "sentence_index": 0, "correct_answer": "外来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我自己创造的这个新词是外来的。", "explanation": "这里应该用〈本土的〉。外来指从外国或外地传入的，自己创造的新词是本土产生的，不能说是外来的。"}, {"text": "这首民歌是我们村祖祖辈辈传下来的，是外来的。", "explanation": "这里应该用〈本土〉。村里世代流传的民歌是本土的，不能说是外来的。"}, {"text": "这种瓷器是我们景德镇的老师傅亲手烧的，是外来的。", "explanation": "这里应该用〈本地〉。景德镇老师傅烧的瓷器是本地的，不能说是外来的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b74e1261-5f5f-425d-9d1e-d585592b8400') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95510, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外来", "is_correct": true, "explanation": "“外来”修饰“食品”，指从国外引入的食品，与句意相符。"}, {"text": "懒惰", "is_correct": false, "explanation": "语义：食品不能懒惰，句意说不通。"}, {"text": "孤独", "is_correct": false, "explanation": "语义：食品不能孤独，句意说不通。"}, {"text": "粗壮", "is_correct": false, "explanation": "搭配：“粗壮”多形容人、动物的身体，不修饰“食品”。"}], "explanations": {"外来": "“外来”修饰“食品”，指从国外引入的食品，与句意相符。", "懒惰": "语义：食品不能懒惰，句意说不通。", "孤独": "语义：食品不能孤独，句意说不通。", "粗壮": "搭配：“粗壮”多形容人、动物的身体，不修饰“食品”。"}, "sentence_index": 6, "correct_answer": "外来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些植物是我们村里自己培育的，是外来的。", "explanation": "这里应该用〈本地〉。外来指从别处传入的，村里自己培育的植物是本地的，不能说是外来的。"}, {"text": "这座石桥是我们村的石匠建的，是外来的。", "explanation": "这里应该用〈本土〉。村里石匠建的石桥是本土的，不能说是外来的。"}, {"text": "这些食品是我们当地人天天做的，是外来的。", "explanation": "这里应该用〈传统〉。当地人天天做的食品是本地传统的，不能说是外来的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b74e1261-5f5f-425d-9d1e-d585592b8400') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95510, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种花是外来。", "corrected_sentence": "这种花是外来的。", "error_description": "错误：“是外来”。正确：“是外来的”。“外来”作谓语时要在后面加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b74e1261-5f5f-425d-9d1e-d585592b8400') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95510, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些外来地食品很受欢迎。", "corrected_sentence": "这些外来的食品很受欢迎。", "error_description": "错误：“外来地食品”。正确：“外来的食品”。“外来”修饰名词时要用“的”，不能用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b74e1261-5f5f-425d-9d1e-d585592b8400') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95513, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "细心", "is_correct": true, "explanation": "细心：与“大条”（做事粗心）是反义关系。"}, {"text": "慷慨", "is_correct": false, "explanation": "慷慨指大方、不吝啬，与“大条”的粗心义没有反义关系。"}, {"text": "冷静", "is_correct": false, "explanation": "冷静指沉着、不慌乱，与“大条”的粗心义没有反义关系。"}, {"text": "低调", "is_correct": false, "explanation": "低调指不张扬，与“大条”的粗心义没有反义关系。"}], "correct_answer": "细心", "explanations": {"细心": "细心：与“大条”（做事粗心）是反义关系。", "慷慨": "慷慨指大方、不吝啬，与“大条”的粗心义没有反义关系。", "冷静": "冷静指沉着、不慌乱，与“大条”的粗心义没有反义关系。", "低调": "低调指不张扬，与“大条”的粗心义没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95bade41-f44b-48bc-8fad-b923e7b51524') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95513, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "细心", "is_correct": true, "explanation": "细心：与“大条”（做事粗心）是反义关系。"}, {"text": "热情", "is_correct": false, "explanation": "热情指待人亲切、积极主动，与“大条”没有反义关系。"}, {"text": "凶狠", "is_correct": false, "explanation": "凶狠指残暴、狠毒，与“大条”没有反义关系。"}, {"text": "悠闲", "is_correct": false, "explanation": "悠闲指不紧不慢、清闲自在，与“大条”没有反义关系。"}], "correct_answer": "细心", "explanations": {"细心": "细心：与“大条”（做事粗心）是反义关系。", "热情": "热情指待人亲切、积极主动，与“大条”没有反义关系。", "凶狠": "凶狠指残暴、狠毒，与“大条”没有反义关系。", "悠闲": "悠闲指不紧不慢、清闲自在，与“大条”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95bade41-f44b-48bc-8fad-b923e7b51524') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95513, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "做事不太小心，不爱想细小的事。", "primary_collocate": null, "pronunciation": "dà tiáo", "ipa": "ta˥˩ tʰiɑʊ˧˥", "syllable_count": 2, "sentences": [{"text": "他做事太大条，常常忘了关门。", "target_word": "大条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别这么大条，出门要带钥匙。", "target_word": "大条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她有点大条，把手机丢在了车上。", "target_word": "大条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥很大条，考试时漏看了一页。", "target_word": "大条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做事不能太大条，要多检查。", "target_word": "大条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他大条得连自己的生日都忘了。", "target_word": "大条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王太大条了，把重要文件放错了地方。", "target_word": "大条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大条的人容易丢三落四。", "target_word": "大条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怎么这么大条，又把水杯忘在教室了？", "target_word": "大条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说我太大条，写字总是漏笔画。", "target_word": "大条", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "神经大条", "label": "复合"}], "register": "口语", "sense_fingerprint": "做事粗心不注意小事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0240c25c-1339-443c-bf73-9fd83a71d5f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95513, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大条", "is_correct": true, "explanation": "大条：做事粗心、不爱想细小的事，与“常常忘了关门”相符。"}, {"text": "细心", "is_correct": false, "explanation": "语义：“细心”与“常常忘了关门”语义相反，不合句意。"}, {"text": "严谨", "is_correct": false, "explanation": "语域：“严谨”偏书面语，且与“常常忘了关门”矛盾。"}, {"text": "周到", "is_correct": false, "explanation": "语义：“周到”指照顾得全面，与“常常忘了关门”不符。"}], "explanations": {"大条": "大条：做事粗心、不爱想细小的事，与“常常忘了关门”相符。", "细心": "语义：“细心”与“常常忘了关门”语义相反，不合句意。", "严谨": "语域：“严谨”偏书面语，且与“常常忘了关门”矛盾。", "周到": "语义：“周到”指照顾得全面，与“常常忘了关门”不符。"}, "sentence_index": 0, "correct_answer": "大条"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条河很大条，我们游不过去。", "explanation": "这里应该用〈湍急〉。大条说人做事粗心，不能用来形容河水的流速和水势。"}, {"text": "这把椅子很大条，坐上去总是晃。", "explanation": "这里应该用〈结实〉。大条只说人做事粗心，不能用来形容椅子是否牢固。"}, {"text": "这张桌子很大条，搬进房间时总是卡住。", "explanation": "这里应该用〈笨重〉。大条只说人做事粗心，不能用来形容桌子的体积和重量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95bade41-f44b-48bc-8fad-b923e7b51524') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95513, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大条", "is_correct": true, "explanation": "大条：做事粗心，与“把重要文件放错了地方”相符。"}, {"text": "高", "is_correct": false, "explanation": "体貌：“高”指身材，不用来形容做事态度，句子不通。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”多形容眼睛、灯光，不用于形容人做事的态度。"}, {"text": "谨慎", "is_correct": false, "explanation": "语义：“谨慎”与“把重要文件放错了地方”相矛盾。"}], "explanations": {"大条": "大条：做事粗心，与“把重要文件放错了地方”相符。", "高": "体貌：“高”指身材，不用来形容做事态度，句子不通。", "明亮": "搭配：“明亮”多形容眼睛、灯光，不用于形容人做事的态度。", "谨慎": "语义：“谨慎”与“把重要文件放错了地方”相矛盾。"}, "sentence_index": 6, "correct_answer": "大条"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块木板的表面很大条，需要再打磨。", "explanation": "这里应该用〈粗糙〉。大条形容人做事粗心，不用来形容木板的表面。"}, {"text": "这把剪刀太大条了，剪不断细线。", "explanation": "这里应该用〈锋利〉。大条形容人做事粗心，不能用来形容剪刀的刀刃；剪不断细线是因为刀刃不够锋利。"}, {"text": "这盏台灯很大条，光线忽明忽暗。", "explanation": "这里应该用〈稳定〉。大条只形容人做事粗心，不能用来形容台灯的光线是否稳定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95bade41-f44b-48bc-8fad-b923e7b51524') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95513, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个学生大条的连作业都忘了带。", "corrected_sentence": "这个学生大条得连作业都忘了带。", "error_description": "“大条”后面作补语要用“得”，应说“大条得……”，不能用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95bade41-f44b-48bc-8fad-b923e7b51524') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95513, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈说我比哥哥很大条，写字常漏笔画。", "corrected_sentence": "妈妈说我比哥哥大条，写字常漏笔画。", "error_description": "比字句中形容词前不能再加“很”，应说“比哥哥大条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95bade41-f44b-48bc-8fad-b923e7b51524') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
