INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95516, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca8f4407-400e-4cf6-bded-765ee8a5e6c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95516, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "从地下开采出来的可燃气体，主要成分是甲烷。", "primary_collocate": null, "pronunciation": "tiān rán qì", "ipa": "tʰjɛn˥ ʐan˧˥ tɕʰi˥˩", "syllable_count": 3, "sentences": [{"text": "这个国家出口大量天然气。", "target_word": "天然气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人在海边开采天然气。", "target_word": "天然气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天然气的主要成分是甲烷。", "target_word": "天然气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天的时候，天然气的需求量大增。", "target_word": "天然气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司专门卖天然气和石油。", "target_word": "天然气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天然气是一种清洁的能源。", "target_word": "天然气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年天然气的价格涨了不少。", "target_word": "天然气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多工厂用天然气发电。", "target_word": "天然气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家在海底发现了新的天然气。", "target_word": "天然气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天然气从地下运到城市里。", "target_word": "天然气", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "天然氣", "label": "繁体"}, {"form": "天然气管道", "label": "复合"}], "register": "中性", "sense_fingerprint": "作为能源开采、出口的可燃气体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af1f0b90-466a-4ce3-a330-0972cf8aba73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95516, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天然气", "is_correct": true, "explanation": "正确：天然气是可以大量出口的能源商品，与“出口大量”搭配。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是可以出口的货物。"}, {"text": "历史", "is_correct": false, "explanation": "搭配：“出口大量”搭配的是货物，不能说“出口历史”。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨不是货物，不能说“出口大量雨”。"}], "explanations": {"天然气": "正确：天然气是可以大量出口的能源商品，与“出口大量”搭配。", "空气": "语义：空气不是可以出口的货物。", "历史": "搭配：“出口大量”搭配的是货物，不能说“出口历史”。", "雨": "语义：雨不是货物，不能说“出口大量雨”。"}, "sentence_index": 0, "correct_answer": "天然气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他深吸一口天然气，觉得很清爽。", "explanation": "这里应该用〈空气〉。“深吸一口”用于空气，天然气是燃料，不能吸入。"}, {"text": "这个国家出口了三颗天然气。", "explanation": "量词错误：〈颗〉用于粒状的东西，天然气是气体，应用〈股〉。"}, {"text": "工人在海边种天然气。", "explanation": "搭配错误：天然气是从地下开采出来的，不能“种”，应说「开采天然气」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca8f4407-400e-4cf6-bded-765ee8a5e6c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95516, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天然气", "is_correct": true, "explanation": "正确：天然气是有价格的能源商品，“价格涨了”说得通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄是人的岁数，不是商品，没有价格可言。"}, {"text": "友谊", "is_correct": false, "explanation": "搭配：“价格”用于可以买卖的东西，不能说友谊的价格。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是商品，没有价格。"}], "explanations": {"天然气": "正确：天然气是有价格的能源商品，“价格涨了”说得通。", "年龄": "语义：年龄是人的岁数，不是商品，没有价格可言。", "友谊": "搭配：“价格”用于可以买卖的东西，不能说友谊的价格。", "天空": "语义：天空不是商品，没有价格。"}, "sentence_index": 6, "correct_answer": "天然气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天天然气很好，我们去海边吧。", "explanation": "这里应该用〈天气〉。天气用来描述晴雨冷暖，天然气是燃料，不能形容天气好坏。"}, {"text": "我们在天然气里住了三天。", "explanation": "用法错误：天然气是能源，不是居住的地方，这里把燃料当成了场所。"}, {"text": "这个孩子把天然气当成了玩具。", "explanation": "这里把天然气当成了可以玩耍的东西。天然气是可燃的燃料，不是玩具，“当成玩具”只适用于可以拿在手里玩的物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca8f4407-400e-4cf6-bded-765ee8a5e6c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95516, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条天然气运到了港口。", "corrected_sentence": "这股天然气运到了港口。", "error_description": "量词错误：天然气是气体，应用“股”；“条”用于细长的物品，不能修饰气体。正确形式为“这股天然气”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca8f4407-400e-4cf6-bded-765ee8a5e6c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95516, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些天然气的来自海底。", "corrected_sentence": "这些天然气来自海底。", "error_description": "“的”多余：“天然气”后直接接动词“来自”，不能加“的”。正确形式为“这些天然气来自海底”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca8f4407-400e-4cf6-bded-765ee8a5e6c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
