INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95518, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "好的评价。", "primary_collocate": null, "pronunciation": "hǎo píng", "ipa": "xau˨˩ pʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "吃完饭，我给这家店写了好评。", "target_word": "好评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "收到货以后，请给我们好评。", "target_word": "好评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买家给了这件衣服一个好评。", "target_word": "好评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板很高兴，因为他收到了好评。", "target_word": "好评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务好的店，常常能得到顾客的好评。", "target_word": "好评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了得到好评，他对客人特别热情。", "target_word": "好评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的作业得到了老师的好评。", "target_word": "好评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你满意的话，可以给我一个好评吗？", "target_word": "好评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个司机服务很好，乘客都给他好评。", "target_word": "好评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天回复客人，慢慢有了好评。", "target_word": "好评", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "好評", "label": "繁体"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "别人给出的正面评价，如网购后给商家的好评", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3d50c0-7076-42e3-ba24-63a14507b06f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95518, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "好评", "is_correct": true, "explanation": "正确。“写”后接“好评”，指给店家写正面的评价。"}, {"text": "脚印", "is_correct": false, "explanation": "语义：“写”的对象是文字，脚印不能被写。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：“写”的对象是文字，鞋子不能被写。"}, {"text": "饭菜", "is_correct": false, "explanation": "搭配：“写”不跟“饭菜”搭配，写的是评价或文字。"}], "explanations": {"好评": "正确。“写”后接“好评”，指给店家写正面的评价。", "脚印": "语义：“写”的对象是文字，脚印不能被写。", "鞋子": "语义：“写”的对象是文字，鞋子不能被写。", "饭菜": "搭配：“写”不跟“饭菜”搭配，写的是评价或文字。"}, "sentence_index": 0, "correct_answer": "好评"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他给这家店写了一本好评。", "explanation": "这里应该用〈个〉或〈条〉。“好评”的量词可用“个”或“条”，“本”用于书籍，这里不合适。"}, {"text": "他是班里的好评。", "explanation": "这里应该用〈好学生〉。“好评”指对作品或服务的正面评价，不指人，“班里的……”应说〈好学生〉。"}, {"text": "他想出了一个好评。", "explanation": "这里应该用〈主意〉。“好评”是对事物的正面评价，不能和“想出”搭配，应说“想出一个好主意”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da9a4a8f-2144-400a-ab0c-e78d3e6ac6ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95518, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好评", "is_correct": true, "explanation": "正确。“得到”后接“好评”，指作业得到老师的正面评价。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：“得到”后接的是评价、奖励一类的东西，“眼镜”不是这样的对象。"}, {"text": "凳子", "is_correct": false, "explanation": "语义：“得到”的是评价一类的东西，凳子不是这样的对象。"}, {"text": "墨水", "is_correct": false, "explanation": "搭配：“得到”后接“评价、奖励”，不接“墨水”。"}], "explanations": {"好评": "正确。“得到”后接“好评”，指作业得到老师的正面评价。", "眼镜": "语义：“得到”后接的是评价、奖励一类的东西，“眼镜”不是这样的对象。", "凳子": "语义：“得到”的是评价一类的东西，凳子不是这样的对象。", "墨水": "搭配：“得到”后接“评价、奖励”，不接“墨水”。"}, "sentence_index": 6, "correct_answer": "好评"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他饿了，就吃了一个好评。", "explanation": "这里应该用〈面包〉。“好评”是对事物的评价，不能吃，“吃”的对象应是食物，如〈面包〉。"}, {"text": "她的画是一个好评。", "explanation": "这里应该用〈画〉。“好评”是对作品的评价，不是作品本身，“她的画”应说〈画〉。"}, {"text": "他的好评是一只小猫。", "explanation": "这里应该用〈宠物〉。“好评”是评价，不是动物，“是一只小猫”应说〈宠物〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da9a4a8f-2144-400a-ab0c-e78d3e6ac6ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95518, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "吃完饭，我给这家店写了一张好评。", "corrected_sentence": "吃完饭，我给这家店写了一个好评。", "error_description": "量词错误：“好评”的量词可用“个”或“条”，这里误用“张”。应说“一个好评”或“一条好评”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da9a4a8f-2144-400a-ab0c-e78d3e6ac6ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95518, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他曾经得到顾客的好评过。", "corrected_sentence": "他曾经得到顾客的好评。", "error_description": "体标错误：“好评”后不能加“过”，应去掉“过”，说“他曾经得到顾客的好评”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da9a4a8f-2144-400a-ab0c-e78d3e6ac6ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
