INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95519, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "妈妈。", "primary_collocate": null, "pronunciation": "niáng", "ipa": "njɑŋ˧˥", "syllable_count": 1, "sentences": [{"text": "我娘做的面条特别好吃。", "target_word": "娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "娘，我回来了，今天饿坏了。", "target_word": "娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他娘每天早上都起得很早。", "target_word": "娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候，娘常给我讲故事。", "target_word": "娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给娘买了一件新衣服。", "target_word": "娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "娘在厨房里做饭，我在旁边帮忙。", "target_word": "娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "娘说，出门要多穿点衣服。", "target_word": "娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很听娘的话，从来不惹事。", "target_word": "娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想娘了，今晚给她打个电话。", "target_word": "娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年了，我要回家看娘。", "target_word": "娘", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "爹娘", "label": "复合"}, {"form": "娘家", "label": "复合"}], "register": "口语", "sense_fingerprint": "口语里对妈妈的称呼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59499d32-9057-46d0-9d86-6bb1baf6c73a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95519, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "娘", "is_correct": true, "explanation": "正确答案。娘（niáng）指妈妈。"}, {"text": "年", "is_correct": false, "explanation": "年（nián）与 niáng 的韵母不同（an 与 ang），意思是年份。"}, {"text": "狼", "is_correct": false, "explanation": "狼（láng）与 niáng 的声母不同（l 与 n），意思是狼。"}, {"text": "凉", "is_correct": false, "explanation": "凉（liáng）与 niáng 的声母不同（l 与 n），意思是凉。"}], "explanations": {"娘": "正确答案。娘（niáng）指妈妈。", "年": "年（nián）与 niáng 的韵母不同（an 与 ang），意思是年份。", "狼": "狼（láng）与 niáng 的声母不同（l 与 n），意思是狼。", "凉": "凉（liáng）与 niáng 的声母不同（l 与 n），意思是凉。"}, "sentence_index": null, "correct_answer": "娘"}, "level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会做面条，“我桌子做的面条”句意不通。"}, {"text": "娘", "is_correct": true, "explanation": "正确答案。“娘”指妈妈，能做饭，与“做的面条”相合。"}, {"text": "令堂", "is_correct": false, "explanation": "语域：“令堂”是敬称别人母亲的书面词，不能用来称自己的母亲。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫不会做面条，“我猫做的面条”句意不通。"}], "explanations": {"桌子": "语义：桌子不会做面条，“我桌子做的面条”句意不通。", "娘": "正确答案。“娘”指妈妈，能做饭，与“做的面条”相合。", "令堂": "语域：“令堂”是敬称别人母亲的书面词，不能用来称自己的母亲。", "猫": "语义：猫不会做面条，“我猫做的面条”句意不通。"}, "sentence_index": 0, "correct_answer": "娘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春节我们回娘看爷爷奶奶。", "explanation": "这里应该用〈娘家〉。“回娘家”指回到出嫁前的家，“娘”单用不能表示地点。"}, {"text": "我家那只娘，每天早上都起得很早。", "explanation": "这里应该用〈个〉或〈位〉。“只”多用于动物，不用来数人。"}, {"text": "这家商店的娘今天不营业。", "explanation": "这里应该用〈店主〉或〈老板〉。“娘”只指母亲，不能指商店或店主，这里句意不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01bbc7a5-90cb-4a54-b92b-a1bb5793a932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95519, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "娘", "is_correct": true, "explanation": "正确答案。娘（niáng）指妈妈。"}, {"text": "酿", "is_correct": false, "explanation": "酿（niàng）与 niáng 的声调不同（第四声与第二声），意思是酿造。"}, {"text": "郎", "is_correct": false, "explanation": "郎（láng）与 niáng 的声母不同（l 与 n），意思是男子或丈夫。"}, {"text": "粮", "is_correct": false, "explanation": "粮（liáng）与 niáng 的声母不同（l 与 n），意思是粮食。"}], "explanations": {"娘": "正确答案。娘（niáng）指妈妈。", "酿": "酿（niàng）与 niáng 的声调不同（第四声与第二声），意思是酿造。", "郎": "郎（láng）与 niáng 的声母不同（l 与 n），意思是男子或丈夫。", "粮": "粮（liáng）与 niáng 的声母不同（l 与 n），意思是粮食。"}, "sentence_index": null, "correct_answer": "娘"}, "level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "配价：“说”要求能说话的施事，“冰箱”不能充当说话的主语。"}, {"text": "娘", "is_correct": true, "explanation": "正确答案。“娘”指妈妈，能对孩子说这样的叮嘱话。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“书包”不能作“说”的施事，“书包说”搭配不当。"}, {"text": "闹钟", "is_correct": false, "explanation": "搭配：闹钟不会说这样的叮嘱，“闹钟说”与句意冲突。"}], "explanations": {"冰箱": "配价：“说”要求能说话的施事，“冰箱”不能充当说话的主语。", "娘": "正确答案。“娘”指妈妈，能对孩子说这样的叮嘱话。", "书包": "搭配：“书包”不能作“说”的施事，“书包说”搭配不当。", "闹钟": "搭配：闹钟不会说这样的叮嘱，“闹钟说”与句意冲突。"}, "sentence_index": 6, "correct_answer": "娘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "婚礼上，娘穿着红色的礼服，笑得很甜。", "explanation": "这里应该用〈新娘〉。“娘”单用只指母亲，不指刚结婚的女子。"}, {"text": "门口站着一把娘，她在等我。", "explanation": "这里应该用〈位〉或〈个〉。“把”用于有柄的器具，不用来数人。"}, {"text": "这台电脑的娘坏了，需要修理。", "explanation": "这里应该用〈主板〉。“娘”只指母亲，不能指电脑的部件，这里应说“主板”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01bbc7a5-90cb-4a54-b92b-a1bb5793a932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95519, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家有一只好娘，她每天天不亮就起来做饭。", "corrected_sentence": "我家有一个好娘，她每天天不亮就起来做饭。", "error_description": "“娘”指人，量词应用“个”（或“位”）。“只”多用于动物，不能用来数人。应改为“一个好娘”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01bbc7a5-90cb-4a54-b92b-a1bb5793a932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95519, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是我娘照片，她年轻时很漂亮。", "corrected_sentence": "这是我娘的照片，她年轻时很漂亮。", "error_description": "“娘”修饰“照片”时要加结构助词“的”，应说“我娘的照片”，不能说“我娘照片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01bbc7a5-90cb-4a54-b92b-a1bb5793a932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
