INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95520, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "母亲。", "primary_collocate": null, "pronunciation": "niáng", "ipa": "njɑŋ˧˥", "syllable_count": 1, "sentences": [{"text": "他娘是个很能干的农村妇女。", "target_word": "娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "娘的头发白了，眼睛也不好了。", "target_word": "娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "儿子走了很远，心里总想着娘。", "target_word": "娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "娘一个人把我们三个孩子养大了。", "target_word": "娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把挣来的钱全交给了娘。", "target_word": "娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "娘站在门口，看着我走远。", "target_word": "娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是娘留给我的一只旧碗。", "target_word": "娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子哭了，娘赶快抱起他。", "target_word": "娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我娘没读过书，可她懂很多道理。", "target_word": "娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每到冬天，娘都给我们做新鞋。", "target_word": "娘", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "爹娘", "label": "复合"}, {"form": "娘家", "label": "复合"}], "register": "口语", "sense_fingerprint": "口语里指生养自己的母亲", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59499d32-9057-46d0-9d86-6bb1baf6c73a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95520, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "娘", "is_correct": true, "explanation": "正确答案。娘（niáng）指母亲。"}, {"text": "年", "is_correct": false, "explanation": "年（nián）与 niáng 的韵母不同（an 与 ang），意思是年份。"}, {"text": "郎", "is_correct": false, "explanation": "郎（láng）与 niáng 的声母不同（l 与 n），意思是男子或丈夫。"}, {"text": "良", "is_correct": false, "explanation": "良（liáng）与 niáng 的声母不同（l 与 n），意思是好。"}], "explanations": {"娘": "正确答案。娘（niáng）指母亲。", "年": "年（nián）与 niáng 的韵母不同（an 与 ang），意思是年份。", "郎": "郎（láng）与 niáng 的声母不同（l 与 n），意思是男子或丈夫。", "良": "良（liáng）与 niáng 的声母不同（l 与 n），意思是好。"}, "sentence_index": null, "correct_answer": "娘"}, "level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：桌子不是人，不能作“是个很能干的农村妇女”的主语。"}, {"text": "娘", "is_correct": true, "explanation": "正确答案。“娘”指母亲，与“是个很能干的农村妇女”相合。"}, {"text": "家母", "is_correct": false, "explanation": "语域：“家母”是谦称自己母亲的书面词，不能用来称“他”的母亲。"}, {"text": "水杯", "is_correct": false, "explanation": "语义：水杯不是人，句中“水杯是个妇女”无法成立。"}], "explanations": {"桌子": "语义：桌子不是人，不能作“是个很能干的农村妇女”的主语。", "娘": "正确答案。“娘”指母亲，与“是个很能干的农村妇女”相合。", "家母": "语域：“家母”是谦称自己母亲的书面词，不能用来称“他”的母亲。", "水杯": "语义：水杯不是人，句中“水杯是个妇女”无法成立。"}, "sentence_index": 0, "correct_answer": "娘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "婚礼那天，娘穿着红色的礼服，笑得很甜。", "explanation": "这里应该用〈新娘〉。“娘”单用只指母亲，不指刚结婚的女子。"}, {"text": "我们村那只娘特别能干，做饭又快又好。", "explanation": "这里应该用〈位〉或〈个〉。“只”多用于动物，不用来数人。"}, {"text": "这家工厂的娘每天都很忙。", "explanation": "这里应该用〈厂长〉。“娘”只指母亲，不能用来指工厂的负责人，这里句意不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01bbc7a5-90cb-4a54-b92b-a1bb5793a932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95520, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "娘", "is_correct": true, "explanation": "正确答案。娘（niáng）指母亲。"}, {"text": "酿", "is_correct": false, "explanation": "酿（niàng）与 niáng 的声调不同（第四声与第二声），意思是酿造。"}, {"text": "狼", "is_correct": false, "explanation": "狼（láng）与 niáng 的声母不同（l 与 n），意思是狼。"}, {"text": "粮", "is_correct": false, "explanation": "粮（liáng）与 niáng 的声母不同（l 与 n），意思是粮食。"}], "explanations": {"娘": "正确答案。娘（niáng）指母亲。", "酿": "酿（niàng）与 niáng 的声调不同（第四声与第二声），意思是酿造。", "狼": "狼（láng）与 niáng 的声母不同（l 与 n），意思是狼。", "粮": "粮（liáng）与 niáng 的声母不同（l 与 n），意思是粮食。"}, "sentence_index": null, "correct_answer": "娘"}, "level_3": {"options": [{"text": "窗户", "is_correct": false, "explanation": "配价：“留给我”要求能给予东西的施事，“窗户”不能作施事。"}, {"text": "娘", "is_correct": true, "explanation": "正确答案。“娘”指母亲，能把旧碗留给孩子。"}, {"text": "冬天", "is_correct": false, "explanation": "配价：“冬天”不能把东西留给别人，与“留给我”的施事不符。"}, {"text": "眼镜", "is_correct": false, "explanation": "搭配：“留给我”一般以人为施事，“眼镜”与“留给”搭配不当。"}], "explanations": {"窗户": "配价：“留给我”要求能给予东西的施事，“窗户”不能作施事。", "娘": "正确答案。“娘”指母亲，能把旧碗留给孩子。", "冬天": "配价：“冬天”不能把东西留给别人，与“留给我”的施事不符。", "眼镜": "搭配：“留给我”一般以人为施事，“眼镜”与“留给”搭配不当。"}, "sentence_index": 6, "correct_answer": "娘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周末我想回娘看看老朋友。", "explanation": "这里应该用〈娘家〉。“回娘家”指回到出嫁前的家，“娘”单用不表示地点。"}, {"text": "街上走来一块娘，她很和气。", "explanation": "这里应该用〈位〉或〈个〉。“块”用于片状或块状的东西，不用来数人。"}, {"text": "这个方案的娘还不完整，需要再修改。", "explanation": "这里应该用〈原稿〉或〈草案〉。“娘”只指母亲，不能指方案，这里句意不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01bbc7a5-90cb-4a54-b92b-a1bb5793a932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95520, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我有一只好娘，她从小教我做人。", "corrected_sentence": "我有一位好娘，她从小教我做人。", "error_description": "“娘”指人，量词应用“位”（或“个”）。“只”多用于动物，不能用来数人。应改为“一位好娘”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01bbc7a5-90cb-4a54-b92b-a1bb5793a932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95520, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把娘旧照片收好了，那是她年轻时的样子。", "corrected_sentence": "我把娘的旧照片收好了，那是她年轻时的样子。", "error_description": "“娘”修饰“旧照片”时要加“的”，应说“娘的旧照片”，不能说“娘旧照片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01bbc7a5-90cb-4a54-b92b-a1bb5793a932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
