INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95521, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "放在银行里的钱。", "primary_collocate": null, "pronunciation": "cún kuǎn", "ipa": "tsʰwən˧˥ kʰwan˨˩˦", "syllable_count": 2, "sentences": [{"text": "他在银行的存款不多。", "target_word": "存款", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我把存款放在银行里。", "target_word": "存款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月我的存款又多了。", "target_word": "存款", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她每个月都往银行存钱，存款越来越多。", "target_word": "存款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用存款买了一套房子。", "target_word": "存款", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "银行的存款有利息。", "target_word": "存款", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想看看卡里还有多少存款。", "target_word": "存款", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷的存款是为了养老用的。", "target_word": "存款", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她没有存款，所以不敢辞职。", "target_word": "存款", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他花光了所有的存款，还是没买到。", "target_word": "存款", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "笔", "label": "量词"}, {"form": "银行存款", "label": "复合"}], "register": "中性", "sense_fingerprint": "个人存放在银行里的钱，指积蓄", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6595b4a5-d1da-4ecc-9c20-7ed1df0b6017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95521, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "存款", "is_correct": true, "explanation": "“存款”指存在银行里的钱，“他在银行的存款不多”句意通顺。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油不能存放在银行里，句意说不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不能存放在银行里，句意说不通。"}, {"text": "早饭", "is_correct": false, "explanation": "搭配：“早饭”不能说“银行的早饭”，搭配不当。"}], "explanations": {"存款": "“存款”指存在银行里的钱，“他在银行的存款不多”句意通顺。", "汽油": "语义：汽油不能存放在银行里，句意说不通。", "年龄": "语义：年龄不能存放在银行里，句意说不通。", "早饭": "搭配：“早饭”不能说“银行的早饭”，搭配不当。"}, "sentence_index": 0, "correct_answer": "存款"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的一只存款不多。", "explanation": "这里应该用〈笔〉。存款的量词是“笔”，说“一笔存款”，不能说“一只”。"}, {"text": "他每个月都把存款存进了抽屉。", "explanation": "这里应该用〈现金〉。存款在银行里，不能存进抽屉，存进抽屉的应是现金。"}, {"text": "他租房子时交了一笔存款。", "explanation": "这里应该用〈押金〉。押金是租房时交给房东的钱，存款是存在银行里的钱，不能说交存款。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b74e1261-5f5f-425d-9d1e-d585592b8400') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95521, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "存款", "is_correct": true, "explanation": "“存款”指卡里的钱，与“多少”搭配，句意通顺。"}, {"text": "温度", "is_correct": false, "explanation": "语义：卡里不能有温度，句意说不通。"}, {"text": "笑容", "is_correct": false, "explanation": "语义：卡里不能有笑容，句意说不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“多少”问的是钱的数量，“体重”不能这样计量或存放在卡里。"}], "explanations": {"存款": "“存款”指卡里的钱，与“多少”搭配，句意通顺。", "温度": "语义：卡里不能有温度，句意说不通。", "笑容": "语义：卡里不能有笑容，句意说不通。", "体重": "搭配：“多少”问的是钱的数量，“体重”不能这样计量或存放在卡里。"}, "sentence_index": 6, "correct_answer": "存款"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他还清了所有的存款，还是没买到。", "explanation": "这里不这么用〈存款〉。“还清”用于欠款，存款是存在银行里的钱，不能说还清。"}, {"text": "他身上只带了一些存款，还是没买到。", "explanation": "这里应该用〈现金〉。存款存在银行里，不能随身带。"}, {"text": "他向银行借了一笔存款，还是没买到。", "explanation": "这里应该用〈借款〉。存款是自己存进银行的钱，不能向银行借。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b74e1261-5f5f-425d-9d1e-d585592b8400') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95521, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把一只存款放在银行里。", "corrected_sentence": "我把一笔存款放在银行里。", "error_description": "错误：“一只存款”。存款的量词应为“笔”，应说“一笔存款”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b74e1261-5f5f-425d-9d1e-d585592b8400') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95521, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想知道卡里还有多少只存款。", "corrected_sentence": "我想知道卡里还有多少存款。", "error_description": "错误：“多少只存款”。正确：“多少存款”。“存款”不用“只”作量词，计量时应用“笔”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b74e1261-5f5f-425d-9d1e-d585592b8400') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
